(237, 3994, 'a:13:{s:12:"cfdb7_status";s:6:"unread";s:17:"pum_form_popup_id";s:4:"3993";s:4:"Name";s:8:"Иван";s:5:"Email";s:22:"product_202@aquario.ru";s:5:"Phone";s:12:"+79855119889";s:7:"Company";s:19:"ООО ИНВЕСТ";s:7:"Messege";s:96:"Требуется 5 столешниц из фторопласта размером 2820*700*40";s:6:"source";s:31:"Страница товаров";s:3:"ref";s:38:"https:&#047;&#047;www.google.com&#047;";s:4:"Urls";s:74:"https:&#047;&#047;ftoroplast.com.ru&#047;products&#047;uhmwpe-plates&#047;";s:3:"tvr";s:42:"Пластины из СВМПЭ (PE-1000)";s:11:"check_field";s:1:"1";s:4:"File";s:0:"";}', '2018-12-29 10:42:20'),
