(577, 'rttheme18_templateid_334065_footer_output', '[footer selector_class="footer-334065"][/footer]', 'yes'),
(578, 'rttheme18_templateid_334065_content_output', '[row full_width_row="" row_counter=1 page_title="" breadcrumb="on" breadcrumb_position="inside_content" id="row-334065-1" sidebar_selection = "full" sidebar_id = "" paddings = "" class="" css_class="" parallax_background="disabled_parallax" background_image_url = ""][rt_columns][rt_column layout="one"][text_box id="text-box-334065-117564"]<h1>КОНТАКТЫ</h1>[/text_box][tabs tabs_style="horizontal" tab1="ГЛАВНЫЙ ОФИС" tab1_icon="icon-building" tab2="ОФИС В МОСКВЕ" tab2_icon="icon-building" tab3="ОФИС И СКЛАД В НОВОСИБИРСКЕ" tab3_icon="icon-building" ] [tab]<div class="box three ">\r\n<h3 class="featured_article_title">Главный офис</h3>\r\n<div class="space margin-b20"> </div>\r\n<ul class="with_icons colored " data-rt-animation-group="group">\r\n<li class="box one first last fadeInDown animated" style="animation-delay: 0s;" data-rt-animate="animate" data-rt-animation-type="fadeInDown">\r\n<p>Санкт-Петербург, Липовая аллея д.9, лит. А, пом. 14Н</p>\r\n</li>\r\n<li class="spb-phone box one first last fadeInDown animated" style="animation-delay: 0.1s;" data-rt-animate="animate" data-rt-animation-type="fadeInDown">\r\n<p><a href="tel:+78123247535">+7 (812) 324-75-35</a></p>\r\n</li>\r\n<li class="spb-phone box one first last fadeInDown animated" style="animation-delay: 0.2s;" data-rt-animate="animate" data-rt-animation-type="fadeInDown">\r\n<p><a href="tel:+78123272776">+7 (812) 327-27-76</a></p>\r\n</li>\r\n<li class="email-address box one first last fadeInDown animated" style="animation-delay: 0.3s;" data-rt-animate="animate" data-rt-animation-type="fadeInDown">\r\n<p><a href="mailto:info@ftoroplast.com.ru">info@ftoroplast.com.ru</a></p>\r\n</li>\r\n<li class="email-address box one first last fadeInDown animated" style="animation-delay: 0.4s;" data-rt-animate="animate" data-rt-animation-type="fadeInDown">\r\n<p><a href="mailto:support@ftoroplast.com.ru">support@ftoroplast.com.ru</a></p>\r\n</li>\r\n</ul>\r\n<h3 class="featured_article_title">Место расположения склада</h3>\r\n<div class="space margin-b20"> </div>\r\n<ul class="with_icons colored " data-rt-animation-group="group">\r\n<li class="box one first last fadeInDown animated" style="animation-delay: 0s;" data-rt-animate="animate" data-rt-animation-type="fadeInDown">\r\n<p>194100 г. Санкт-Петербург, ул. Ал. Матросова, д.4, кор. 2, лит. Л</p>\r\n</li>\r\n<li class="box one first last fadeInDown animated" style="animation-delay: 0.1s;" data-rt-animate="animate" data-rt-animation-type="fadeInDown">\r\n<p>Въезд и вход на производственно-складской комплекс «Оккервиль» с Выборгской набережной, 55.</p>\r\n</li>\r\n<li class="box one first last fadeInDown animated" style="animation-delay: 0.2s;" data-rt-animate="animate" data-rt-animation-type="fadeInDown">\r\n<p>Для получения продукции требуется доверенность, дни для самовывоза вторник, четверг. Склад работает с 9.00 до 17.00 перерыв с 12.00 до 13.00.</p>\r\n</li>\r\n</ul>\r\n</div>\r\n<div class="box two-three ">\r\n<div id="wpcf7-f2690-o1" class="wpcf7" dir="ltr" lang="ru-RU" role="form">\r\n<div class="screen-reader-response"> </div>\r\n[contact-form-7 id="2690" city="Санкт-Петербург" source="Страница ''контакты''" title="Контактная форма 1"]</div>\r\n</div>\r\n<div class="box one">\r\n<p> <br /><script type="text/javascript" charset="utf-8" async src="https://api-maps.yandex.ru/services/constructor/1.0/js/?um=constructor%3Aa83b30f4d38a687f0a834b4941e4bc43a629e41ed88ea4131cac755bdd8efef5&width=100%25&height=400&lang=ru_RU&scroll=true"></script></p>\r\n</div>[/tab][tab]<div class="box three ">\r\n<h3 class="featured_article_title">Представительство в Москве</h3>\r\n<div class="space margin-b20"> </div>\r\n<ul class="with_icons colored " data-rt-animation-group="group">\r\n<li class="box one first last fadeInDown animated" style="animation-delay: 0s;" data-rt-animate="animate" data-rt-animation-type="fadeInDown">\r\n<p>109382, г. Москва, ул. Нижние Поля, д. 31, оф. 413</p>\r\n</li>\r\n<li class="moscow-phone box one first last fadeInDown animated" style="animation-delay: 0.1s;" data-rt-animate="animate" data-rt-animation-type="fadeInDown">\r\n<p><a href="tel:+74993578200">+7 (499) 357-82-00</a></p>\r\n</li>\r\n<li class="moscow-phone box one first last fadeInDown animated" style="animation-delay: 0.2s;" data-rt-animate="animate" data-rt-animation-type="fadeInDown">\r\n<p><a href="tel:+74955185718">+7 (495) 518-57-18</a></p>\r\n</li>\r\n<li class="email-address box one first last fadeInDown animated" style="animation-delay: 0.3s;" data-rt-animate="animate" data-rt-animation-type="fadeInDown">\r\n<p><a href="mailto:info@ftoroplast.com.ru">info@ftoroplast.com.ru</a></p>\r\n</li>\r\n</ul>\r\n</div>\r\n<div class="box two-three ">\r\n<div id="wpcf7-f2690-o1" class="wpcf7" dir="ltr" lang="ru-RU" role="form">\r\n<div class="screen-reader-response"> </div>\r\n[contact-form-7 id="2690" city="Москва" source="Страница ''контакты''" title="Контактная форма 1"]</div>\r\n</div>\r\n<div class="box one">\r\n<p> <br /><script type="text/javascript" charset="utf-8" async src="https://api-maps.yandex.ru/services/constructor/1.0/js/?um=constructor%3A5440b99a19ef25d4538ebe175107f2717b666dfe52d7eeedcda9e6dc3316dfec&width=100%25&height=400&lang=ru_RU&scroll=true"></script></p>\r\n</div>[/tab][tab]<div class="box three ">\r\n<h3 class="featured_article_title">Офис и склад в Новосибирске</h3>\r\n<div class="space margin-b20"> </div>\r\n<ul class="with_icons colored " data-rt-animation-group="group">\r\n<li class="box one first last fadeInDown animated" style="animation-delay: 0s;" data-rt-animate="animate" data-rt-animation-type="fadeInDown">\r\n<p>г. Новосибирск, ул. Кирова, д. 278, лит. И-2.0</p>\r\n</li>\r\n<li class="novosib-phone box one first last fadeInDown animated" style="animation-delay: 0.1s;" data-rt-animate="animate" data-rt-animation-type="fadeInDown">\r\n<p><a href="tel:+73833622772">+7 (383) 362-27-72</a></p>\r\n</li>\r\n<li class="email-address box one first last fadeInDown animated" style="animation-delay: 0.3s;" data-rt-animate="animate" data-rt-animation-type="fadeInDown">\r\n<p><a href="mailto:info@ftoroplast.com.ru">info@ftoroplast.com.ru</a></p>\r\n</li>\r\n</ul>\r\n</div>\r\n<div class="box two-three ">\r\n<div id="wpcf7-f2690-o1" class="wpcf7" dir="ltr" lang="ru-RU" role="form">\r\n<div class="screen-reader-response"> </div>\r\n[contact-form-7 id="2690" city="Новосибирск" source="Страница ''контакты''" title="Контактная форма 1"]</div>\r\n</div>\r\n<div class="box one">\r\n<p> <br /><script type="text/javascript" charset="utf-8" async src="https://api-maps.yandex.ru/services/constructor/1.0/js/?um=constructor%3A06d42bed5f46b6902a992ea7ef2f318d1f4742c56ad98efb8ebf72f2e9aaeebd&width=100%25&height=400&lang=ru_RU&scroll=true"></script></p>\r\n</div>[/tab][/tabs][/rt_column][/rt_columns][/row]', 'yes');
