(665, 'rttheme18_templateid_673265_header_output', '[header selector_class="header-673265" header_options="" breadcrumb="" page_title="" breadcrumb_position="inside_content"][space_box id="space-673265-106576" height="32"][rev_slider demo-slider][/header]', 'yes'),
(666, 'rttheme18_templateid_673265_footer_output', '[footer selector_class="footer-673265"][rt_columns][horizontal_line group_id="118041" content_type="horizontal_line" style="7" margin_top="0" margin_bottom="40" ][/rt_columns][rt_columns][banner id="banner-673265-1146006" gradient="" border="" text_icon="" text_alignment="left" button_text="Задать вопрос" button_icon="icon-comment-empty" button_link="#modal" button_size="big" link_target="_self"]Приглашаем воспользоваться нашим отделом консалтинга\r\n<small>ЗАО Фторопластовые технологии оказывает услуги консультирования по любым вопросам, связанным с фторопластом.</small>[/banner][/rt_columns][space_box id="space-673265-136947" height="35"][/footer]', 'yes');
INSERT INTO `fttwp_options` (`option_id`, `option_name`, `option_value`, `autoload`) VALUES
(667, 'rttheme18_templateid_673265_content_output', '[row full_width_row="" row_counter=1 page_title="" breadcrumb="" breadcrumb_position="inside_content" id="row-673265-1" sidebar_selection = "full" sidebar_id = "" paddings = "" class="" css_class="" parallax_background="disabled_parallax" background_image_url = ""][rt_columns][text_box id="text-box-673265-4007"]<h2 style=\\"text-align: center;\\">НАША <span style=\\"color: #02aadb;\\">ПРОДУКЦИЯ</span></h2>[/text_box][/rt_columns][rt_columns][horizontal_line group_id="108843" content_type="horizontal_line" style="6" margin_top="0" margin_bottom="0" ][/rt_columns][space_box id="space-673265-113587" height="60"][rt_columns][rt_column layout="four"][content_box id="content-box-673265-98562" title="ЗАГОТОВКИ ИЗ ФТОРОПЛАСТА-4" title_position="after" featured_image="https://ftoroplast.com.ru/wp-content/uploads/2018/04/12.jpg" image_style="1" icon="" icon_style="0" text_position="2" link="/product-category/provisions/ptfe/" link_text="" link_target="_self"]<p><span style=\\"font-weight: 400;\\">ЗАО “Фторопластовые технологии” производит широкий ассортимент стандартных заготовок и расходных материалов из фторопласта: пластины, стержни, втулки, лист строганный, трубка Ф-4Д, лента ФУМ, профили, кубики и др.</span></p>[/content_box][/rt_column][rt_column layout="four"][content_box id="content-box-673265-171320" title="ФТОРОПЛАСТОВЫЕ КОМПОЗИЦИИ" title_position="after" featured_image="https://ftoroplast.com.ru/wp-content/uploads/2018/07/10.jpg" image_style="1" icon="" icon_style="0" text_position="2" link="/product-category/provisions/compounds/" link_text="" link_target="_self"]<p><span style=\\"font-weight: 400;\\">Наша компания предлагает самый широкий выбор изделий из композиционных материалов на основе фторопласта-4 российского производства. Помимо известных марок, таких как Ф4К20 м Ф4К15М5, мы наладили производство нескольких десятков уникальных композиций с применением углеволокна, графита, стекловолокна, металлов.</span></p>[/content_box][/rt_column][rt_column layout="four"][content_box id="content-box-673265-28684" title="ИЗДЕЛИЯ ПО ЧЕРТЕЖАМ ЗАКАЗЧИКА" title_position="after" featured_image="https://ftoroplast.com.ru/wp-content/uploads/2018/06/28.jpg" image_style="1" icon="" icon_style="0" text_position="2" link="/product-category/parts/" link_text="" link_target="_self"]<p>Предлагаем комплекс инжиниринговых услуг полного цикла: от запроса — до готового изделия. Помогаем в подборе материала, разработке конструкторской документации. Выполняем заказы любой сложности.</p>[/content_box][/rt_column][rt_column layout="four"][content_box id="content-box-673265-32044" title="ВОЕННО-ТЕХНИЧЕСКАЯ ПРИЁМКА" title_position="after" featured_image="https://ftoroplast.com.ru/wp-content/uploads/2018/04/4.jpg" image_style="1" icon="" icon_style="0" text_position="2" link="/products/tehpriemka/" link_text="" link_target="_self"]<p><span style=\\"font-weight: 400;\\">Наличие на нашем предприятии аккредитованной лаборатории позволяет изготавливать заготовки по ОСТ В-6-05-5022-81 — 1 и 2 сорта, а также заготовки по ТУ 6-05-810-88 – высший и 1 сорт.</span></p>[/content_box][/rt_column][/rt_columns][/row][row full_width_row="" row_counter=2 page_title="" breadcrumb="" breadcrumb_position="inside_content" id="row-673265-2" sidebar_selection = "full" sidebar_id = "" paddings = "" class="row-style-2" css_class="" parallax_background="disabled_parallax" background_image_url = ""][rt_columns][horizontal_line group_id="39088" content_type="horizontal_line" style="7" margin_top="0" margin_bottom="0" ][/rt_columns][rt_columns][rt_column layout="two"][space_box id="space-673265-90096" height="25"][text_box id="text-box-673265-148820"]<h2 style=\\"text-align: center;\\"><b>ВЫГОДЫ ОТ СОТРУДНИЧЕСТВА С НАМИ</b></h2>\r\n<p> </p>[/text_box][icon_list title="" icon_style="colored big_icons icon_borders" item_width="2"][icon_list_line icon="icon-cog"]Выполняем заказы от 1 штуки до нескольких миллионов изделий.[/icon_list_line][icon_list_line icon="icon-truck"]Обеспечиваем наличие на складе запаса стандартных позиций, готовых к отгрузке.[/icon_list_line][icon_list_line icon="icon-lightbulb"]Обладая знаниями и многолетним опытом в обработке фторопласта-4, консультируем и предлагаем оптимальное решение задачи любой сложности.[/icon_list_line][icon_list_line icon="icon-temperatire"]Благодаря собственной аккредитованной лаборатории, производим продукцию, соответствующую требованиям конструкторской документации.[/icon_list_line][/icon_list][/rt_column][rt_column layout="two"][text_box id="text-box-673265-84023"]<p> </p>\r\n<p><img class=\\"alignnone wp-image-2791 size-full\\" src=\\"https://ftoroplast.com.ru/wp-content/uploads/2018/04/laptop.png\\" alt=\\"\\" width=\\"488\\" height=\\"333\\" /></p>\r\n<p> </p>[/text_box][/rt_column][/rt_columns][/row][row full_width_row="" row_counter=3 page_title="" breadcrumb="" breadcrumb_position="inside_content" id="row-673265-149190" sidebar_selection = "full" sidebar_id = "" paddings = "" class="" css_class="" parallax_background="disabled_parallax" background_image_url = ""][rt_columns][rt_column layout="one"][space_box id="space-673265-79099" height="25"][text_box id="text-box-673265-51930"]<h2>КАК МЫ РАБОТАЕМ</h2>\r\n<p> </p>[/text_box][icon_list title="" icon_style="colored big_icons icon_borders" item_width="4"][icon_list_line icon="icon-right-hand"]1. Запрос от заказчика[/icon_list_line][icon_list_line icon="icon-angle-double-right"]2. Согласование техзадания, условий поставки[/icon_list_line][icon_list_line icon="icon-angle-double-right"]3. Производство заказа[/icon_list_line][icon_list_line icon="icon-angle-double-right"]4. Отгрузка[/icon_list_line][/icon_list][/rt_column][/rt_columns][rt_columns][rt_column layout="two"][icon_list title="" icon_style="colored" item_width="1"][icon_list_line icon="icon-ok-circle"]Работаем как по предоплате, так и с отсрочкой платежа.[/icon_list_line][icon_list_line icon="icon-ok-circle"]Возможен самовывоз по согласованию[/icon_list_line][icon_list_line icon="icon-ok-circle"]Доставка продукции от складов до терминалов ГК “Деловые линии” в Санкт-Петербурге и Новосибирске бесплатна[/icon_list_line][/icon_list][/rt_column][rt_column layout="two"][icon_list title="" icon_style="colored" item_width="1"][icon_list_line icon="icon-ok-circle"]Отгрузочные дни со склада в г. Санкт-Петербурге по вторникам и четвергам*[/icon_list_line][icon_list_line icon="icon-ok-circle"]Отгрузочные дни со склада в г. Новосибирске с понедельника по пятницу*[/icon_list_line][icon_list_line icon=""]*за исключением праздничных дней[/icon_list_line][/icon_list][/rt_column][/rt_columns][/row][row full_width_row="" row_counter=4 page_title="" breadcrumb="" breadcrumb_position="inside_content" id="row-673265-163500" sidebar_selection = "full" sidebar_id = "" paddings = "" class="" css_class="" parallax_background="disabled_parallax" background_image_url = ""][rt_columns][rt_column layout="two-three"][heading_bar group_id="686034" content_type="heading_bar" heading="О КОМПАНИИ" icon="icon-chart-line" style="" ][text_box id="text-box-673265-319345"]<p><span style=\\"font-weight: 400;\\">ЗАО “Фторопластовые технологии”, начав свою работу в 2001 году, стало одним из немногочисленных предприятий-переработчиков политертафторэтилена (фторопласта-4) и на сегодняшний день занимает прочные лидирующие позиции среди производителей как заготовок, так и готовых изделий из фторопласта-4 в России. Обладая кадровым и интеллектуальным потенциалом, наша компания успешно осваивает и внедряет новые и уникальные композиционные материалы на основе фторопласта-4, работает над расширением ассортимента выпускаемой продукции, качеством конечного продукта и обслуживания клиентов.</span></p>\r\n<p><span style=\\"font-weight: 400;\\">В 2012 году было учреждено ООО “Торговый дом “Фторопластовые технологии” — компания, являющаяся официальным дистрибьютором завода-производителя и специализирующаяся на сбыте производимых заготовок и расходных материалов из фторопласта-4. За 5 лет работы было продано около 2 000 000 кг продукции, и наша компания продолжает набирать обороты на рынках России и СНГ.</span></p>[/text_box][space_box id="space-673265-54098" height="20"][/rt_column][rt_column layout="three"][blog_carousel id="blog-carousel-673265-134887" crop="on" style="plain_carousel" heading="СВЕЖИЕ НОВОСТИ" heading_icon="icon-doc-alt" item_width="1" list_orderby="date" list_order="DESC" max_item="4" categories="42" ids="" display_excerpts="on" limit_chars="480"][/rt_column][/rt_columns][/row]', 'yes'),
