ia.com/v4/updates/1362246/assets/icon-128x128.png";s:2:"2x";s:79:"https://repository.kreaturamedia.com/v4/updates/1362246/assets/icon-256x256.png";s:7:"default";s:79:"https://repository.kreaturamedia.com/v4/updates/1362246/assets/icon-256x256.png";}s:7:"banners";a:3:{s:3:"low";s:84:"https://repository.kreaturamedia.com/v4/updates/1362246/assets/thumbnail-772x250.png";s:4:"high";s:85:"https://repository.kreaturamedia.com/v4/updates/1362246/assets/thumbnail-1544x500.png";s:7:"default";s:85:"https://repository.kreaturamedia.com/v4/updates/1362246/assets/thumbnail-1544x500.png";}s:8:"sections";a:3:{s:9:"changelog";s:130:"<p style="text-align: justify;">\n	See the release log in the ''LayerSlider News'' section at the bottom of its main admin page.\n</p>";s:12:"installation";s:456:"<p style="text-align: justify;">\n	Updating the plugin won''t touch your sliders and settings and the new version always has backward compatibility,\n	so you don''t have to worry about losing your work. Depending of the default settings, you may\n	have to adjust some options to get the new features. If you are experience unwanted behavior changes, it is always a\n	good idea to check your settings, there are probably new options to control these changes.\n</p>";s:3:"faq";s:595:"<p style="text-align: justify;">\n	Before contacting us, please read our <a href="http://support.kreaturamedia.com/faq/4/layerslider-for-wordpress/" target="_blank">online FAQs</a>, or check the built-in documentation in the contextual Help menu on the top-right corner of the page. Please note, these Help menus are contextual, they will show you different content on different pages.\n</p>\n\n<p style="text-align: justify;">\n	If you couldn''t find an answer for your question, you can write us a comment at the Item''s page on CodeCanyon, or send us an email from our CodeCanyon profile page.\n</p>\n";}s:4:"slug";s:11:"LayerSlider";s:7:"package";s:0:"";s:13:"download_link";s:0:"";}s:15:"_latest_version";s:5:"6.7.6";s:7:"checked";i:1547092267;}', 'yes'),
