INSERT INTO `fttwp_options` (`option_id`, `option_name`, `option_value`, `autoload`) VALUES
(45502, 'rttheme18_templateid_293744', '', 'yes'),
(45503, 'rttheme18_templateid_293744_header_output', '[header selector_class="header-293744" header_options="" breadcrumb="on" page_title="on" breadcrumb_position="inside_header"][/header]', 'yes'),
(45504, 'rttheme18_templateid_293744_footer_output', '[footer selector_class="footer-293744"][/footer]', 'yes'),
(45505, 'rttheme18_templateid_293744_content_output', '[row full_width_row="" row_counter=1 page_title="on" breadcrumb="on" breadcrumb_position="inside_header" id="row-293744-1" sidebar_selection = "full" sidebar_id = "" paddings = "" class="" css_class="" parallax_background="disabled_parallax" background_image_url = ""][rt_columns][text_box id="text-box-293744-107062"]<h2><b>Чем мы занимаемся</b></h2>\r\n<p><span style=\\"font-weight: 400;\\">Основной деятельностью ЗАО «Фторопластовые технологии» является переработка политетрафторэтилена и производство фторопластовой продукции. </span></p>\r\n<p><span style=\\"font-weight: 400;\\">Обладая современными производственными мощностями, наше предприятие предоставляет услуги полного цикла: от создания заготовок из фторопластового порошка до готовых технологичных изделий высокого качества, применяемых во многих отраслях промышленности.</span></p>\r\n<p> </p>\r\n<h2><b>Немного истории</b></h2>\r\n<p><span style=\\"font-weight: 400;\\">Основанная в декабре 2001 года, наша компания начинала свой путь с нескольких обрабатывающих станков и небольшой команды специалистов. Приобретая опыт и завоевывая клиентов, </span><span style=\\"font-weight: 400;\\">ЗАО «Фторопластовые технологии» взяло курс на освоение новых для себя технологий и расширение ассортимента выпускаемой продукции: так появились производственные участки прессования, </span><span style=\\"font-weight: 400;\\">экструзии, каландрирования, был модернизирован участок механической обработки высокопроизводительными станками с ЧПУ. </span></p>\r\n<p><span style=\\"font-weight: 400;\\">Благодаря новому оборудованию и новым специалистам, компания начала расти, стали открываться обособленные подразделения в городах. На сегодняшний день мы представлены в трех городах России: г. Санкт-Петербурге (главный офис, производство и склад), г. Москве (офис) и г. Новосибирске (офис и склад). </span></p>\r\n<p><span style=\\"font-weight: 400;\\">В 2012 году было учреждено ООО “Торговый дом Фторопластовые технологии” (ООО “ТД ФТТ”), позиционирующееся как официальный дистрибьютор завода-производителя и поставщик заготовок из фторопласта-4, композиционных материалов и других инженерных пластиков. В целях оптимизации бизнес-процессов компании было внедрено программное обеспечение на базе технологий SAP, что позволяет нам держать уверенный курс на освоение рынков России и СНГ.</span></p>\r\n<p> </p>\r\n<h2><b>Основные направления деятельности</b></h2>[/text_box][/rt_columns][rt_columns][rev_slider O-nas-1][/rt_columns][rt_columns][text_box id="text-box-293744-119332"]<p> </p>\r\n<p><span style=\\"font-weight: 400;\\">На сегодняшний день ЗАО «Фторопластовые технологии» развивается в двух продуктовых направлениях: </span></p>\r\n<h3><b>1. Производство заготовок из фторопласта и композиций на его основе</b></h3>\r\n<p><span style=\\"font-weight: 400;\\">Для успешной и продуктивной работы собственными усилиями компании были созданы производственные участки:</span></p>\r\n<ul>\r\n<li style=\\"font-weight: 400;\\"><span style=\\"font-weight: 400;\\">прессования, участка по выпуску заготовок (стержней, втулок, колец, пластин) из фторопласта 4 и композиций на его основе</span></li>\r\n<li style=\\"font-weight: 400;\\"><span style=\\"font-weight: 400;\\">смешения масс для создания новых композиций на основе фторопласта 4</span></li>\r\n<li style=\\"font-weight: 400;\\"><span style=\\"font-weight: 400;\\">экструзии фторопласта-4Д для получением труб и трубок</span></li>\r\n<li style=\\"font-weight: 400;\\"><span style=\\"font-weight: 400;\\">экструзии и каландрирования для выпуска фторопластовых уплотнительных жгутов, ленты ФУМ-1</span></li>\r\n</ul>\r\n<p><span style=\\"font-weight: 400;\\">Кроме того, мы принимаем заказы на поставку заготовок из:</span></p>\r\n<ul>\r\n<li style=\\"font-weight: 400;\\"><span style=\\"font-weight: 400;\\">Капролона (Полиамида-6 блочного)</span></li>\r\n<li style=\\"font-weight: 400;\\"><span style=\\"font-weight: 400;\\">Полиэтилена низкого давления (ПНД)</span></li>\r\n<li style=\\"font-weight: 400;\\"><span style=\\"font-weight: 400;\\">Сверхвысокомолекулярного полиэтилена (СВМПЭ)</span></li>\r\n<li style=\\"font-weight: 400;\\"><span style=\\"font-weight: 400;\\">Полиэфирэфиркетона (РЕЕК)</span></li>\r\n</ul>[/text_box][/rt_columns][rt_columns][rev_slider o-nas-2][/rt_columns][rt_columns][text_box id="text-box-293744-178818"]<h3> </h3>\r\n<h3><b>2. Производство полимерных изделий по чертежам заказчика</b></h3>\r\n<p><span style=\\"font-weight: 400;\\">представлено производственными участками:</span></p>\r\n<ul>\r\n<li style=\\"font-weight: 400;\\"><span style=\\"font-weight: 400;\\">по механической обработке заготовок из фторопласта с внедрением оборудования с ЧПУ</span></li>\r\n<li style=\\"font-weight: 400;\\"><span style=\\"font-weight: 400;\\">по производству строганной ленты и профиля</span></li>\r\n<li style=\\"font-weight: 400;\\"><span style=\\"font-weight: 400;\\">по выпуску готовых деталей методом </span><span style=\\"font-weight: 400; color: #ff0000;\\">автоматического прессования</span></li>\r\n</ul>\r\n<p><span style=\\"font-weight: 400; color: #ff0000;\\">На данном этапе предлагаем изготовление деталей как из новых и самых современных, так и хорошо известных конструкционных пластмасс:</span></p>\r\n<ul>\r\n<li style=\\"font-weight: 400;\\"><span style=\\"font-weight: 400;\\">Капролон (Полиамид-6) и его модификации</span></li>\r\n<li style=\\"font-weight: 400;\\"><span style=\\"font-weight: 400;\\">Полиоксиметилен (ПОМ)</span></li>\r\n<li style=\\"font-weight: 400;\\"><span style=\\"font-weight: 400;\\">Полиэтилентерафталат (РЕТ)</span></li>\r\n<li style=\\"font-weight: 400;\\"><span style=\\"font-weight: 400;\\">Высокомолекулярный  полиэтилен РЕ-500</span></li>\r\n<li style=\\"font-weight: 400;\\"><span style=\\"font-weight: 400;\\">Сверхвысокомолекулярный полиэтилен РЕ-1000</span></li>\r\n</ul>\r\n<p><span style=\\"font-weight: 400;\\">ЗАО “Фторопластовые технологии” обладает многолетним опытом в изготовлении уплотнений (седла, кольца, прокладки) на запорно-регулирующую арматуру (кран шаровый, заслонки поворотные химические, клапаны обратные химические) от Ду 20 до Ду 500. Также мы изготавливаем уплотнения и детали (кольца нажимные, кольца опорные, кольца уплотнительные, манжеты) для пищевой промышленности, нефтегазоперерабатывающей промышленности, приборостроения.</span></p>\r\n<p>&nbsp;</p>\r\n<h2><b>Гарантии качества</b></h2>\r\n<p><span style=\\"font-weight: 400;\\">Все изделия, выпускаемые ЗАО “Фторопластовые технологии”, изготавливаются в соответствии с ТУ, ГОСТ, ОСТ и соответствуют государственным санитарно-эпидемиологическим правилам и нормативам. Качество продукции обеспечивается отлаженной работой ОТК, собственной аккредитованной лабораторией и подтверждается паспортами качества.</span></p>\r\n<p>&nbsp;</p>\r\n<h2><b>Экспертность в инженерном консалтинге</b></h2>\r\n<p><span style=\\"font-weight: 400;\\">Нашей отличительной особенностью является сочетание фундаментальных научных наработок прошлого, применение лучших бизнес-практик современности и ориентация на высокие технологии будущего.</span> <span style=\\"font-weight: 400;\\">Мы помогаем нашим клиентам в подборе материалов с целью минимизации затрат на механическую обработку. Специалисты нашей компании с удовольствием проконсультируют вас по вопросам применения фторопласта, композиционных материалов и других промышленных полимеров. Отправьте запрос прямо сейчас, и мы поможем решить вашу задачу!</span></p>[/text_box][/rt_columns][rt_columns][horizontal_line group_id="155683" content_type="horizontal_line" style="7" margin_top="0" margin_bottom="40" ][/rt_columns][rt_columns][banner id="banner-293744-116199" gradient="" border="" text_icon="" text_alignment="left" button_text="Задать вопрос" button_icon="icon-comment-empty" button_link="#modal" button_size="big" link_target="_self"]Приглашаем воспользоваться нашим отделом консалтинга\r\n<small>ЗАО Фторопластовые технологии оказывает услуги консультирования по любым вопросам, связанным с фторопластом.</small>[/banner][/rt_columns][space_box id="space-293744-178579" height="35"][/row]', 'yes'),
(45506, 'rttheme18_templateid_293744_css_output', 'a:4:{s:10:"color_sets";a:3:{i:0;a:3:{s:9:"container";s:19:"body .header-293744";s:9:"selection";s:6:"header";s:6:"values";a:0:{}}i:1;a:3:{s:9:"container";s:13:"#row-293744-1";s:9:"selection";s:3:"ca1";s:6:"values";a:0:{}}i:2;a:3:{s:9:"container";s:30:"body #container .footer-293744";s:9:"selection";s:6:"footer";s:6:"values";a:0:{}}}s:11:"backgrounds";a:3:{i:0;a:3:{s:9:"container";s:19:"body .header-293744";s:9:"selection";s:6:"header";s:6:"values";a:0:{}}i:1;a:3:{s:9:"container";s:13:"#row-293744-1";s:9:"selection";s:3:"ca1";s:6:"values";a:0:{}}i:2;a:3:{s:9:"container";s:30:"body #container .footer-293744";s:9:"selection";s:6:"footer";s:6:"values";a:0:{}}}s:9:"css_codes";s:210:"#row-293744-1 { padding-top: 20px; }#row-293744-1 { padding-bottom: 20px; }@media only screen and (max-width: 767px) { #row-293744-1 { padding-left: 0px; padding-right: 0px; } }#space-293744-178579{height:35px}";s:5:"fonts";a:0:{}}', 'yes'),
