(97460, 'rs-templates', 'a:2:{s:6:"slider";a:233:{i:0;a:20:{s:2:"id";s:1:"1";s:5:"title";s:16:"Classic Carousel";s:5:"alias";s:16:"classic-carousel";s:3:"zip";s:20:"classic-carousel.zip";s:3:"uid";s:32:"146a01dd380c0cdee85c4456ee68cd84";s:3:"img";s:27:"classic-carousel/slider.jpg";s:7:"preview";s:56:"http://revolution.themepunch.com/carousel-slider-plugin/";s:7:"version";s:5:"1.0.0";s:8:"required";s:5:"5.0.5";s:5:"width";s:4:"1240";s:6:"height";s:3:"600";s:11:"description";s:141:"<span class="ttm_content">Our classic, full-width carousel example. Drag, swipe or click to navigate!</span>\r\n<span class="ttm_space"></span>";s:11:"setup_notes";s:310:"<span class="ttm_content">This is a "Default" content carousel. Just edit the slides to change images and texts.<br/><br/></span>\r\n<span class="ttm_content">Checkout our <a href="https://www.themepunch.com/revslider-doc/slider-revolution-documentation/" target="_blank">Documentation</a> for basic help.</span>";s:3:"cat";s:15:"Revolution Base";s:6:"filter";a:1:{i:0;s:8:"carousel";}s:14:"plugin_require";N;s:4:"date";s:19:"2016-02-22 13:21:33";s:13:"package_order";s:1:"0";s:6:"active";s:1:"1";s:9:"installed";b:0;}i:1;a:20:{s:2:"id";s:1:"2";s:5:"title";s:14:"Classic Slider";s:5:"alias";s:13:"classicslider";s:3:"zip";s:17:"classicslider.zip";s:3:"uid";s:32:"a0d6a9248c9066b404ba0f1cdadc5cf2";s:3:"img";s:24:"classicslider/slider.jpg";s:7:"preview";s:61:"http://revolution.themepunch.com/wordpress-slideshow-gallery/";s:7:"version";s:5:"1.0.0";s:8:"required";s:5:"5.0.5";s:5:"width";s:4:"1240";s:6:"height";s:3:"600";s:11:"description";s:136:" <span class="ttm_content">A classic slideshow example with timer, bullets and arrow navigation.</span>\r\n<span class="ttm_space"></span>";s:11:"setup_notes";s:308:"<span class="ttm_content">This is a "Default" content slider. Just edit the slides to change images and texts.<br/><br/></span>\r\n<span class="ttm_content">Checkout our <a href="https://www.themepunch.com/revslider-doc/slider-revo