(98869, '_transient_aioseop_feed', 'a:4:{i:0;a:4:{s:3:"url";s:62:"https://semperplugins.com/upgrading-to-2-9-seo-meta-disappear/";s:5:"title";s:72:"Upgrading to 2.9.x made your SEO meta section disappear? Read this post!";s:4:"date";s:13:"Oct 25th 2018";s:7:"content";s:131:"Hi friends,\nIn 2.9, several users reported in the community forums that the SEO section disappeared from their source code or ba...";}i:1;a:4:{s:3:"url";s:48:"https://semperplugins.com/new-robots-txt-module/";s:5:"title";s:52:"New Robots.txt module with Multisite Network support";s:4:"date";s:13:"Sep 17th 2018";s:7:"content";s:131:"Missed the release notes for All in One SEO Pack v2.7? Then you may not be aware that we&#8217;ve completely overhauled the Robo...";}i:2;a:4:{s:3:"url";s:60:"https://semperplugins.com/all-in-one-seo-pack-v2-8-released/";s:5:"title";s:33:"All in One SEO Pack v2.8 released";s:4:"date";s:13:"Sep 12th 2018";s:7:"content";s:131:"Earlier this week, we released All in One SEO Pack v2.8.  This major release includes both enhancements to existing features of...";}i:3;a:4:{s:3:"url";s:77:"https://semperplugins.com/missing-all-in-one-seo-pack-2-6-post-and-page-meta/";s:5:"title";s:50:"Missing All in One SEO Pack 2.6 post and page meta";s:4:"date";s:13:"May 29th 2018";s:7:"content";s:131:"If you updated to the latest version of All in One SEO Pack (2.6) for WordPress recently, you may have noticed what appears to ...";}}', 'no'),
