/11/wp-moscow-4-%d0%be%d0%b1%d1%81%d1%83%d0%b4%d0%b8%d0%bc-%d0%bd%d0%b0%d1%81%d1%82%d1%80%d0%be%d0%b9%d0%ba%d0%b8-%d1%82%d0%b5%d0%bc-%d0%b8-%d0%b4%d0%b8%d0%b7%d0%b0%d0%b9%d0%bd/";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:7:"pubDate";a:1:{i:0;a:5:{s:4:"data";s:31:"Fri, 09 Nov 2018 13:22:09 +0000";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:8:"category";a:2:{i:0;a:5:{s:4:"data";s:14:"Новости";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}i:1;a:5:{s:4:"data";s:25:"Общие вопросы";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:4:"guid";a:1:{i:0;a:5:{s:4:"data";s:32:"https://ru.wordpress.org/?p=2065";s:7:"attribs";a:1:{s:0:"";a:1:{s:11:"isPermaLink";s:5:"false";}}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:11:"description";a:1:{i:0;a:5:{s:4:"data";s:467:"Очередной митап по WordPress состоится в четверг 15 ноября. Запланировано два доклада: «Настройки темы: Customizer или Advanced Custom Fields?»Денис Янчевский «В чем отличие UX дизайна от UI дизайна?»Фёдор Гребенников Вход свободной по предварительной регистрации. Начало в 18.00.";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}s:32:"http://purl.org/dc/elements/1.1/";a:1:{s:7:"creator";a:1:{i:0;a:5:{s:4:"data";s:17:"Denis Yanchevskiy";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}s:40:"http://purl.org/rss/1.0/modules/content/";a:1:{s:7:"encoded";a:1:{i:0;a:5:{s:4:"data";s:646:"\n<p>Очередной митап по WordPress состоится в четверг 15 ноября.</p>\n\n\n\n<p>Запланировано два доклада:</p>\n\n\n\n<p><strong>«Настройки темы: Customizer или Advanced Custom Fields?»</strong><br>Денис Янчевский</p>\n\n\n\n<p><strong>«В чем отличие UX дизайна от UI дизайна?»</strong><br>Фёдор Гребенников</p>\n\n\n\n<p