(25906, 2821, '_aioseop_keywords', 'ФТТ бизнес успех'),
(25907, 2821, '_aioseop_description', '27-28 февраля 2013 года общероссийская общественная организация малого и среднего предпринимательства ОПОРА РОССИИ проводила масштабное событие для предпринимателей - Межрегиональный форум "Бизнес-Успех".'),
(25908, 2821, '_aioseop_title', 'ФТТ получает премию Бизнес-Успех'),
