(25918, 2818, '_aioseop_keywords', 'Фторопласт на каждом шагу'),
(25919, 2818, '_aioseop_description', 'В наше время фторопласт, давно перестал быть чем-то редким и недоступным. Сейчас его можно встретить буквально на каждом шагу. Например, люди, которые увлекаются велоспортом, наверняка слышали понятие "велокосметика", в это понятие вкладываются всевозможные средства для чистки и смазки разных частей велосипеда. '),
(25920, 2818, '_aioseop_title', 'Фторопласт на каждом шагу'),
(25926, 2816, '_aioseop_opengraph_settings', 'a:14:{s:32:"aioseop_opengraph_settings_title";s:0:"";s:31:"aioseop_opengraph_settings_desc";s:0:"";s:36:"aioseop_opengraph_settings_customimg";s:0:"";s:37:"aioseop_opengraph_settings_imagewidth";s:0:"";s:38:"aioseop_opengraph_settings_imageheight";s:0:"";s:32:"aioseop_opengraph_settings_video";s:0:"";s:37:"aioseop_opengraph_settings_videowidth";s:0:"";s:38:"aioseop_opengraph_settings_videoheight";s:0:"";s:35:"aioseop_opengraph_settings_category";s:8:"activity";s:34:"aioseop_opengraph_settings_section";s:0:"";s:30:"aioseop_opengraph_settings_tag";s:0:"";s:34:"aioseop_opengraph_settings_setcard";s:7:"summary";s:44:"aioseop_opengraph_settings_customimg_twitter";s:0:"";s:44:"aioseop_opengraph_settings_customimg_checker";s:1:"0";}'),
(25930, 2816, '_aioseop_keywords', 'фторопласт выписка гост'),
(25931, 2816, '_aioseop_description', 'В России фтропласт-4 производится в соответствии с ГОСТ 10007-80, который предусматривает выпуск нескольких марок фторопласта-4. С – марка предназначенная, для изготовления специзделий. Читать полностью.'),
(25932, 2816, '_aioseop_title', 'Фторопласт - выписка из ГОСТ'),
