(25991, 2840, '_aioseop_keywords', 'сап велогонка'),
(25992, 2840, '_aioseop_description', 'Сегодня, 1 августа стартовала велогонка Race Across Russia, не имеющая аналогов в мире. Более того стартовала она, всего несколько часов назад в 4-30 с красной площади. '),
(25993, 2840, '_aioseop_title', 'Велогонка RARU 2013 | ФТТ'),
