(26003, 2838, '_aioseop_keywords', 'ФТТ фишт'),
(26004, 2838, '_aioseop_description', 'К церемонии открытия и закрытия зимних Олимпийских игр в Сочи будет построен современный стадион "Фишт". На данный момент, проходят работы по строительству прозрачных навесов над западной и восточной трибуны.'),
(26005, 2838, '_aioseop_title', 'Современные материалы в строительстве | ФТТ'),
(26011, 2842, '_aioseop_opengraph_settings', 'a:14:{s:32:"aioseop_opengraph_settings_title";s:0:"";s:31:"aioseop_opengraph_settings_desc";s:0:"";s:36:"aioseop_opengraph_settings_customimg";s:0:"";s:37:"aioseop_opengraph_settings_imagewidth";s:0:"";s:38:"aioseop_opengraph_settings_imageheight";s:0:"";s:32:"aioseop_opengraph_settings_video";s:0:"";s:37:"aioseop_opengraph_settings_videowidth";s:0:"";s:38:"aioseop_opengraph_settings_videoheight";s:0:"";s:35:"aioseop_opengraph_settings_category";s:8:"activity";s:34:"aioseop_opengraph_settings_section";s:0:"";s:30:"aioseop_opengraph_settings_tag";s:0:"";s:34:"aioseop_opengraph_settings_setcard";s:7:"summary";s:44:"aioseop_opengraph_settings_customimg_twitter";s:0:"";s:44:"aioseop_opengraph_settings_customimg_checker";s:1:"0";}'),
(26015, 2842, '_aioseop_keywords', 'Фторопласт-3'),
(26016, 2842, '_aioseop_description', 'ЗАО "Фторопластовые технологии" может предложит услуги по изготовление изделий из фторопласта 3.'),
(26017, 2842, '_aioseop_title', 'Изготовление изделий из фторопласта-3 | ФТТ'),
(26023, 2844, '_aioseop_opengraph_settings', 'a:14:{s:32:"aioseop_opengraph_settings_title";s:0:"";s:31:"aioseop_opengraph_settings_desc";s:0:"";s:36:"aioseop_opengraph_settings_customimg";s:0:"";s:37:"aioseop_opengraph_settings_imagewidth";s:0:"";s:38:"aioseop_opengraph_settings_imageheight";s:0:"";s:32:"aioseop_opengraph_settings_video";s:0:"";s:37:"aioseop_opengraph_settings_videowidth";s:0:"";s:38:"aioseop_opengraph_settings_videoheight";s:0:"";s:35:"aioseop_opengraph_settings_category";s:8:"activity";s:34:"aioseop_opengraph_settings_section";s:0:"";s:30:"aioseop_opengraph_settings_tag";s:0:"";s:34:"aioseop_opengraph_settings_setcard";s:7:"summary";s:44:"aioseop_opengraph_settings_customimg_twitter";s:0:"";s:44:"aioseop_opengraph_settings_customimg_checker";s:1:"0";}'),
(26027, 2844, '_aioseop_keywords', 'попигайский кратер'),
(26028, 2844, '_aioseop_description', 'По словам академика Николая Похиленко, директора Института геологии и минералогии имени Соболева, алмазы, найденные на месторождении никакого отношения к ювелирным изделиям не имеют, тем не менее, они могут сделать революцию в других областях: "инструментальной, камнерезной и буровой промышленностях".'),
(26029, 2844, '_aioseop_title', 'Попигайский кратер | ФТТ'),
(26035, 2846, '_aioseop_opengraph_settings', 'a:14:{s:32:"aioseop_opengraph_settings_title";s:0:"";s:31:"aioseop_opengraph_settings_desc";s:0:"";s:36:"aioseop_opengraph_settings_customimg";s:0:"";s:37:"aioseop_opengraph_settings_imagewidth";s:0:"";s:38:"aioseop_opengraph_settings_imageheight";s:0:"";s:32:"aioseop_opengraph_settings_video";s:0:"";s:37:"aioseop_opengraph_settings_videowidth";s:0:"";s:38:"aioseop_opengraph_settings_videoheight";s:0:"";s:35:"aioseop_opengraph_settings_category";s:8:"activity";s:34:"aioseop_opengraph_settings_section";s:0:"";s:30:"aioseop_opengraph_settings_tag";s:0:"";s:34:"aioseop_opengraph_settings_setcard";s:7:"summary";s:44:"aioseop_opengraph_settings_customimg_twitter";s:0:"";s:44:"aioseop_opengraph_settings_customimg_checker";s:1:"0";}'),
(26039, 2846, '_aioseop_keywords', 'фторопласт аммофос'),
(26040, 2846, '_aioseop_description', 'ЗАО "Фторопластовые технологии" в декабре месяце на основании тендера сделала крупную поставку фторопластовых заготовок для ОАО "АММОФОС". По оценкам сотрудников компании Аммофос поставка фторполимерной продукции прошла успешно. Статус согласно системе рейтингов на площадке Tender.Pro "2(отлично)".'),
(26041, 2846, '_aioseop_title', 'Фторопласт АММОФОС | ФТТ'),
