(27500, 3771, 'slide_template', 'default'),
(27501, 3771, 'rtthemecustom_sidebar_position', ''),
(27526, 3771, '_aioseop_keywords', 'история фтт'),
(27527, 3771, '_aioseop_description', 'Компания «Фторопластовые технологии» берет свое начало еще в декабре 2001 года. Несколько станков и небольшой персонал начинал ковать нашу историю. Читать далее...'),
(27528, 3771, '_aioseop_title', 'История компании ФТТ'),
(27535, 2860, '_aioseop_keywords', 'вакансии фторопласт'),
(27536, 2860, '_aioseop_description', 'ЗАО Фторопластовые технологии приглашает на постоянную работу сотрудников с опытом работы по специальности.\r\n'),
(27537, 2860, '_aioseop_title', 'Вакансии | Фторопластовые технологи'),
