(27546, 3775, 'rtthemecustom_sidebar_position', ''),
(27550, 3775, '_aioseop_keywords', 'компания фтт'),
(27551, 3775, '_aioseop_description', 'ЗАО «Фторопластовые технологии»</strong> принимает заказы на поставку заготовок и изделий из капролона (полиамида 6 блочного), поставку деталей из высококачественных пластмасс, производства Бельгии.'),
(27552, 3775, '_aioseop_title', 'Компания Фторопластовые технологии'),
(27556, 1885, '_aioseop_keywords', 'персонал фтт, команда фтт'),
(27557, 1885, '_aioseop_description', 'Наши специалисты'),
(27558, 1885, '_aioseop_title', 'Персонал ЗАО Фторопластовые технологии'),
(27607, 3160, '_aioseop_keywords', 'производство фторопласта'),
(27608, 3160, '_aioseop_description', 'ЗАО "Фторопластовые технологии" - это широкий спектр инженерных решений для любого проекта, в том числе, разработка новых.'),
(27609, 3160, '_aioseop_title', 'Производство | Фторопластовые технологии'),
(27621, 2950, '_aioseop_keywords', 'Автоматическое прессование'),
(27622, 2950, '_aioseop_description', 'С появлением свободно сыпучих марок фторопласта -4 стало возможно объемное дозирование порошка в пресс-форму, что позволило перейти к созданию процесса автоматического прессования, в первую очередь для тех изделий, изготовление которых из заготовок механической обработкой давало большое количество отходов в виде стружки.'),
(27623, 2950, '_aioseop_title', 'Автоматическое прессование | Фторопластовые технологии'),
(27635, 2956, '_wp_old_slug', 'machine'),
(27664, 2956, '_aioseop_keywords', 'Обработка фторопласта, токарные работы, фрезерные работы'),
(27665, 2956, '_aioseop_description', 'Более 50% изделий из фторопласта -4 и композиций на его основе выпускается в виде заготовок, из которых методами механической обработки получают готовые детали. Консультируем, помогаем подобрать решение.'),
(27666, 2956, '_aioseop_title', 'Механическая обработка | Фторопластовые технологии'),
