(27872, 2746, '_wp_old_slug', 'ftoroplast4_gost'),
(27887, 2751, '_wp_old_slug', 'precompose'),
(27902, 2753, '_wp_old_slug', 'films-and-tapes'),
(27931, 2755, '_wp_old_slug', 'tube'),
(27943, 2755, '_aioseop_keywords', 'Трубка фторопластовая, трубка из фторопласта'),
(27944, 2755, '_aioseop_description', 'Трубки обладают высокой химической стойкостью к различным химическим средам. Относятся к типу 308 по ГОСТ 17675-87. Изготавливаем изделия по чертежам заказчика. Консультируем.'),
(27945, 2755, '_aioseop_title', 'Трубка фторопластовая электроизоляционная Ф-4Д | Фторопластовые технологии'),
(27957, 2757, '_wp_old_slug', 'plenka'),
(27958, 2757, '_aioseop_keywords', 'Плёнка сырая каландрированная'),
(27959, 2757, '_aioseop_description', 'Пленка применяется в качестве электроизоляционного материала для проводов, кабелей и других электротехнических изделий в виде спеченной в монолит оболочки. Изготавливаем изделия по чертежам заказчика. Консультируем.'),
(27960, 2757, '_aioseop_title', 'Плёнка из фторопласта Ф-4Д сырая каландрированная | Фторопластовые технологии'),
(27972, 2759, '_wp_old_slug', 'layer'),
(27973, 2759, '_aioseop_keywords', 'Прокладки фторопластовые, прокладки из фторопласта'),
(27974, 2759, '_aioseop_description', 'Плоские эластичные прокладки из паронита, резины, картона, фторопласта-4 и композиционных материалов, на их основе для фланцев арматуры, соединительных частей и трубопроводов с уплотнительными поверхностями исполнений.'),
(27975, 2759, '_aioseop_title', 'Прокладки из фторопласта плоские и эластичные | Фторопластовые технологии'),
(27987, 2761, '_wp_old_slug', 'details'),
(27988, 2761, '_aioseop_keywords', 'Детали из фторопласта'),
(27989, 2761, '_aioseop_description', 'Заготовки изготавливаются из фторопласта-4, фторопласта-4 модифицированного, фторопласта-4А и из фторопластовых композиций Ф4К20, Ф4С15, Ф4К15М5. Изготавливаем изделия по чертежам заказчика. Консультируем.'),
(27990, 2761, '_aioseop_title', 'Детали из фторопластовых заготовок | Фторопластовые технологии'),
