(28047, 2763, '_wp_old_slug', 'templates'),
(28048, 2763, '_aioseop_keywords', 'Фторопласт и металл'),
(28049, 2763, '_aioseop_description', 'Заготовки из композиций фторопластовых Ф4Н17М3, Ф4Н40М3, Ф4Бр40, Ф4Бр60 предназначены для изготовления различных деталей антифрикционного назначения, в том числе манжет, поршневых колец, подшипников скольжения, уплотнительных колец, работающих в интервале температур от минус 60 до плюс 250°С, обладающих повышенной износостойкостью и высокой устойчивостью к деформации под нагрузкой.'),
(28050, 2763, '_aioseop_title', 'Заготовки из металлофторопластовых композиций | Фторопластовые технологии'),
