(28144, 2753, '_aioseop_keywords', 'Плёнка из фторопласта, плёнка фторопластовая'),
(28145, 2753, '_aioseop_description', 'Пленки и лента стойки к воздействию всех сред, за исключением газообразного фтора, трехфтористого хлора, расплавов и растворов щелочных металлов. Изготавливаем изделия по чертежам заказчика. Консультируем.\r\n'),
(28146, 2753, '_aioseop_title', 'Плёнка и лента из Фторопласта-4 | Фторопластовые технологии'),
(28161, 2893, '_aioseop_keywords', 'Фторопласт физические свойства, фторопласт химические свойства, фторопласт механические свойства'),
(28162, 2893, '_aioseop_description', 'Фторопласт-4 - кристаллический полимер, температурой плавления кристаллитов 327°С и температурой стеклования аморфных участков от -100 до -120°С. Подробнее о фторопласте | на нашем сайте.\r\n'),
(28163, 2893, '_aioseop_title', 'Фторопласт | описание свойств и показателей | Фторопластовые технологии'),
(28175, 2962, '_aioseop_keywords', 'Капролон свойства, капролон производство, капролон купить'),
(28176, 2962, '_aioseop_description', 'Капролон - жесткий и твердый пластик, легко сваривается и клеится. В полезные свойства капролона можно занести устойчивость к химическим реагентам, а также бензину, различным маслам, слабым кислотам и т.п.'),
(28177, 2962, '_aioseop_title', 'Свойства капролона | Фторопластовые технологии');
INSERT INTO `fttwp_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(28189, 2964, '_aioseop_keywords', 'полиоцеталь, полиформальдегид, обработка инженерных пластиков'),
(28190, 2964, '_aioseop_description', 'Полиоксиметилен, полиоцеталь, полиформальдегид. ЗАО Фторопластовые технологии помогает разработать, подобрать решение и изготовить готовые изделия. Консультируем по любым вопросам.'),
(28191, 2964, '_aioseop_title', 'Обработка инженерных пластиков | Фторопластовые технологии'),
(28194, 3815, '_wp_old_slug', '%d1%81%d0%b2%d0%be%d0%b9%d1%81%d1%82%d0%b2%d0%b0-%d1%81%d0%b2%d0%bc%d0%bf%d1%8d'),
