(28211, 3810, '_wp_old_date', '2018-06-24'),
(28224, 2751, '_aioseop_keywords', 'Заготовки из фторопласта'),
(28225, 2751, '_aioseop_description', 'Заготовки выпускают в виде пластин, брусков, дисков, стержней, втулок (колец) и других типов. Изготавливаем изделия по чертежам заказчика. Консультируем.'),
(28226, 2751, '_aioseop_title', 'Заготовки из Фторопласта 4 общего назначения | Фторопластовые технологии'),
(28235, 2749, '_aioseop_keywords', 'фторопласт 4д'),
(28236, 2749, '_aioseop_description', 'Фторопласт-4Д применяют для изготовления методом экструзии тонкостенных труб, шлангов, стержней, кабельной изоляции, ленты и материала «ФУМ», сырой каландрированной пленки и других изделий. Изготавливаем изделия по чертежам заказчика. Консультируем.'),
(28237, 2749, '_aioseop_title', 'Фторопласт-4Д документация | Фторопластовые технологии'),
(28246, 2746, '_aioseop_keywords', 'ГОСТ фторопласт 4'),
(28247, 2746, '_aioseop_description', 'Фторопласт-4 предназначается для изготовления изделий, пленок, обладающих высокими диэлектрическими свойствами, стойкостью к сильным агрессивным средам и работающих при температуре до плюс 260°С. Изготавливаем изделия по чертежам заказчика. Консультируем.'),
(28248, 2746, '_aioseop_title', 'Фторопласт-4 документация | Фторопластовые технологии'),
(28252, 1770, '_aioseop_keywords', 'продукция фтортопласт'),
(28253, 1770, '_aioseop_description', 'ЗАО "Фторопластовые технологии" предоставляет широкий спектр продукции. Наш отдел консалтинга поможет подобрать индивидуальное решение и разработать соответствующий проект.'),
(28254, 1770, '_aioseop_title', 'Продукция | Фторопластовые технологии'),
