(40, 1, '2010-08-23 19:14:50', '2010-08-24 02:14:50', '<strong>ЗАО Фторопластовые технологии</strong>\r\n\r\n<strong>Центральный офис и производство</strong>\r\n\r\n<strong>197183</strong><strong>, Санкт-Петербург, Липовая аллея д. 9</strong><strong>, лит. А, пом. 14Н</strong>\r\n\r\n<strong>+7 (812) 324-75-35</strong>\r\n\r\n&nbsp;\r\n\r\n<strong>ООО "ТД Фторопластовые технологии" Продажа заготовок</strong>\r\n\r\n<strong>Фактический и юридический адрес:</strong>\r\n\r\n<strong>197183, Россия, г. Санкт-Петербург, Липовая аллея, д. 9, лит. А, пом. 14Н</strong>\r\n\r\n<strong>+7 (812) 327-27-76</strong>\r\n\r\n<strong>E-mail:</strong> <a href="mailto:ftoroplast@chemcom.ru"><strong>ftoroplast@chemcom.ru</strong></a>\r\n\r\n[google_maps height="300"]\r\n[location title="Eifel Tower" lat="48.8582285" lon="2.2943877000000157"]Location description for Eifel Tower[/location]\r\n[/google_maps]\r\n<div><small><a href="http://maps.google.ru/maps?f=q&amp;source=embed&amp;hl=ru&amp;geocode=&amp;q=%D0%A1%D0%B0%D0%BD%D0%BA%D1%82-%D0%9F%D0%B5%D1%82%D0%B5%D1%80%D0%B1%D1%83%D1%80%D0%B3,+%D1%83%D0%BB.%D0%90%D0%BB%D0%B5%D0%BA%D1%81%D0%B0%D0%BD%D0%B4%D1%80%D0%B0+%D0%9C%D0%B0%D1%82%D1%80%D0%BE%D1%81%D0%BE%D0%B2%D0%B0,+%D0%B4.4,+%D0%BA%D0%BE%D1%80.+2,+%D0%BB%D0%B8%D1%82.+%D0%9B&amp;aq=&amp;sll=61.676372,105.31911&amp;sspn=105.95154,350.507813&amp;ie=UTF8&amp;hq=&amp;hnear=%D1%83%D0%BB.+%D0%90%D0%BB%D0%B5%D0%BA%D1%81%D0%B0%D0%BD%D0%B4%D1%80%D0%B0+%D0%9C%D0%B0%D1%82%D1%80%D0%BE%D1%81%D0%BE%D0%B2%D0%B0,+4,+%D0%A1%D0%B0%D0%BD%D0%BA%D1%82-%D0%9F%D0%B5%D1%82%D0%B5%D1%80%D0%B1%D1%83%D1%80%D0%B3,+194100&amp;t=m&amp;ll=59.977263,30.330334&amp;spn=0.041227,0.109863&amp;z=13&amp;iwloc=A" target="_blank" rel="noopener"><img src="https://www.ftoroplast.com.ru/img/maps/spb.jpg" width="400" border="0" />\r\nСанкт-Петербург</a></small></div>\r\n<table border="1" width="95%" cellspacing="1" cellpadding="5">\r\n<tbody>\r\n<tr>\r\n<td>\r\n<h1>Генеральный директор</h1>\r\n</td>\r\n<td>Дьяченко Николай Валерьевич</td>\r\n<td>доб. 202</td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<h1>Менеджер коммерческого отдела</h1>\r\n</td>\r\n<td>\r\n<div>Русинов Антон Евгеньевич</div></td>\r\n<td>\r\n<div>\r\n\r\nдоб. 222\r\n\r\n</div></td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<h1>Менеджер коммерческого отдела</h1>\r\n</td>\r\n<td>Елизаров Михаил Андреевич</td>\r\n<td>доб. 221</td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<h1>Менеджер коммерческого отдела</h1>\r\n<h1>(фторопластовая продукция с технической приемкой)</h1>\r\n</td>\r\n<td>\r\n<div>Михайлов Андрей Владимирович</div></td>\r\n<td>\r\n<div>\r\n\r\nдоб. 210\r\n\r\n</div></td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<h1>Начальник отдела контроля качества</h1>\r\n</td>\r\n<td>Ильина Надежда Николаевна</td>\r\n<td>доб. 215</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<div></div>\r\n<div>\r\n<h3>Представительство в Москве</h3>\r\n<div>\r\n<h3>109382, г.Москва, ул.Нижние Поля д.31 оф.413\r\nТел. факс.: +7 (499) 357-82-00 Сот: +7 (495) 518-57-18 Абрамов Максим Викторович</h3>\r\n<div>\r\n<h3>E-mail: <a href="mailto:chemcom-m@chemcom.ru">chemcom-m@chemcom.ru</a></h3>\r\n<div><small><a href="http://maps.google.ru/maps?f=q&amp;source=embed&amp;hl=ru&amp;geocode=&amp;q=%D0%9C%D0%BE%D1%81%D0%BA%D0%B2%D0%B0,+%D1%83%D0%BB.%D0%9D%D0%B8%D0%B6%D0%BD%D0%B8%D0%B5+%D0%9F%D0%BE%D0%BB%D1%8F+%D0%B4.31+%D0%BE%D1%84.413&amp;aq=&amp;sll=59.977303,30.330274&amp;sspn=0.012261,0.042787&amp;ie=UTF8&amp;hq=&amp;hnear=%D1%83%D0%BB.+%D0%9D%D0%B8%D0%B6%D0%BD%D0%B8%D0%B5+%D0%9F%D0%BE%D0%BB%D1%8F,+31,+%D0%9C%D0%BE%D1%81%D0%BA%D0%B2%D0%B0,+109382&amp;t=m&amp;ll=55.656285,37.730141&amp;spn=0.023243,0.054932&amp;z=14&amp;iwloc=A" target="_blank" rel="noopener"><img src="https://www.ftoroplast.com.ru/img/maps/msk.jpg" width="400" border="0" />\r\nМосква</a></small>\r\n<div>\r\n<h3>Представительство в Новосибирске</h3>\r\n<div>\r\n<div>\r\n<h3>г.Новосибирск, ул.Кирова, д.278, лит.И-2.0\r\nТел. факс.:  +7 (383) 362-27-72</h3>\r\n<div>\r\n<h3>E-mail: <a href="mailto:ftoroplast@ftoroplastsib.ru">ftoroplast@ftoroplastsib.ru</a></h3>\r\n<div><small><a href="http://maps.google.ru/maps?f=q&amp;source=embed&amp;hl=ru&amp;geocode=&amp;q=%D0%9D%D0%BE%D0%B2%D0%BE%D1%81%D0%B8%D0%B1%D0%B8%D1%80%D1%81%D0%BA,+%D1%83%D0%BB.%D0%9A%D0%B8%D1%80%D0%BE%D0%B2%D0%B0,+%D0%B4.278,+%D0%BB%D0%B8%D1%82.%D0%98-2&amp;aq=&amp;sll=55.656285,37.730141&amp;sspn=0.027649,0.085573&amp;ie=UTF8&amp;hq=&amp;hnear=%D1%83%D0%BB.+%D0%9A%D0%B8%D1%80%D0%BE%D0%B2%D0%B0,+278,+%D0%9D%D0%BE%D0%B2%D0%BE%D1%81%D0%B8%D0%B1%D0%B8%D1%80%D1%81%D0%BA,+630063&amp;t=m&amp;ll=55.003121,82.976475&amp;spn=0.023629,0.054932&amp;z=14&amp;iwloc=A" target="_blank" rel="noopener"><img src="https://www.ftoroplast.com.ru/img/maps/nsk.jpg" width="400" border="0" />\r\nНовосибирск</a></small>\r\n<div>\r\n<h3>Реквизиты:</h3>\r\nЗАО "Фторопластовые технологии"\r\n\r\nИНН/КПП 7816193617/781401001\r\n\r\nФилиал С-Петербург ПАО Банка "ФК Открытие"\r\n\r\nр.счет 40702810500350117001\r\n\r\nБИК 044030720\r\n<div>\r\n<h3>К.счет 30101810200000000720</h3>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>', 'Контакты', '', 'publish', 'open', 'open', '', 'contacts', '', '', '2018-06-13 12:03:48', '2018-06-13 12:03:48', '', 0, '<strong>ЗАО Фторопластовые технологии</strong>\r\n\r\n<strong>Центральный офис и производство</strong>\r\n\r\n<strong>197183</strong><strong>, Санкт-Петербург, Липовая аллея д. 9</strong><strong>, лит. А, пом. 14Н</strong>\r\n\r\n<strong>+7 (812) 324-75-35</strong>\r\n', 0, 'page', '', 0),
