dth="142">\r\n<div>26,60</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="170">\r\n<div>4,2</div>\r\n<div>4,5</div>\r\n<div>5,0</div></td>\r\n<td valign="top" width="132">\r\n<div></div>\r\n<div>0,6</div></td>\r\n<td valign="top" width="132">\r\n<div>8,97</div>\r\n<div>9,53</div>\r\n<div>10,51</div></td>\r\n<td valign="top" width="142">\r\n<div>19,70</div>\r\n<div>20,96</div>\r\n<div>23,30</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="170">\r\n<div>5,0</div>\r\n<div>5,5</div>\r\n<div>6,0</div></td>\r\n<td valign="top" width="132">\r\n<div></div>\r\n<div>1,0</div></td>\r\n<td valign="top" width="132">\r\n<div>18,72</div>\r\n<div>20,20</div>\r\n<div>21,84</div></td>\r\n<td valign="top" width="142">\r\n<div>41,20</div>\r\n<div>44,40</div>\r\n<div>48,50</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="170">\r\n<div>6,0</div></td>\r\n<td valign="top" width="132">\r\n<div>1,5</div></td>\r\n<td valign="top" width="132">\r\n<div>35,10</div></td>\r\n<td valign="top" width="142">\r\n<div>77,22</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="170">\r\n<div>7,0</div></td>\r\n<td valign="top" width="132">\r\n<div>1,0</div></td>\r\n<td valign="top" width="132">\r\n<div>24,90</div></td>\r\n<td valign="top" width="142">\r\n<div>54,80</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="170">\r\n<div>8,0</div></td>\r\n<td valign="top" width="132">\r\n<div>1,0</div></td>\r\n<td valign="top" width="132">\r\n<div>28,26</div></td>\r\n<td valign="top" width="142">\r\n<div>62,17</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="170">\r\n<div>8,0</div></td>\r\n<td valign="top" width="132">\r\n<div>1,5</div></td>\r\n<td valign="top" width="132">\r\n<div>44,50</div></td>\r\n<td valign="top" width="142">\r\n<div>97,90</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="170">\r\n<div>8,0</div></td>\r\n<td valign="top" width="132">\r\n<div>2,0</div></td>\r\n<td valign="top" width="132">\r\n<div>62,40</div></td>\r\n<td valign="top" width="142">\r\n<div>137,30