FFBFF"><span class="mainblock">Толщина, мм</span></td>\r\n<td align="center" valign="middle" bgcolor="#FFFBFF"><span class="mainblock">Допуск на толщину, мм</span></td>\r\n<td align="center" valign="middle" bgcolor="#FFFBFF"><img src="https://www.ftoroplast.com.ru/images/cart.gif" /></td>\r\n</tr>\r\n<tr>\r\n<td align="center" valign="middle" bgcolor="#FFFBFF"><span class="mainblock">  Лента ФУМ</span></td>\r\n<td align="center" valign="middle" bgcolor="#FFFBFF"><span class="mainblock">  10</span></td>\r\n<td align="center" valign="middle" bgcolor="#FFFBFF"><span class="mainblock">  0,1</span></td>\r\n<td align="center" valign="middle" bgcolor="#FFFBFF"><span class="mainblock">  +/-0,02</span></td>\r\n<td class="orderCell" align="center" valign="middle" bgcolor="#FFFBFF"><a id="d8ae7b86420a11d9a619cfed20797861" class="makeOrder"></a>заказать</td>\r\n</tr>\r\n<tr>\r\n<td align="center" valign="middle" bgcolor="#FFFBFF"><span class="mainblock">  Лента ФУМ</span></td>\r\n<td align="center" valign="middle" bgcolor="#FFFBFF"><span class="mainblock">  15</span></td>\r\n<td align="center" valign="middle" bgcolor="#FFFBFF"><span class="mainblock">  0,1</span></td>\r\n<td align="center" valign="middle" bgcolor="#FFFBFF"><span class="mainblock">  +/-0,02</span></td>\r\n<td class="orderCell" align="center" valign="middle" bgcolor="#FFFBFF"><a id="0551ca97420b11d9a619cfed20797861" class="makeOrder"></a>заказать</td>\r\n</tr>\r\n<tr>\r\n<td align="center" valign="middle" bgcolor="#FFFBFF"><span class="mainblock">  Лента ФУМ</span></td>\r\n<td align="center" valign="middle" bgcolor="#FFFBFF"><span class="mainblock">  20</span></td>\r\n<td align="center" valign="middle" bgcolor="#FFFBFF"><span class="mainblock">  0,1</span></td>\r\n<td align="center" valign="middle" bgcolor="#FFFBFF"><span class="mainblock">  +/-0,02</span></td>\r\n<td class="orderCell" align="center" valign="middle" bgcolor="#FFFBFF"><a id="3915226a420b11d9a619cfed20797861" class="makeOrder"></a>заказать</td>\r\n</tr>\r\n<tr>\r\n<td align="center" valign="middle" bgcolor="#FFFBFF"><span class="mainblock">  Лента ФУМ</span></td>\r\n<td align="center" valign="middle" bgcolor="#FFFBFF"><span class="mainblock">  60</span></td>\r\n<td align="center" valign="middle" bgcolor="#FFFBFF"><span class="mainblock">  0,1</span></td>\r\n<td align="center" valign="middle" bgcolor="#FFFBFF"><span class="mainblock">  +/-0,02</span></td>\r\n<td class="orderCell" align="center" valign="middle" bgcolor="#FFFBFF"><a id="4ae168b7420b11d9a619cfed20797861" class="makeOrder"></a>заказать</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n<table border="0" width="100%" bgcolor="#FFFBFF">\r\n<tbody>\r\n<tr valign="middle">\r\n<td align="center" valign="middle" bgcolor="#FFFBFF"></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<table border="0" width="100%" bgcolor="#FFFBFF">\r\n<tbody>\r\n<tr valign="middle">\r\n<td align="center" valign="middle" bgcolor="#FFFBFF">\r\n<div>\r\n\r\n<strong>Примечание:</strong>\r\n<ul>\r\n 	<li>цена указана без учета НДС (18%);</li>\r\n 	<li>цена указана при партии более 50 кг;</li>\r\n 	<li>цены для организаций РФ.</li>\r\n</ul>\r\n</div></td>\r\n</tr>\r\n</tbody>\r\n</table>', 'Лента ФУМ', '', 'inherit', 'closed', 'closed', '', '2879-revision-v1', '', '', '2018-04-12 03:07:04', '2018-04-12 03:07:04', '', 2879, '<table border="0" width="100%" bgcolor="#FFFBFF">\r\n<tbody>\r\n<tr align="" valign="middle">\r\n<td align="left" bgcolor="#FFFBFF">\r\n<div>\r\n\r\nпускается по:\r\n<ul>\r\n 	<li>ТУ 6-05-1388-86</li>\r\n</ul>\r\n</div></td>\r\n<td class="prod-head" align="center" valign="midd', 0, 'revision', '', 0),
(2882, 1, '2018-04-12 03:09:13', '2018-04-12 03:09:13', 'Наша организация изготавливает из фторопласта-4 защитные кольца для уплотнительных устройств радиальных неподвижных и подвижных соединений (далее - защитные кольца), предназначенные для предохранения резиновых колец от выдавливания в уплотняемый зазор под воздействием избыточного давления в рабочей полости цилиндра и устанавливаемые в рабочие канавки.\r\n\r\nТипоразмеры колец и их размеры соответствуют ГОСТ 23825-79 и таблицы, размещенной ниже (размеры колец в таблице постоянно пополняется).\r\n\r\nВозможно изготовление других типоразмеров колец. Стоимость этих изделий рассчитывается исходя из типоразмера и количества в партии.\r\n\r\n<hr />\r\n\r\n<strong>Примечание:</strong>\r\n\r\nцена указана без учета НДС (18%);\r\nпри заказе партии более 5000 штук - скидка 5% от цены.', 'Кольца защитные уплотнительные из фторопласта', '', 'publish', 'open', 'closed', '', '%d0%ba%d0%be%d0%bb%d1%8c%d1%86%d0%b0-%d0%b7%d0%b0%d1%89%d0%b8%d1%82%d0%bd%d1%8b%d0%b5-%d1%83%d0%bf%d0%bb%d0%be%d1%82%d0%bd%d0%b8%d1%82%d0%b5%d0%bb%d1%8c%d0%bd%d1%8b%d0%b5-%d0%b8%d0%b7-%d1%84%d1%82', '', '', '2018-06-14 07:03:11', '2018-06-14 07:03:11', '', 0, 'Наша организация изготавливает из фторопласта-4 защитные кольца для уплотнительных устройств радиальных неподвижных и подвижных соединений (далее - защитные кольца), предназначенные для предохранения резиновых колец от выдавливания в уплотняемый зазор под', 0, 'products', '', 0),
