INSERT INTO `fttwp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(3181, 1, '2018-06-24 22:04:20', '2018-06-24 22:04:20', 'Фторопласт -4 - кристаллический полимер, температурой плавления кристаллитов 327°С и температурой стеклования аморфных участков от -100 до -120°С. Даже при температуре выше температуры разложения (415°С) фторопласт-4 не переходит в вязкотекучее состояние (при 370°С вязкость его расплава равна ≈10<sup>11</sup>П, т.е. в 1000000 раз больше вязкости, (необходимой для литья под давлением), поэтому переработка его возможна только методом спекания отпрессованных таблеток.\n\nВ зависимости от скорости охлаждения (до температуры ниже 250°С) после спекания можно получить закаленные изделия со степенью кристалличности ≈50% и плотностью ≈2,15 г/см<sup>3</sup> или незакаленные со степенью кристалличности более 65% плотностью выше 2,20 г/см3.При температуре эксплуатации и от -269°С до +260°С степень кристалличности, достигнутая при данном режиме охлаждения, не меняется, при температуре выше 260°С степень кристалличности постепенно увеличивается, особенно быстро она вырастает при 310 - 315°С.\n<div>\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\n<tbody>\n<tr>\n<td><strong>Степень кристалличности, %</strong></td>\n<td><strong>Плотность при\n23°С, г/см<sup>3</sup></strong></td>\n<td><strong>Степень кристалличности, %</strong></td>\n<td><strong>Плотность при\n23°С, г/см<sup>3</sup></strong></td>\n</tr>\n<tr>\n<td>40.0</td>\n<td>2.12</td>\n<td>69.4</td>\n<td>2.21</td>\n</tr>\n<tr>\n<td>43.2</td>\n<td>2.13</td>\n<td>72.8</td>\n<td>2.22</td>\n</tr>\n<tr>\n<td>46.5</td>\n<td>2.14</td>\n<td>75.2</td>\n<td>2.23</td>\n</tr>\n<tr>\n<td>49.7</td>\n<td>2.15</td>\n<td>78.0</td>\n<td>2.24</td>\n</tr>\n<tr>\n<td>53.0</td>\n<td>2.16</td>\n<td>80.7</td>\n<td>2.25</td>\n</tr>\n<tr>\n<td>56.3</td>\n<td>2.17</td>\n<td>82.6</td>\n<td>2.26</td>\n</tr>\n<tr>\n<td>59.7</td>\n<td>2.18</td>\n<td>85.2</td>\n<td>2.27</td>\n</tr>\n<tr>\n<td>63.1</td>\n<td>2.19</td>\n<td>89.0</td>\n<td>2.28</td>\n</tr>\n<tr>\n<td>66.5</td>\n<td>2.20</td>\n<td>-</td>\n<td>-</td>\n</tr>\n</tbody>\n</table>\nОб отсутствии же пористости свидетельствует полная прозрачность образца во время спекания при 370-390°С. Даже незначительная пористость вызывает мутность образца. Пористость, равная примерно 0,1-0,2%, заметно влияет на точность определения плотности.\n\nДанные о зависимости удельного объема и плотности от температуры для образца со степенью кристалличности 68% (плотность медленно охлажденного изделия) приведены ниже:\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\n<tbody>\n<tr>\n<td><strong>Температура, °С</strong></td>\n<td><strong>Удельный объем, см<sup>3</sup>/г</strong></td>\n<td><strong>Плотность, г/см<sup>3</sup></strong></td>\n<td><strong>Температура, °С</strong></td>\n<td><strong>Удельный объем, cм<sup>3</sup>/г</strong></td>\n<td><strong>Плотность, г/см<sup>3</sup></strong></td>\n</tr>\n<tr>\n<td>-50</td>\n<td>0.440</td>\n<td>2.27</td>\n<td>175</td>\n<td>0.4769</td>\n<td>2.10</td>\n</tr>\n<tr>\n<td>-25</td>\n<td>0.443</td>\n<td>2.26</td>\n<td>200</td>\n<td>0.482</td>\n<td>2.08</td>\n</tr>\n<tr>\n<td>0</td>\n<td>0.447</td>\n<td>2.24</td>\n<td>225</td>\n<td>0.488</td>\n<td>2.05</td>\n</tr>\n<tr>\n<td>+25</td>\n<td>0.453*</td>\n<td>2.21</td>\n<td>250</td>\n<td>0.495</td>\n<td>2.02</td>\n</tr>\n<tr>\n<td>+50</td>\n<td>0.456</td>\n<td>2.19</td>\n<td>275</td>\n<td>0.503</td>\n<td>1.99</td>\n</tr>\n<tr>\n<td>+75</td>\n<td>0.459</td>\n<td>2.18</td>\n<td>300</td>\n<td>0.514</td>\n<td>1.95</td>\n</tr>\n<tr>\n<td>+100</td>\n<td>0.463</td>\n<td>2.16</td>\n<td>325</td>\n<td>0.534</td>\n<td>1.88</td>\n</tr>\n<tr>\n<td>+125</td>\n<td>0.467</td>\n<td>2.14</td>\n<td>327</td>\n<td>0.640**</td>\n<td>1.57</td>\n</tr>\n<tr>\n<td>+150</td>\n<td>0.471</td>\n<td>2.12</td>\n<td>350</td>\n<td>0.655</td>\n<td>1.53</td>\n</tr>\n</tbody>\n</table>\n* При нагревании от 19,6 до 22°C удлиненный объём увеличивается на 0,74%\n** При 327°С удлиненный объём увеличивается на 20%.\n<h2>ФИЗИКО-МЕХАНИЧЕСКИЕ СВОЙСТВА ФТОРОПЛАСТА-4</h2>\nОсновные показатели физико-механических свойств фторопласта-4 приведены ниже:\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\n<tbody>\n<tr>\n<td><strong>Разрушающее напряжение, кгс/см<sup>2</sup></strong></td>\n<td>Значения</td>\n</tr>\n<tr>\n<td>при растяжении:</td>\n<td>-</td>\n</tr>\n<tr>\n<td>- незакаленный образец (кристалличность 05-08%)</td>\n<td>140-350*</td>\n</tr>\n<tr>\n<td>- закаленный образец (кристалличность 50%)</td>\n<td>160-315*</td>\n</tr>\n<tr>\n<td>при сжатии:</td>\n<td>-</td>\n</tr>\n<tr>\n<td>- при 1%-ной деформации</td>\n<td>100</td>\n</tr>\n<tr>\n<td>- 10%-ной деформации</td>\n<td>185</td>\n</tr>\n<tr>\n<td><strong>Сопротивлению изгибу (стрела прогиба 6 мм)</strong></td>\n<td>185</td>\n</tr>\n<tr>\n<td><strong>Относительное удлинение при разрыт, %</strong></td>\n<td>250-500</td>\n</tr>\n<tr>\n<td><strong>Остаточное удлинение, %</strong></td>\n<td>250-350</td>\n</tr>\n<tr>\n<td><strong>Напряжение при 10%-ном удлинении, кгс/см<sup>2</sup></strong></td>\n<td>110-120</td>\n</tr>\n<tr>\n<td><strong>Модуль упругости, кгс/см<sup>2</sup></strong></td>\n<td>-</td>\n</tr>\n<tr>\n<td>- при изгибе при 20°С</td>\n<td>4700-8500</td>\n</tr>\n<tr>\n<td>- сдвиге 2700</td>\n<td>2700</td>\n</tr>\n<tr>\n<td><strong>Ударная вязкость, кгс·см/см<sup>2</sup></strong></td>\n<td>100 (не ломается)</td>\n</tr>\n<tr>\n<td><strong>Ударное растяжение, кгс·см/см<sup>2</sup> (DIN 53448)</strong></td>\n<td>-</td>\n</tr>\n<tr>\n<td>- при 20°С</td>\n<td>650</td>\n</tr>\n<tr>\n<td>- 23°С</td>\n<td>680</td>\n</tr>\n<tr>\n<td>(удлинение при 20°С - 20%, при 23°С - 30%)</td>\n<td>-</td>\n</tr>\n<tr>\n<td><strong>Твердость:</strong></td>\n<td>-</td>\n</tr>\n<tr>\n<td>по Бринеллю, кгс/мм<sup>2</sup></td>\n<td>3-4</td>\n</tr>\n<tr>\n<td>по Шору при 20°С</td>\n<td>-</td>\n</tr>\n<tr>\n<td>- шкала С</td>\n<td>85-87</td>\n</tr>\n<tr>\n<td>- шкала D</td>\n<td>55-59</td>\n</tr>\n<tr>\n<td>Твердость по Роквеллу</td>\n<td>-</td>\n</tr>\n<tr>\n<td>- шкала I</td>\n<td>80-95</td>\n</tr>\n</tbody>\n</table>\nВ зависимости от того, как вырезан образец: поперек направления прессования-высокие значения, вдоль направления прессования-малые.\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\n<tbody>\n<tr>\n<td><strong>Показатели</strong></td>\n<td colspan="10"><strong>Температура, °С</strong></td>\n</tr>\n<tr>\n<td>-</td>\n<td>-60</td>\n<td>-40</td>\n<td>-20</td>\n<td>0</td>\n<td>20</td>\n<td>40</td>\n<td>60</td>\n<td>80</td>\n<td>100</td>\n<td>120</td>\n</tr>\n<tr>\n<td>Разрушающее напряжение при растяжении, кгс/см<sup>2</sup></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n</tr>\n<tr>\n<td>- незакаленный образец</td>\n<td>-</td>\n<td>350</td>\n<td>325</td>\n<td>300</td>\n<td>200</td>\n<td>180</td>\n<td>-</td>\n<td>135</td>\n<td>115</td>\n<td>-</td>\n</tr>\n<tr>\n<td>- закаленный образец</td>\n<td>-</td>\n<td>500</td>\n<td>440</td>\n<td>330</td>\n<td>250</td>\n<td>240</td>\n<td>-</td>\n<td>200</td>\n<td>190</td>\n<td>-</td>\n</tr>\n<tr>\n<td>Относительное удлинение при разрыве, %</td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n</tr>\n<tr>\n<td>- незакаленный образец</td>\n<td>-</td>\n<td>70</td>\n<td>100</td>\n<td>150</td>\n<td>470</td>\n<td>650</td>\n<td>-</td>\n<td>600</td>\n<td>540</td>\n<td>-</td>\n</tr>\n<tr>\n<td>- закаленный образец</td>\n<td>-</td>\n<td>100</td>\n<td>160</td>\n<td>190</td>\n<td>400</td>\n<td>500</td>\n<td>-</td>\n<td>500</td>\n<td>480</td>\n<td>-</td>\n</tr>\n<tr>\n<td>Модуль упругости, кгс/см<sup>2</sup></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n</tr>\n<tr>\n<td>при сжатии</td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n</tr>\n<tr>\n<td>- незакаленный образец</td>\n<td>18000</td>\n<td>17000</td>\n<td>15000</td>\n<td>11000</td>\n<td>7000</td>\n<td>4500</td>\n<td>3300</td>\n<td>2400</td>\n<td>1700</td>\n<td>-</td>\n</tr>\n<tr>\n<td>при сжатии</td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n</tr>\n<tr>\n<td>- незакаленный образец</td>\n<td>27800</td>\n<td>23900</td>\n<td>23300</td>\n<td>18100</td>\n<td>8500</td>\n<td>5100</td>\n<td>4800</td>\n<td>3800</td>\n<td>-</td>\n<td>2450</td>\n</tr>\n<tr>\n<td>- закаленный образец</td>\n<td>13200</td>\n<td>11300</td>\n<td>9800</td>\n<td>7400</td>\n<td>4700</td>\n<td>4000</td>\n<td>2900</td>\n<td>2180</td>\n<td>-</td>\n<td>1100</td>\n</tr>\n</tbody>\n</table>\nДанные о зависимости физико-механических свойств фторопласта-4 от температуры приведены ниже.\n<h2>Физико-механические свойства фторопласта-4 при низких температурах</h2>\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\n<tbody>\n<tr>\n<td><strong>Показатели</strong></td>\n<td colspan="6"><strong>Температура, °С</strong></td>\n</tr>\n<tr>\n<td></td>\n<td>-93</td>\n<td>-123</td>\n<td>-153</td>\n<td>-193</td>\n<td>-223</td>\n<td>-269</td>\n</tr>\n<tr>\n<td>Разрушающее напряжение при сжатии *, кгс/см<sup>2</sup></td>\n<td>350</td>\n<td>-</td>\n<td>980</td>\n<td>1260</td>\n<td>1554</td>\n<td>1750-1960</td>\n</tr>\n<tr>\n<td>Модуль упругости при сжатии, кгс/см<sup>2</sup></td>\n<td>-</td>\n<td>52500</td>\n<td>-</td>\n<td>-</td>\n<td>-</td>\n<td>70000</td>\n</tr>\n</tbody>\n</table>\n* Разрушающее напряжение при сжатии равно напряжению, при котором деформация составляет 0,2%.\n<h2>Зависимость деформации фторопласта-4 при сжатии от температуры:</h2>\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\n<tbody>\n<tr>\n<td><strong>Деформация, %</strong></td>\n<td colspan="7"><strong>Нагрузка, вызывающая деформацию, кгс/см</strong><sup>2</sup></td>\n</tr>\n<tr>\n<td>-</td>\n<td>-50°С</td>\n<td> 0°С</td>\n<td> 25°С</td>\n<td>50°С</td>\n<td>100°С</td>\n<td>150°С</td>\n<td>200°С</td>\n</tr>\n<tr>\n<td>1</td>\n<td>203</td>\n<td>157</td>\n<td>62</td>\n<td>49</td>\n<td>31</td>\n<td>17,5</td>\n<td>11</td>\n</tr>\n<tr>\n<td>2</td>\n<td>304</td>\n<td>210</td>\n<td>92</td>\n<td>66</td>\n<td>39</td>\n<td>27</td>\n<td>20</td>\n</tr>\n<tr>\n<td>3</td>\n<td>350</td>\n<td>236</td>\n<td>105</td>\n<td>77</td>\n<td>48</td>\n<td>33</td>\n<td>27</td>\n</tr>\n<tr>\n<td>4</td>\n<td>374</td>\n<td>251</td>\n<td>120</td>\n<td>85</td>\n<td>59</td>\n<td>39</td>\n<td>31</td>\n</tr>\n<tr>\n<td>5</td>\n<td>390</td>\n<td>262</td>\n<td>127</td>\n<td>92</td>\n<td>62</td>\n<td>44</td>\n<td>35</td>\n</tr>\n</tbody>\n</table>\nОдним из важнейших прочностных показателей является предел текучести при растяжении, т.е. то напряжение, при котором возникают остаточные деформации. Он зависит от степени кристалличности, скорости растяжения и температуры. При степени кристалличности 65% и скорости растяжения 100 мм/мин зависимость предела текучести от абсолютной температуры Т (в К) описывается эмпирической формулой (справедливой от 20 до 300°С):\nlgσT= 0,53166+483,64/Т\n\nНиже приведены значения пределов текучести для некоторых температур, рассчитанные по этой формуле:\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\n<tbody>\n<tr>\n<td>Температура, °С</td>\n<td>25</td>\n<td>50</td>\n<td>75</td>\n<td>100</td>\n<td>150</td>\n<td>200</td>\n<td>250</td>\n</tr>\n<tr>\n<td>Предел текучести, кгс/см2</td>\n<td>42,4</td>\n<td>106,9</td>\n<td>83,5</td>\n<td>67,2</td>\n<td>46,6</td>\n<td>35,5</td>\n<td>28,6</td>\n</tr>\n</tbody>\n</table>\nПри длительном воздействии нагрузок остаточные деформации возникают при меньших напряжениях (40-50% от рассчитанных по формуле).\n\nПри конструировании изделий из фторопласта-4 следует учитывать ползучесть. Ползучесть (деформация при длительном действии нагрузки) рассчитывается по формуле:\nlgγt=lgγ1+a·lgt\nгде γt - деформация за t сут; γ1 - деформация за 1 сут; а - коэффициент, зависящий в основном от температуры и в меньшей степени от нагрузки, если она не превышает 40-50% предела текучести.\n\nЗначения коэффициента a и некоторые данные о ползучести для образцов со степенью кристалличности 50% приведены в таблице. Деформация за 1 сут (γ1) при других нагрузках и температурах определяется опытным путем. При степени кристалличности 65-68% ползучесть меньше.\n<h2>   Ползучесть фторопласта-4</h2>\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\n<tbody>\n<tr>\n<td><strong>Температура, °С</strong></td>\n<td><strong>Нагрузка, кгс/см<sup>2</sup></strong></td>\n<td colspan="2"><strong>Деформация, %</strong></td>\n<td><strong>Коэффициент а\n</strong></td>\n</tr>\n<tr>\n<td colspan="2">Сжатие</td>\n<td>1 сут (γ1)</td>\n<td>4 сут (γ4)</td>\n<td>-</td>\n</tr>\n<tr>\n<td>20</td>\n<td>33</td>\n<td>6,00</td>\n<td>6,25</td>\n<td>0,030</td>\n</tr>\n<tr>\n<td>20</td>\n<td>21</td>\n<td>3,05</td>\n<td>3,19</td>\n<td>0,032</td>\n</tr>\n<tr>\n<td colspan="2">Растяжение</td>\n<td>1 сут (γ1)</td>\n<td>4 сут (γ4)</td>\n<td>-</td>\n</tr>\n<tr>\n<td>40</td>\n<td>28</td>\n<td>2,72</td>\n<td>2,87</td>\n<td>0,038</td>\n</tr>\n<tr>\n<td>100</td>\n<td>28</td>\n<td>5,58</td>\n<td>5,90</td>\n<td>0,040</td>\n</tr>\n<tr>\n<td>140</td>\n<td>21</td>\n<td>4,67</td>\n<td>4,94</td>\n<td>0,042</td>\n</tr>\n<tr>\n<td>200</td>\n<td>14</td>\n<td>4,08</td>\n<td>4,50</td>\n<td>0,048</td>\n</tr>\n<tr>\n<td>250</td>\n<td>14</td>\n<td>5,17</td>\n<td>5,58</td>\n<td>0,055</td>\n</tr>\n</tbody>\n</table>\n<h2>АНТИФРИКЦИОННЫЕ СВОЙСТВА ФТОРОПЛАСТА-4</h2>\nДанные о зависимости коэффициента трения от нагрузки [статической и динамической (при малых скоростях) коэффициенты трения фторопласта-4 по стали без смазки одинаковы] приведены ниже:\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\n<tbody>\n<tr>\n<td>Нагрузка, кгс/см2</td>\n<td>1</td>\n<td>3</td>\n<td>10</td>\n<td>20</td>\n</tr>\n<tr>\n<td>Коэффициент трения</td>\n<td>0,4</td>\n<td>0,1</td>\n<td>0,06</td>\n<td>0,05</td>\n</tr>\n</tbody>\n</table>\nПри наличии смазки он примерно в 2 раза меньше.\n\nДинамический коэффициент трения фторопласта-4 по стали без смазки при нагрузке ~ 20 кгс/см2 зависит от скорости скольжения:\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\n<tbody>\n<tr>\n<td>Скорость скольжения, см/c</td>\n<td>4</td>\n<td>8</td>\n<td>20</td>\n<td>40</td>\n<td>80</td>\n<td>160</td>\n</tr>\n<tr>\n<td>Динамический коэффициент трения</td>\n<td>0,05</td>\n<td>0,1</td>\n<td>0,15</td>\n<td>0,23</td>\n<td>0,24</td>\n<td>0,27</td>\n</tr>\n</tbody>\n</table>\nВ присутствии наполнителя при малых скоростях скольжения коэффициент трения несколько выше, а при больших скоростях - ниже, чем коэффициент трения чистого фторопласта-4 по стали.\n\nПри 327°С (на поверхности трения) коэффициент трения фторопласта-4 по стали резко возрастает (в несколько раз), что приводит к катастрофически быстрому износу и разрушению подшипника.\n<h2>ТЕПЛОФИЗИЧЕСКИЕ СВОЙСТВА ФТОРОПЛАСТА-4</h2>\nНеспеченный фторопласт-4 (в виде порошка) имеет степень кристалличности 95 - 98%, после спекания - от 50% (закаленный) до 68 - 70% (незакаленный). Ниже 19,6°С элементарная ячейка кристалла фторопласта-4 состоит из 13 групп CF2, выше 19,6°С - из 15 групп CF2. При 19,6°С триклиническая упаковка переходит в менее упорядоченную, гексагональную, что сопровождается увеличение объема кристаллитов на 0,0058 см3/г (1,2 объемн. %), или увеличением объема образца при степени кристалличности 68% на 0,74%. При наличии внешнего давления точка перехода понижается на 0,013°С на каждую атмосферу. При 30°С имеет место второй переход кристаллической структуры, но изменение объема составляет едва 1/10 часть изменения объема при 19,6°С. Под высоким давлением (4500 кгс/см2 при 70°С) возникает третий переход.\n\nТемпература стеклования аморфных участков, определенная по температуре хрупкости, колеблется от -97 до -100°С, а по точке перегиба кривой зависимости модуля упругости составляет -120°С. Температура перехода аморфного твердого тела в переохлажденную жидкость равна 127°С.\n\nПри 327°С кристаллиты фторопласта-4 плавятся, и он становится полностью аморфным, совершенно прозрачным (при отсутствии пористости), высокоэластичным, но не течет (вязкость выше 1011 П). Объем возрастает на 20%.\n\nТочка плавления зависит от внешнего давления - на каждую атмосферу повышается на 0,154 °С. При остывании расплава ниже 327 °С образец мутнеет и становится непрозрачным - молочно-белым.   Скорость кристаллизации зависит от температуры (максимальная скорость при 310-315 °С), от продолжительности выдержки в расплавленном состоянии при 370-390 °С (чем больше время спекания, тем быстрее кристаллизуется образец) и от среднего молекулярного веса полимера (чем ниже молекулярный вес полимера, тем быстрее он кристаллизуется). На этом основан метод косвенной оценки молекулярного веса фторопласта-4: образец в виде диска толщиной 2 мм спекают при 370 °С в течение 13 ч и охлаждают от 370 до 250 °С в течение 5 ч. По плотности полученного образца при 23 °С можно оценить молекулярный вес: 2,16-2,19 г/см3-для высокомолекулярного полимера, 2,20-2,22 г/см3-для низкомолекулярного.\n<h2>Ниже приведены некоторые теплофизические свойства фторопласта-4:</h2>\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\n<tbody>\n<tr>\n<td>Теплостойкость по Вика (при нагрузке 5 кгс), °С</td>\n<td>110</td>\n</tr>\n<tr>\n<td>Удельная теплоемкость, ккал/(кг·°С)</td>\n<td>-</td>\n</tr>\n<tr>\n<td>при 0°С</td>\n<td>0,23</td>\n</tr>\n<tr>\n<td>при 50°С</td>\n<td>0,25</td>\n</tr>\n<tr>\n<td>Коэффициент теплопроводности, ккал/(м·ч·°С)</td>\n<td>0,20</td>\n</tr>\n</tbody>\n</table>\nТермический коэффициент линейного расширения зависит от температуры:\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\n<tbody>\n<tr>\n<td>Температура, °С</td>\n<td>от -60 до -10</td>\n<td>19,6</td>\n<td>30</td>\n<td>40</td>\n<td>200</td>\n<td>300</td>\n</tr>\n<tr>\n<td>Термический коэффициент линейного расширения α·105, 1/°С</td>\n<td>8</td>\n<td>54</td>\n<td>28</td>\n<td>11</td>\n<td>25</td>\n<td>64</td>\n</tr>\n</tbody>\n</table>\nНа практике удобнее пользоваться средними значениями термического коэффициента линейного расширения для определенных интервалов температур. Следует также учитывать, что при нагревании изделий из фторопласта-4 в них часто возникают внутренние напряжения, вызывающие необратимое изменение размеров. Иногда вместо ожидаемого при нагревании удлинения образца он сокращается.\n\nДанные, приведенные ниже, относятся к образцам, в которых полностью отсутствуют внутренние напряжения:\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\n<tbody>\n<tr>\n<td>Температура, °C</td>\n<td>Термический коэффициент линейного расширения α·105, 1/°C</td>\n<td>Изменение размеров изделия*, %</td>\n<td>Температура, °C</td>\n<td>Термический коэффициент линейного расширения α·105, 1/°C</td>\n<td>Изменение размеров изделия*, %</td>\n</tr>\n<tr>\n<td>от -193 до +25</td>\n<td>8,6</td>\n<td>-1,85</td>\n<td>от +25 до +100</td>\n<td>12,4</td>\n<td>+0,93</td>\n</tr>\n<tr>\n<td>от -150 до +25</td>\n<td>9,6</td>\n<td>-1,68</td>\n<td>от +25 до +150</td>\n<td>13,5</td>\n<td>+1,59</td>\n</tr>\n<tr>\n<td>от -100 до +25</td>\n<td>11,2</td>\n<td>-1,40</td>\n<td>от +25 до +200</td>\n<td>15,1</td>\n<td>+2,64</td>\n</tr>\n<tr>\n<td>от -50 до +25</td>\n<td>13,5</td>\n<td>-1,01</td>\n<td>от +25 до +250</td>\n<td>17,4</td>\n<td>+3,92</td>\n</tr>\n<tr>\n<td> от 0 до +25</td>\n<td>20,0</td>\n<td>-0,50</td>\n<td>от +25 до +300</td>\n<td>21,8</td>\n<td>+5,99</td>\n</tr>\n<tr>\n<td>от +25 до +50</td>\n<td>12,4</td>\n<td>+0,31</td>\n<td>от +25 до +300</td>\n<td>21,8</td>\n<td>+5,99</td>\n</tr>\n</tbody>\n</table>\n* От размера при 25°С.\n<h2>ЭЛЕКТРИЧЕСКИЕ СВОЙТСВА ФТОРОПЛАСТА-4</h2>\nПоказатели электрических свойств фторопласта-4 приведены ниже:\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\n<tbody>\n<tr>\n<td>Удельное электрическое сопротивление:</td>\n<td></td>\n</tr>\n<tr>\n<td>-поверхностное, Ом</td>\n<td>&gt;10<sup>17</sup></td>\n</tr>\n<tr>\n<td>-на воздухе со 100%-ной относительной влажностью</td>\n<td>&gt;10<sup>12</sup></td>\n</tr>\n<tr>\n<td>-объемное (до 150<sup>о</sup>С), Ом·см</td>\n<td>101<sup>7</sup> - 10<sup>20</sup></td>\n</tr>\n<tr>\n<td>-после длительного пребывания в воде не меняется</td>\n<td>1,9-2,2</td>\n</tr>\n<tr>\n<td>Диэлектрическая проницаемость (при 60 - 1010 Гц)</td>\n<td></td>\n</tr>\n<tr>\n<td>Тангенс угла диэлектрических потерь (при 60 - 1010 Гц)</td>\n<td>&lt;1·10<sup>17</sup></td>\n</tr>\n<tr>\n<td>Электрическая прочность, кВ/мм:</td>\n<td></td>\n</tr>\n<tr>\n<td>-при толщине образца 4 мм</td>\n<td>25-27</td>\n</tr>\n<tr>\n<td>-при толщине образца 0,1 - 0,3 мм</td>\n<td>40-80</td>\n</tr>\n<tr>\n<td>-при толщине образца 0,005 - 0,02 мм</td>\n<td>200-300</td>\n</tr>\n<tr>\n<td>Дугостойкость, с (сплошного токопроводящего слоя не образуется)</td>\n<td>250-700</td>\n</tr>\n</tbody>\n</table>\nДанные о зависимости тангенса угла диэлектрических потерь от частоты приведены ниже:\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\n<tbody>\n<tr>\n<td>Частота, Гц</td>\n<td>60</td>\n<td>10<sup>3</sup></td>\n<td>10<sup>4</sup></td>\n<td>10<sup>5</sup></td>\n<td>10<sup>6</sup></td>\n<td>10<sup>7</sup></td>\n</tr>\n<tr>\n<td>tgδ·10<sup>4</sup></td>\n<td>0,5</td>\n<td>0,3</td>\n<td>0,4</td>\n<td>0,7</td>\n<td>0,7</td>\n<td>0,7</td>\n</tr>\n</tbody>\n</table>\nДиэлектрическая проницаемость фторопласта-4 вплоть до 1010 Гц не зависит от частоты, а зависит от плотности: є= <u>1+0,238*d</u>\n2-0,119*d\nгде d - плотность при данной степени кристалличности и температуре.\nТангенс угла диэлектрических потерь остается постоянным при температуре от -60 до 250<sup>о</sup>С.\nПрогрев при 300<sup>о</sup>С в течение 6 месяцев не влияет на диэлектрические свойства фторопласта-4.\n<h2>ХИМИЧЕСКИЕ И ДРУГИЕ СВОЙСТВА ФТОРОПЛАСТА-4</h2>\nФторопласт-4 является самым стойким из всех известных металлов - пластмасс, металлов, стекол, эмалей, сплавов и т.п. На него совершенно не действуют кислоты, окислители, щелочи, растворители. На фторопласт-4 действуют только расплавленные щелочные металлы и их комплексные соединения с аммиаком, нафталином, пиридином, а также трехфтористых хлор и элементный фтор при повышенных температурах. При температурах выше 327<sup>о</sup>С фторопласт набухает в жидких фторуглеродах, например в перфторкеросине. При 20<sup>о</sup>С фторопласт-4 слегка набухает (3 - 9%) в фторхлорсодержащих газах (фреонах).\n\nВыше 350<sup>о</sup>С фторопласт-4 реагирует с щелочеземельными металлами и их соединениями (окислами и карбонатами), а также с окислами некоторых других металлов (свинца, кадмия, меди).\n\nФторопласт-4 не смачивается водой при кратковременном погружении (угол смачивания 126<sup>о</sup>С), но смачивается при длительном пребывании в дистиллированной воде (15 - 20 суток). В соленой воде (например, морской) на поверхности фторопласта-4 через 15 - 20 суток отлагается пленка солей, смываемая дистиллированной водой.\n\nВодопоглощение за 24 часа (и более продолжительное время) - ниже ошибки взвешивания (0,00%).\n\nФторопласт-4 абсолютно стоек в тропических условиях и не подвижен действию грибков (но и не подавляет их развитие).\n\nВлагопроницаемость при 20<sup>о</sup>С равна 3·10<sup>-9</sup> - 6·10<sup>-9</sup> г/(см·ч·мм рт. ст.); паропроницаемость при 20<sup>о</sup>С составляет 0,6·10<sup>-9</sup> - 1,2·10<sup>-9</sup> г/(см·ч·мм рт. ст.).\n\nДанные о газопроницаемости пленки из фтороплавта-4 (при отсутствии пор) толщиной 0,1 мм при 20<sup>о</sup>С [в см<sup>3</sup>/(см·с·мм рт. ст.)] приведены ниже:\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\n<tbody>\n<tr>\n<td>Воздух</td>\n<td>1,1*10<sup>-9</sup></td>\n</tr>\n<tr>\n<td>Азот</td>\n<td>0,7*10<sup>-9</sup></td>\n</tr>\n<tr>\n<td>Кислород</td>\n<td>2,3*10<sup>-9</sup></td>\n</tr>\n<tr>\n<td>Водород</td>\n<td>6,3*10<sup>-9</sup></td>\n</tr>\n<tr>\n<td>Двуокись углерода</td>\n<td>4,8*10<sup>-9</sup></td>\n</tr>\n</tbody>\n</table>\nПри наличии пористости проницаемость может увеличиваться до 1000 раз.\n\nФторопласт-4 предназначен для видимого света только при малой толщине пленки:\n<table class="responsive-table" width="100%">\n<tbody>\n<tr>\n<td width="95%"></td>\n</tr>\n</tbody>\n<tbody>\n<tr>\n<td>Толщина пленки, мм</td>\n<td>0,05</td>\n<td>0,10</td>\n<td>0,15</td>\n<td>1,00</td>\n</tr>\n<tr>\n<td>Пропускание, %</td>\n<td>88</td>\n</tr>\n</tbody>\n</table>\n</div>', 'Свойства фторопласта-4', '', 'inherit', 'closed', 'closed', '', '2893-autosave-v1', '', '', '2018-06-24 22:04:20', '2018-06-24 22:04:20', '', 2893, 'Фторопласт -4 - кристаллический полимер, температурой плавления кристаллитов 327°С и температурой стеклования аморфных участков от -100 до -120°С. Даже при температуре выше температуры разложения (415°С) фторопласт-4 не переходит в вязкотекучее состояние ', 0, 'revision', '', 0);
INSERT INTO `fttwp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(3182, 1, '2018-05-07 19:31:56', '2018-05-07 19:31:56', '<p>Фторопласт -4 - кристаллический полимер, температурой плавления кристаллитов 327°С и температурой стеклования аморфных участков от -100 до -120°С. Даже при температуре выше температуры разложения (415°С) фторопласт-4 не переходит в вязкотекучее состояние (при 370°С вязкость его расплава равна ≈10<sup>11</sup>П, т.е. в 1000000 раз больше вязкости, (необходимой для литья под давлением), поэтому переработка его возможна только методом спекания отпрессованных таблеток.\r\nВ зависимости от скорости охлаждения (до температуры ниже 250°С) после спекания можно получить закаленные изделия со степенью кристалличности ≈50% и плотностью ≈2,15 г/см<sup>3</sup> или незакаленные со степенью кристалличности более 65% плотностью выше 2,20 г/см3.При температуре эксплуатации и от -269°С до +260°С степень кристалличности, достигнутая при данном режиме охлаждения, не меняется, при температуре выше 260°С степень кристалличности постепенно увеличивается, особенно быстро она вырастает при 310 - 315°С.</p>\r\n<div>\r\n\r\n\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td><strong>Степень кристалличности, %</strong></td>\r\n<td><strong>Плотность при\r\n23°С, г/см<sup>3</sup></strong></td>\r\n<td><strong>Степень кристалличности, %</strong></td>\r\n<td><strong>Плотность при\r\n23°С, г/см<sup>3</sup></strong></td>\r\n</tr>\r\n<tr>\r\n<td>40.0</td>\r\n<td>2.12</td>\r\n<td>69.4</td>\r\n<td>2.21</td>\r\n</tr>\r\n<tr>\r\n<td>43.2</td>\r\n<td>2.13</td>\r\n<td>72.8</td>\r\n<td>2.22</td>\r\n</tr>\r\n<tr>\r\n<td>46.5</td>\r\n<td>2.14</td>\r\n<td>75.2</td>\r\n<td>2.23</td>\r\n</tr>\r\n<tr>\r\n<td>49.7</td>\r\n<td>2.15</td>\r\n<td>78.0</td>\r\n<td>2.24</td>\r\n</tr>\r\n<tr>\r\n<td>53.0</td>\r\n<td>2.16</td>\r\n<td>80.7</td>\r\n<td>2.25</td>\r\n</tr>\r\n<tr>\r\n<td>56.3</td>\r\n<td>2.17</td>\r\n<td>82.6</td>\r\n<td>2.26</td>\r\n</tr>\r\n<tr>\r\n<td>59.7</td>\r\n<td>2.18</td>\r\n<td>85.2</td>\r\n<td>2.27</td>\r\n</tr>\r\n<tr>\r\n<td>63.1</td>\r\n<td>2.19</td>\r\n<td>89.0</td>\r\n<td>2.28</td>\r\n</tr>\r\n<tr>\r\n<td>66.5</td>\r\n<td>2.20</td>\r\n<td>-</td>\r\n<td>-</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\nОб отсутствии же пористости свидетельствует полная прозрачность образца во время спекания при 370-390°С. Даже незначительная пористость вызывает мутность образца. Пористость, равная примерно 0,1-0,2%, заметно влияет на точность определения плотности.\r\nДанные о зависимости удельного объема и плотности от температуры для образца со степенью кристалличности 68% (плотность медленно охлажденного изделия) приведены ниже:\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td><strong>Температура, °С</strong></td>\r\n<td><strong>Удельный объем, см<sup>3</sup>/г</strong></td>\r\n<td><strong>Плотность, г/см<sup>3</sup></strong></td>\r\n<td><strong>Температура, °С</strong></td>\r\n<td><strong>Удельный объем, cм<sup>3</sup>/г</strong></td>\r\n<td><strong>Плотность, г/см<sup>3</sup></strong></td>\r\n</tr>\r\n<tr>\r\n<td>-50</td>\r\n<td>0.440</td>\r\n<td>2.27</td>\r\n<td>175</td>\r\n<td>0.4769</td>\r\n<td>2.10</td>\r\n</tr>\r\n<tr>\r\n<td>-25</td>\r\n<td>0.443</td>\r\n<td>2.26</td>\r\n<td>200</td>\r\n<td>0.482</td>\r\n<td>2.08</td>\r\n</tr>\r\n<tr>\r\n<td>0</td>\r\n<td>0.447</td>\r\n<td>2.24</td>\r\n<td>225</td>\r\n<td>0.488</td>\r\n<td>2.05</td>\r\n</tr>\r\n<tr>\r\n<td>+25</td>\r\n<td>0.453*</td>\r\n<td>2.21</td>\r\n<td>250</td>\r\n<td>0.495</td>\r\n<td>2.02</td>\r\n</tr>\r\n<tr>\r\n<td>+50</td>\r\n<td>0.456</td>\r\n<td>2.19</td>\r\n<td>275</td>\r\n<td>0.503</td>\r\n<td>1.99</td>\r\n</tr>\r\n<tr>\r\n<td>+75</td>\r\n<td>0.459</td>\r\n<td>2.18</td>\r\n<td>300</td>\r\n<td>0.514</td>\r\n<td>1.95</td>\r\n</tr>\r\n<tr>\r\n<td>+100</td>\r\n<td>0.463</td>\r\n<td>2.16</td>\r\n<td>325</td>\r\n<td>0.534</td>\r\n<td>1.88</td>\r\n</tr>\r\n<tr>\r\n<td>+125</td>\r\n<td>0.467</td>\r\n<td>2.14</td>\r\n<td>327</td>\r\n<td>0.640**</td>\r\n<td>1.57</td>\r\n</tr>\r\n<tr>\r\n<td>+150</td>\r\n<td>0.471</td>\r\n<td>2.12</td>\r\n<td>350</td>\r\n<td>0.655</td>\r\n<td>1.53</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n* При нагревании от 19,6 до 22°C удлиненный объём увеличивается на 0,74%\r\n** При 327°С удлиненный объём увеличивается на 20%.\r\n\r\n<strong>                                ФИЗИКО-МЕХАНИЧЕСКИЕ СВОЙСТВА ФТОРОПЛАСТА-4\r\n</strong>\r\n<strong>Основные показатели физико-механических свойств фторопласта-4 приведены ниже:</strong>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td><strong>Разрушающее напряжение, кгс/см<sup>2</sup></strong></td>\r\n<td>Значения</td>\r\n</tr>\r\n<tr>\r\n<td>при растяжении:</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- незакаленный образец (кристалличность 05-08%)</td>\r\n<td>140-350*</td>\r\n</tr>\r\n<tr>\r\n<td>- закаленный образец (кристалличность 50%)</td>\r\n<td>160-315*</td>\r\n</tr>\r\n<tr>\r\n<td>при сжатии:</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- при 1%-ной деформации</td>\r\n<td>100</td>\r\n</tr>\r\n<tr>\r\n<td>- 10%-ной деформации</td>\r\n<td>185</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Сопротивлению изгибу (стрела прогиба 6 мм)</strong></td>\r\n<td>185</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Относительное удлинение при разрыт, %</strong></td>\r\n<td>250-500</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Остаточное удлинение, %</strong></td>\r\n<td>250-350</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Напряжение при 10%-ном удлинении, кгс/см<sup>2</sup></strong></td>\r\n<td>110-120</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Модуль упругости, кгс/см<sup>2</sup></strong></td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- при изгибе при 20°С</td>\r\n<td>4700-8500</td>\r\n</tr>\r\n<tr>\r\n<td>- сдвиге 2700</td>\r\n<td>2700</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Ударная вязкость, кгс·см/см<sup>2</sup></strong></td>\r\n<td>100 (не ломается)</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Ударное растяжение, кгс·см/см<sup>2</sup> (DIN 53448)</strong></td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- при 20°С</td>\r\n<td>650</td>\r\n</tr>\r\n<tr>\r\n<td>- 23°С</td>\r\n<td>680</td>\r\n</tr>\r\n<tr>\r\n<td>(удлинение при 20°С - 20%, при 23°С - 30%)</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Твердость:</strong></td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>по Бринеллю, кгс/мм<sup>2</sup></td>\r\n<td>3-4</td>\r\n</tr>\r\n<tr>\r\n<td>по Шору при 20°С</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- шкала С</td>\r\n<td>85-87</td>\r\n</tr>\r\n<tr>\r\n<td>- шкала D</td>\r\n<td>55-59</td>\r\n</tr>\r\n<tr>\r\n<td>Твердость по Роквеллу</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- шкала I</td>\r\n<td>80-95</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n· В зависимости от того, как вырезан образец: поперек направления прессования-высокие значения, вдоль направления прессования-малые.\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td><strong>Показатели</strong></td>\r\n<td colspan="10"><strong>Температура, °С</strong></td>\r\n</tr>\r\n<tr>\r\n<td>-</td>\r\n<td>-60</td>\r\n<td>-40</td>\r\n<td>-20</td>\r\n<td>0</td>\r\n<td>20</td>\r\n<td>40</td>\r\n<td>60</td>\r\n<td>80</td>\r\n<td>100</td>\r\n<td>120</td>\r\n</tr>\r\n<tr>\r\n<td>Разрушающее напряжение при растяжении, кгс/см<sup>2</sup></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>- незакаленный образец</td>\r\n<td>-</td>\r\n<td>350</td>\r\n<td>325</td>\r\n<td>300</td>\r\n<td>200</td>\r\n<td>180</td>\r\n<td>-</td>\r\n<td>135</td>\r\n<td>115</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- закаленный образец</td>\r\n<td>-</td>\r\n<td>500</td>\r\n<td>440</td>\r\n<td>330</td>\r\n<td>250</td>\r\n<td>240</td>\r\n<td>-</td>\r\n<td>200</td>\r\n<td>190</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>Относительное удлинение при разрыве, %</td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>- незакаленный образец</td>\r\n<td>-</td>\r\n<td>70</td>\r\n<td>100</td>\r\n<td>150</td>\r\n<td>470</td>\r\n<td>650</td>\r\n<td>-</td>\r\n<td>600</td>\r\n<td>540</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- закаленный образец</td>\r\n<td>-</td>\r\n<td>100</td>\r\n<td>160</td>\r\n<td>190</td>\r\n<td>400</td>\r\n<td>500</td>\r\n<td>-</td>\r\n<td>500</td>\r\n<td>480</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>Модуль упругости, кгс/см<sup>2</sup></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>при сжатии</td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>- незакаленный образец</td>\r\n<td>18000</td>\r\n<td>17000</td>\r\n<td>15000</td>\r\n<td>11000</td>\r\n<td>7000</td>\r\n<td>4500</td>\r\n<td>3300</td>\r\n<td>2400</td>\r\n<td>1700</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>при сжатии</td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>- незакаленный образец</td>\r\n<td>27800</td>\r\n<td>23900</td>\r\n<td>23300</td>\r\n<td>18100</td>\r\n<td>8500</td>\r\n<td>5100</td>\r\n<td>4800</td>\r\n<td>3800</td>\r\n<td>-</td>\r\n<td>2450</td>\r\n</tr>\r\n<tr>\r\n<td>- закаленный образец</td>\r\n<td>13200</td>\r\n<td>11300</td>\r\n<td>9800</td>\r\n<td>7400</td>\r\n<td>4700</td>\r\n<td>4000</td>\r\n<td>2900</td>\r\n<td>2180</td>\r\n<td>-</td>\r\n<td>1100</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\nДанные о зависимости физико-механических свойств фторопласта-4 от температуры приведены ниже.\r\n\r\n<strong>Физико-механические свойства фторопласта-4 при низких температурах\r\n</strong>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td><strong>Показатели</strong></td>\r\n<td colspan="6"><strong>Температура, °С</strong></td>\r\n</tr>\r\n<tr>\r\n<td></td>\r\n<td>-93</td>\r\n<td>-123</td>\r\n<td>-153</td>\r\n<td>-193</td>\r\n<td>-223</td>\r\n<td>-269</td>\r\n</tr>\r\n<tr>\r\n<td>Разрушающее напряжение при сжатии *, кгс/см<sup>2</sup></td>\r\n<td>350</td>\r\n<td>-</td>\r\n<td>980</td>\r\n<td>1260</td>\r\n<td>1554</td>\r\n<td>1750-1960</td>\r\n</tr>\r\n<tr>\r\n<td>Модуль упругости при сжатии, кгс/см<sup>2</sup></td>\r\n<td>-</td>\r\n<td>52500</td>\r\n<td>-</td>\r\n<td>-</td>\r\n<td>-</td>\r\n<td>70000</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n* Разрушающее напряжение при сжатии равно напряжению, при котором деформация составляет 0,2%.\r\n\r\n<strong>Зависимость деформации фторопласта-4 при сжатии от температуры:</strong>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td><strong>Деформация, %</strong></td>\r\n<td colspan="7"><strong>Нагрузка, вызывающая деформацию, кгс/см</strong><sup>2</sup></td>\r\n</tr>\r\n<tr>\r\n<td>-</td>\r\n<td>-50°С</td>\r\n<td> 0°С</td>\r\n<td> 25°С</td>\r\n<td>50°С</td>\r\n<td>100°С</td>\r\n<td>150°С</td>\r\n<td>200°С</td>\r\n</tr>\r\n<tr>\r\n<td>1</td>\r\n<td>203</td>\r\n<td>157</td>\r\n<td>62</td>\r\n<td>49</td>\r\n<td>31</td>\r\n<td>17,5</td>\r\n<td>11</td>\r\n</tr>\r\n<tr>\r\n<td>2</td>\r\n<td>304</td>\r\n<td>210</td>\r\n<td>92</td>\r\n<td>66</td>\r\n<td>39</td>\r\n<td>27</td>\r\n<td>20</td>\r\n</tr>\r\n<tr>\r\n<td>3</td>\r\n<td>350</td>\r\n<td>236</td>\r\n<td>105</td>\r\n<td>77</td>\r\n<td>48</td>\r\n<td>33</td>\r\n<td>27</td>\r\n</tr>\r\n<tr>\r\n<td>4</td>\r\n<td>374</td>\r\n<td>251</td>\r\n<td>120</td>\r\n<td>85</td>\r\n<td>59</td>\r\n<td>39</td>\r\n<td>31</td>\r\n</tr>\r\n<tr>\r\n<td>5</td>\r\n<td>390</td>\r\n<td>262</td>\r\n<td>127</td>\r\n<td>92</td>\r\n<td>62</td>\r\n<td>44</td>\r\n<td>35</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\nОдним из важнейших прочностных показателей является предел текучести при растяжении, т.е. то напряжение, при котором возникают остаточные деформации. Он зависит от степени кристалличности, скорости растяжения и температуры. При степени кристалличности 65% и скорости растяжения 100 мм/мин зависимость предела текучести от абсолютной температуры Т (в К) описывается эмпирической формулой (справедливой от 20 до 300°С):\r\nlgσT= 0,53166+483,64/Т\r\nНиже приведены значения пределов текучести для некоторых температур, рассчитанные по этой формуле:\r\nТемпература, °С ........................ 25.........50.........75......100.......150......200......250\r\nПредел текучести, кгс/см2 ....... 42,4.....106,9.....83,5.....67,2.....46,6.....35,5.....28,6\r\n\r\nПри длительном воздействии нагрузок остаточные деформации возникают при меньших напряжениях (40-50% от рассчитанных по формуле).\r\nПри конструировании изделий из фторопласта-4 следует учитывать ползучесть. Ползучесть (деформация при длительном действии нагрузки) рассчитывается по формуле:\r\nlgγt=lgγ1+a·lgt\r\nгде γt - деформация за t сут; γ1 - деформация за 1 сут; а - коэффициент, зависящий в основном от температуры и в меньшей степени от нагрузки, если она не превышает 40-50% предела текучести.\r\nЗначения коэффициента a и некоторые данные о ползучести для образцов со степенью кристалличности 50% приведены в таблице. Деформация за 1 сут (γ1) при других нагрузках и температурах определяется опытным путем. При степени кристалличности 65-68% ползучесть меньше.\r\n\r\n<strong>   Ползучесть фторопласта-4</strong>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td><strong>Температура, °С</strong></td>\r\n<td><strong>Нагрузка, кгс/см<sup>2</sup></strong></td>\r\n<td colspan="2"><strong>Деформация, %</strong></td>\r\n<td><strong>Коэффициент а\r\n</strong></td>\r\n</tr>\r\n<tr>\r\n<td colspan="2">Сжатие</td>\r\n<td>1 сут (γ1)</td>\r\n<td>4 сут (γ4)</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>20</td>\r\n<td>33</td>\r\n<td>6,00</td>\r\n<td>6,25</td>\r\n<td>0,030</td>\r\n</tr>\r\n<tr>\r\n<td>20</td>\r\n<td>21</td>\r\n<td>3,05</td>\r\n<td>3,19</td>\r\n<td>0,032</td>\r\n</tr>\r\n<tr>\r\n<td colspan="2">Растяжение</td>\r\n<td>1 сут (γ1)</td>\r\n<td>4 сут (γ4)</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>40</td>\r\n<td>28</td>\r\n<td>2,72</td>\r\n<td>2,87</td>\r\n<td>0,038</td>\r\n</tr>\r\n<tr>\r\n<td>100</td>\r\n<td>28</td>\r\n<td>5,58</td>\r\n<td>5,90</td>\r\n<td>0,040</td>\r\n</tr>\r\n<tr>\r\n<td>140</td>\r\n<td>21</td>\r\n<td>4,67</td>\r\n<td>4,94</td>\r\n<td>0,042</td>\r\n</tr>\r\n<tr>\r\n<td>200</td>\r\n<td>14</td>\r\n<td>4,08</td>\r\n<td>4,50</td>\r\n<td>0,048</td>\r\n</tr>\r\n<tr>\r\n<td>250</td>\r\n<td>14</td>\r\n<td>5,17</td>\r\n<td>5,58</td>\r\n<td>0,055</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<strong>                                           АНТИФРИКЦИОННЫЕ СВОЙСТВА ФТОРОПЛАСТА-4\r\n</strong>\r\nДанные о зависимости коэффициента трения от нагрузки [статической и динамической (при малых скоростях) коэффициенты трения фторопласта-4 по стали без смазки одинаковы] приведены ниже:\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Нагрузка, кгс/см2</td>\r\n<td>1</td>\r\n<td>3</td>\r\n<td>10</td>\r\n<td>20</td>\r\n</tr>\r\n<tr>\r\n<td>Коэффициент трения</td>\r\n<td>0,4</td>\r\n<td>0,1</td>\r\n<td>0,06</td>\r\n<td>0,05</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\nПри наличии смазки он примерно в 2 раза меньше.\r\nДинамический коэффициент трения фторопласта-4 по стали без смазки при нагрузке ~ 20 кгс/см2 зависит от скорости скольжения:\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Скорость скольжения, см/c</td>\r\n<td>4</td>\r\n<td>8</td>\r\n<td>20</td>\r\n<td>40</td>\r\n<td>80</td>\r\n<td>160</td>\r\n</tr>\r\n<tr>\r\n<td>Динамический коэффициент трения</td>\r\n<td>0,05</td>\r\n<td>0,1</td>\r\n<td>0,15</td>\r\n<td>0,23</td>\r\n<td>0,24</td>\r\n<td>0,27</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\nВ присутствии наполнителя при малых скоростях скольжения коэффициент трения несколько выше, а при больших скоростях - ниже, чем коэффициент трения чистого фторопласта-4 по стали.\r\nПри 327°С (на поверхности трения) коэффициент трения фторопласта-4 по стали резко возрастает (в несколько раз), что приводит к катастрофически быстрому износу и разрушению подшипника.\r\n\r\n<strong>                                  ТЕПЛОФИЗИЧЕСКИЕ СВОЙСТВА ФТОРОПЛАСТА-4\r\n</strong>\r\nНеспеченный фторопласт-4 (в виде порошка) имеет степень кристалличности 95 - 98%, после спекания - от 50% (закаленный) до 68 - 70% (незакаленный). Ниже 19,6°С элементарная ячейка кристалла фторопласта-4 состоит из 13 групп CF2, выше 19,6°С - из 15 групп CF2. При 19,6°С триклиническая упаковка переходит в менее упорядоченную, гексагональную, что сопровождается увеличение объема кристаллитов на 0,0058 см3/г (1,2 объемн. %), или увеличением объема образца при степени кристалличности 68% на 0,74%. При наличии внешнего давления точка перехода понижается на 0,013°С на каждую атмосферу. При 30°С имеет место второй переход кристаллической структуры, но изменение объема составляет едва 1/10 часть изменения объема при 19,6°С. Под высоким давлением (4500 кгс/см2 при 70°С) возникает третий переход.\r\nТемпература стеклования аморфных участков, определенная по температуре хрупкости, колеблется от -97 до -100°С, а по точке перегиба кривой зависимости модуля упругости составляет -120°С. Температура перехода аморфного твердого тела в переохлажденную жидкость равна 127°С.\r\nПри 327°С кристаллиты фторопласта-4 плавятся, и он становится полностью аморфным, совершенно прозрачным (при отсутствии пористости), высокоэластичным, но не течет (вязкость выше 1011 П). Объем возрастает на 20%.\r\n\r\nТочка плавления зависит от внешнего давления - на каждую атмосферу повышается на 0,154 °С. При остывании расплава ниже 327 °С образец мутнеет и становится непрозрачным - молочно-белым.   Скорость кристаллизации зависит от температуры (максимальная скорость при 310-315 °С), от продолжительности выдержки в расплавленном состоянии при 370-390 °С (чем больше время спекания, тем быстрее кристаллизуется образец) и от среднего молекулярного веса полимера (чем ниже молекулярный вес полимера, тем быстрее он кристаллизуется). На этом основан метод косвенной оценки молекулярного веса фторопласта-4: образец в виде диска толщиной 2 мм спекают при 370 °С в течение 13 ч и охлаждают от 370 до 250 °С в течение 5 ч. По плотности полученного образца при 23 °С можно оценить молекулярный вес: 2,16-2,19 г/см3-для высокомолекулярного полимера, 2,20-2,22 г/см3-для низкомолекулярного.\r\n\r\n<strong>Ниже приведены некоторые теплофизические свойства фторопласта-4:</strong>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Теплостойкость по Вика (при нагрузке 5 кгс), °С</td>\r\n<td>110</td>\r\n</tr>\r\n<tr>\r\n<td>Удельная теплоемкость, ккал/(кг·°С)</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>при 0°С</td>\r\n<td>0,23</td>\r\n</tr>\r\n<tr>\r\n<td>при 50°С</td>\r\n<td>0,25</td>\r\n</tr>\r\n<tr>\r\n<td>Коэффициент теплопроводности, ккал/(м·ч·°С)</td>\r\n<td>0,20</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\nТермический коэффициент линейного расширения зависит от температуры:\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Температура, °С</td>\r\n<td>от -60 до -10</td>\r\n<td>19,6</td>\r\n<td>30</td>\r\n<td>40</td>\r\n<td>200</td>\r\n<td>300</td>\r\n</tr>\r\n<tr>\r\n<td>Термический коэффициент линейного расширения α·105, 1/°С</td>\r\n<td>8</td>\r\n<td>54</td>\r\n<td>28</td>\r\n<td>11</td>\r\n<td>25</td>\r\n<td>64</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\nНа практике удобнее пользоваться средними значениями термического коэффициента линейного расширения для определенных интервалов температур. Следует также учитывать, что при нагревании изделий из фторопласта-4 в них часто возникают внутренние напряжения, вызывающие необратимое изменение размеров. Иногда вместо ожидаемого при нагревании удлинения образца он сокращается.\r\nДанные, приведенные ниже, относятся к образцам, в которых полностью отсутствуют внутренние напряжения:\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Температура, °C</td>\r\n<td>Термический коэффициент линейного расширения α·105, 1/°C</td>\r\n<td>Изменение размеров изделия*, %</td>\r\n<td>Температура, °C</td>\r\n<td>Термический коэффициент линейного расширения α·105, 1/°C</td>\r\n<td>Изменение размеров изделия*, %</td>\r\n</tr>\r\n<tr>\r\n<td>от -193 до +25</td>\r\n<td>8,6</td>\r\n<td>-1,85</td>\r\n<td>от +25 до +100</td>\r\n<td>12,4</td>\r\n<td>+0,93</td>\r\n</tr>\r\n<tr>\r\n<td>от -150 до +25</td>\r\n<td>9,6</td>\r\n<td>-1,68</td>\r\n<td>от +25 до +150</td>\r\n<td>13,5</td>\r\n<td>+1,59</td>\r\n</tr>\r\n<tr>\r\n<td>от -100 до +25</td>\r\n<td>11,2</td>\r\n<td>-1,40</td>\r\n<td>от +25 до +200</td>\r\n<td>15,1</td>\r\n<td>+2,64</td>\r\n</tr>\r\n<tr>\r\n<td>от -50 до +25</td>\r\n<td>13,5</td>\r\n<td>-1,01</td>\r\n<td>от +25 до +250</td>\r\n<td>17,4</td>\r\n<td>+3,92</td>\r\n</tr>\r\n<tr>\r\n<td> от 0 до +25</td>\r\n<td>20,0</td>\r\n<td>-0,50</td>\r\n<td>от +25 до +300</td>\r\n<td>21,8</td>\r\n<td>+5,99</td>\r\n</tr>\r\n<tr>\r\n<td>от +25 до +50</td>\r\n<td>12,4</td>\r\n<td>+0,31</td>\r\n<td>от +25 до +300</td>\r\n<td>21,8</td>\r\n<td>+5,99</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n* От размера при 25°С.\r\n\r\n<strong>ЭЛЕКТРИЧЕСКИЕ СВОЙТСВА ФТОРОПЛАСТА-4</strong>\r\n\r\nПоказатели электрических свойств фторопласта-4 приведены ниже:\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Удельное электрическое сопротивление:</td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>-поверхностное, Ом</td>\r\n<td>&gt;10<sup>17</sup></td>\r\n</tr>\r\n<tr>\r\n<td>-на воздухе со 100%-ной относительной влажностью</td>\r\n<td>&gt;10<sup>12</sup></td>\r\n</tr>\r\n<tr>\r\n<td>-объемное (до 150<sup>о</sup>С), Ом·см</td>\r\n<td>101<sup>7</sup> - 10<sup>20</sup></td>\r\n</tr>\r\n<tr>\r\n<td>-после длительного пребывания в воде не меняется</td>\r\n<td>1,9-2,2</td>\r\n</tr>\r\n<tr>\r\n<td>Диэлектрическая проницаемость (при 60 - 1010 Гц)</td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>Тангенс угла диэлектрических потерь (при 60 - 1010 Гц)</td>\r\n<td>&lt;1·10<sup>17</sup></td>\r\n</tr>\r\n<tr>\r\n<td>Электрическая прочность, кВ/мм:</td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>-при толщине образца 4 мм</td>\r\n<td>25-27</td>\r\n</tr>\r\n<tr>\r\n<td>-при толщине образца 0,1 - 0,3 мм</td>\r\n<td>40-80</td>\r\n</tr>\r\n<tr>\r\n<td>-при толщине образца 0,005 - 0,02 мм</td>\r\n<td>200-300</td>\r\n</tr>\r\n<tr>\r\n<td>Дугостойкость, с (сплошного токопроводящего слоя не образуется)</td>\r\n<td>250-700</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\nДанные о зависимости тангенса угла диэлектрических потерь от частоты приведены ниже:\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Частота, Гц</td>\r\n<td>60</td>\r\n<td>10<sup>3</sup></td>\r\n<td>10<sup>4</sup></td>\r\n<td>10<sup>5</sup></td>\r\n<td>10<sup>6</sup></td>\r\n<td>10<sup>7</sup></td>\r\n</tr>\r\n<tr>\r\n<td>tgδ·10<sup>4</sup></td>\r\n<td>0,5</td>\r\n<td>0,3</td>\r\n<td>0,4</td>\r\n<td>0,7</td>\r\n<td>0,7</td>\r\n<td>0,7</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\nДиэлектрическая проницаемость фторопласта-4 вплоть до 1010 Гц не зависит от частоты, а зависит от плотности: є= <u>1+0,238*d</u>\r\n2-0,119*d\r\nгде d - плотность при данной степени кристалличности и температуре.\r\nТангенс угла диэлектрических потерь остается постоянным при температуре от -60 до 250<sup>о</sup>С.\r\nПрогрев при 300<sup>о</sup>С в течение 6 месяцев не влияет на диэлектрические свойства фторопласта-4.\r\n\r\nХИМИЧЕСКИЕ И ДРУГИЕ СВОЙСТВА ФТОРОПЛАСТА-4\r\n\r\nФторопласт-4 является самым стойким из всех известных металлов - пластмасс, металлов, стекол, эмалей, сплавов и т.п. На него совершенно не действуют кислоты, окислители, щелочи, растворители. На фторопласт-4 действуют только расплавленные щелочные металлы и их комплексные соединения с аммиаком, нафталином, пиридином, а также трехфтористых хлор и элементный фтор при повышенных температурах. При температурах выше 327<sup>о</sup>С фторопласт набухает в жидких фторуглеродах, например в перфторкеросине. При 20<sup>о</sup>С фторопласт-4 слегка набухает (3 - 9%) в фторхлорсодержащих газах (фреонах).\r\nВыше 350<sup>о</sup>С фторопласт-4 реагирует с щелочеземельными металлами и их соединениями (окислами и карбонатами), а также с окислами некоторых других металлов (свинца, кадмия, меди).\r\nФторопласт-4 не смачивается водой при кратковременном погружении (угол смачивания 126<sup>о</sup>С), но смачивается при длительном пребывании в дистиллированной воде (15 - 20 суток). В соленой воде (например, морской) на поверхности фторопласта-4 через 15 - 20 суток отлагается пленка солей, смываемая дистиллированной водой.\r\nВодопоглощение за 24 часа (и более продолжительное время) - ниже ошибки взвешивания (0,00%).\r\nФторопласт-4 абсолютно стоек в тропических условиях и не подвижен действию грибков (но и не подавляет их развитие).\r\nВлагопроницаемость при 20<sup>о</sup>С равна 3·10<sup>-9</sup> - 6·10<sup>-9</sup> г/(см·ч·мм рт. ст.); паропроницаемость при 20<sup>о</sup>С составляет 0,6·10<sup>-9</sup> - 1,2·10<sup>-9</sup> г/(см·ч·мм рт. ст.).\r\nДанные о газопроницаемости пленки из фтороплавта-4 (при отсутствии пор) толщиной 0,1 мм при 20<sup>о</sup>С [в см<sup>3</sup>/(см·с·мм рт. ст.)] приведены ниже:\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Воздух</td>\r\n<td>1,1*10<sup>-9</sup></td>\r\n</tr>\r\n<tr>\r\n<td>Азот</td>\r\n<td>0,7*10<sup>-9</sup></td>\r\n</tr>\r\n<tr>\r\n<td>Кислород</td>\r\n<td>2,3*10<sup>-9</sup></td>\r\n</tr>\r\n<tr>\r\n<td>Водород</td>\r\n<td>6,3*10<sup>-9</sup></td>\r\n</tr>\r\n<tr>\r\n<td>Двуокись углерода</td>\r\n<td>4,8*10<sup>-9</sup></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\nПри наличии пористости проницаемость может увеличиваться до 1000 раз.\r\nФторопласт-4 предназначен для видимого света только при малой толщине пленки:\r\n<table class="responsive-table" width="100%">\r\n<tbody>\r\n<tr>\r\n<td width="95%"></td>\r\n</tr>\r\n</tbody>\r\n<tbody>\r\n<tr>\r\n<td>Толщина пленки, мм</td>\r\n<td>0,05</td>\r\n<td>0,10</td>\r\n<td>0,15</td>\r\n<td>1,00</td>\r\n</tr>\r\n<tr>\r\n<td>Пропускание, %</td>\r\n<td>88</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<table class="responsive-table" border="0" width="100%" cellspacing="0" cellpadding="0">\r\n<tbody>\r\n<tr>\r\n<td align="center" valign="middle" bgcolor="#FFFBFF" width="50%"></td>\r\n</tr>\r\n</tbody>\r\n</table>', 'Фторопласт - описание свойств от показателей', '', 'inherit', 'closed', 'closed', '', '2893-revision-v1', '', '', '2018-05-07 19:31:56', '2018-05-07 19:31:56', '', 2893, '<p>Фторопласт -4 - кристаллический полимер, температурой плавления кристаллитов 327°С и температурой стеклования аморфных участков от -100 до -120°С. Даже при температуре выше температуры разложения (415°С) фторопласт-4 не переходит в вязкотекучее состоян', 0, 'revision', '', 0);
INSERT INTO `fttwp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(3183, 1, '2018-05-07 19:32:15', '2018-05-07 19:32:15', '<p>Фторопласт -4 - кристаллический полимер, температурой плавления кристаллитов 327°С и температурой стеклования аморфных участков от -100 до -120°С. Даже при температуре выше температуры разложения (415°С) фторопласт-4 не переходит в вязкотекучее состояние (при 370°С вязкость его расплава равна ≈10<sup>11</sup>П, т.е. в 1000000 раз больше вязкости, (необходимой для литья под давлением), поэтому переработка его возможна только методом спекания отпрессованных таблеток.\r\n</p><p>\r\nВ зависимости от скорости охлаждения (до температуры ниже 250°С) после спекания можно получить закаленные изделия со степенью кристалличности ≈50% и плотностью ≈2,15 г/см<sup>3</sup> или незакаленные со степенью кристалличности более 65% плотностью выше 2,20 г/см3.При температуре эксплуатации и от -269°С до +260°С степень кристалличности, достигнутая при данном режиме охлаждения, не меняется, при температуре выше 260°С степень кристалличности постепенно увеличивается, особенно быстро она вырастает при 310 - 315°С.</p>\r\n<div>\r\n\r\n\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td><strong>Степень кристалличности, %</strong></td>\r\n<td><strong>Плотность при\r\n23°С, г/см<sup>3</sup></strong></td>\r\n<td><strong>Степень кристалличности, %</strong></td>\r\n<td><strong>Плотность при\r\n23°С, г/см<sup>3</sup></strong></td>\r\n</tr>\r\n<tr>\r\n<td>40.0</td>\r\n<td>2.12</td>\r\n<td>69.4</td>\r\n<td>2.21</td>\r\n</tr>\r\n<tr>\r\n<td>43.2</td>\r\n<td>2.13</td>\r\n<td>72.8</td>\r\n<td>2.22</td>\r\n</tr>\r\n<tr>\r\n<td>46.5</td>\r\n<td>2.14</td>\r\n<td>75.2</td>\r\n<td>2.23</td>\r\n</tr>\r\n<tr>\r\n<td>49.7</td>\r\n<td>2.15</td>\r\n<td>78.0</td>\r\n<td>2.24</td>\r\n</tr>\r\n<tr>\r\n<td>53.0</td>\r\n<td>2.16</td>\r\n<td>80.7</td>\r\n<td>2.25</td>\r\n</tr>\r\n<tr>\r\n<td>56.3</td>\r\n<td>2.17</td>\r\n<td>82.6</td>\r\n<td>2.26</td>\r\n</tr>\r\n<tr>\r\n<td>59.7</td>\r\n<td>2.18</td>\r\n<td>85.2</td>\r\n<td>2.27</td>\r\n</tr>\r\n<tr>\r\n<td>63.1</td>\r\n<td>2.19</td>\r\n<td>89.0</td>\r\n<td>2.28</td>\r\n</tr>\r\n<tr>\r\n<td>66.5</td>\r\n<td>2.20</td>\r\n<td>-</td>\r\n<td>-</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\nОб отсутствии же пористости свидетельствует полная прозрачность образца во время спекания при 370-390°С. Даже незначительная пористость вызывает мутность образца. Пористость, равная примерно 0,1-0,2%, заметно влияет на точность определения плотности.\r\nДанные о зависимости удельного объема и плотности от температуры для образца со степенью кристалличности 68% (плотность медленно охлажденного изделия) приведены ниже:\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td><strong>Температура, °С</strong></td>\r\n<td><strong>Удельный объем, см<sup>3</sup>/г</strong></td>\r\n<td><strong>Плотность, г/см<sup>3</sup></strong></td>\r\n<td><strong>Температура, °С</strong></td>\r\n<td><strong>Удельный объем, cм<sup>3</sup>/г</strong></td>\r\n<td><strong>Плотность, г/см<sup>3</sup></strong></td>\r\n</tr>\r\n<tr>\r\n<td>-50</td>\r\n<td>0.440</td>\r\n<td>2.27</td>\r\n<td>175</td>\r\n<td>0.4769</td>\r\n<td>2.10</td>\r\n</tr>\r\n<tr>\r\n<td>-25</td>\r\n<td>0.443</td>\r\n<td>2.26</td>\r\n<td>200</td>\r\n<td>0.482</td>\r\n<td>2.08</td>\r\n</tr>\r\n<tr>\r\n<td>0</td>\r\n<td>0.447</td>\r\n<td>2.24</td>\r\n<td>225</td>\r\n<td>0.488</td>\r\n<td>2.05</td>\r\n</tr>\r\n<tr>\r\n<td>+25</td>\r\n<td>0.453*</td>\r\n<td>2.21</td>\r\n<td>250</td>\r\n<td>0.495</td>\r\n<td>2.02</td>\r\n</tr>\r\n<tr>\r\n<td>+50</td>\r\n<td>0.456</td>\r\n<td>2.19</td>\r\n<td>275</td>\r\n<td>0.503</td>\r\n<td>1.99</td>\r\n</tr>\r\n<tr>\r\n<td>+75</td>\r\n<td>0.459</td>\r\n<td>2.18</td>\r\n<td>300</td>\r\n<td>0.514</td>\r\n<td>1.95</td>\r\n</tr>\r\n<tr>\r\n<td>+100</td>\r\n<td>0.463</td>\r\n<td>2.16</td>\r\n<td>325</td>\r\n<td>0.534</td>\r\n<td>1.88</td>\r\n</tr>\r\n<tr>\r\n<td>+125</td>\r\n<td>0.467</td>\r\n<td>2.14</td>\r\n<td>327</td>\r\n<td>0.640**</td>\r\n<td>1.57</td>\r\n</tr>\r\n<tr>\r\n<td>+150</td>\r\n<td>0.471</td>\r\n<td>2.12</td>\r\n<td>350</td>\r\n<td>0.655</td>\r\n<td>1.53</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n* При нагревании от 19,6 до 22°C удлиненный объём увеличивается на 0,74%\r\n** При 327°С удлиненный объём увеличивается на 20%.\r\n\r\n<strong>                                ФИЗИКО-МЕХАНИЧЕСКИЕ СВОЙСТВА ФТОРОПЛАСТА-4\r\n</strong>\r\n<strong>Основные показатели физико-механических свойств фторопласта-4 приведены ниже:</strong>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td><strong>Разрушающее напряжение, кгс/см<sup>2</sup></strong></td>\r\n<td>Значения</td>\r\n</tr>\r\n<tr>\r\n<td>при растяжении:</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- незакаленный образец (кристалличность 05-08%)</td>\r\n<td>140-350*</td>\r\n</tr>\r\n<tr>\r\n<td>- закаленный образец (кристалличность 50%)</td>\r\n<td>160-315*</td>\r\n</tr>\r\n<tr>\r\n<td>при сжатии:</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- при 1%-ной деформации</td>\r\n<td>100</td>\r\n</tr>\r\n<tr>\r\n<td>- 10%-ной деформации</td>\r\n<td>185</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Сопротивлению изгибу (стрела прогиба 6 мм)</strong></td>\r\n<td>185</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Относительное удлинение при разрыт, %</strong></td>\r\n<td>250-500</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Остаточное удлинение, %</strong></td>\r\n<td>250-350</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Напряжение при 10%-ном удлинении, кгс/см<sup>2</sup></strong></td>\r\n<td>110-120</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Модуль упругости, кгс/см<sup>2</sup></strong></td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- при изгибе при 20°С</td>\r\n<td>4700-8500</td>\r\n</tr>\r\n<tr>\r\n<td>- сдвиге 2700</td>\r\n<td>2700</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Ударная вязкость, кгс·см/см<sup>2</sup></strong></td>\r\n<td>100 (не ломается)</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Ударное растяжение, кгс·см/см<sup>2</sup> (DIN 53448)</strong></td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- при 20°С</td>\r\n<td>650</td>\r\n</tr>\r\n<tr>\r\n<td>- 23°С</td>\r\n<td>680</td>\r\n</tr>\r\n<tr>\r\n<td>(удлинение при 20°С - 20%, при 23°С - 30%)</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Твердость:</strong></td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>по Бринеллю, кгс/мм<sup>2</sup></td>\r\n<td>3-4</td>\r\n</tr>\r\n<tr>\r\n<td>по Шору при 20°С</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- шкала С</td>\r\n<td>85-87</td>\r\n</tr>\r\n<tr>\r\n<td>- шкала D</td>\r\n<td>55-59</td>\r\n</tr>\r\n<tr>\r\n<td>Твердость по Роквеллу</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- шкала I</td>\r\n<td>80-95</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n· В зависимости от того, как вырезан образец: поперек направления прессования-высокие значения, вдоль направления прессования-малые.\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td><strong>Показатели</strong></td>\r\n<td colspan="10"><strong>Температура, °С</strong></td>\r\n</tr>\r\n<tr>\r\n<td>-</td>\r\n<td>-60</td>\r\n<td>-40</td>\r\n<td>-20</td>\r\n<td>0</td>\r\n<td>20</td>\r\n<td>40</td>\r\n<td>60</td>\r\n<td>80</td>\r\n<td>100</td>\r\n<td>120</td>\r\n</tr>\r\n<tr>\r\n<td>Разрушающее напряжение при растяжении, кгс/см<sup>2</sup></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>- незакаленный образец</td>\r\n<td>-</td>\r\n<td>350</td>\r\n<td>325</td>\r\n<td>300</td>\r\n<td>200</td>\r\n<td>180</td>\r\n<td>-</td>\r\n<td>135</td>\r\n<td>115</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- закаленный образец</td>\r\n<td>-</td>\r\n<td>500</td>\r\n<td>440</td>\r\n<td>330</td>\r\n<td>250</td>\r\n<td>240</td>\r\n<td>-</td>\r\n<td>200</td>\r\n<td>190</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>Относительное удлинение при разрыве, %</td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>- незакаленный образец</td>\r\n<td>-</td>\r\n<td>70</td>\r\n<td>100</td>\r\n<td>150</td>\r\n<td>470</td>\r\n<td>650</td>\r\n<td>-</td>\r\n<td>600</td>\r\n<td>540</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- закаленный образец</td>\r\n<td>-</td>\r\n<td>100</td>\r\n<td>160</td>\r\n<td>190</td>\r\n<td>400</td>\r\n<td>500</td>\r\n<td>-</td>\r\n<td>500</td>\r\n<td>480</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>Модуль упругости, кгс/см<sup>2</sup></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>при сжатии</td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>- незакаленный образец</td>\r\n<td>18000</td>\r\n<td>17000</td>\r\n<td>15000</td>\r\n<td>11000</td>\r\n<td>7000</td>\r\n<td>4500</td>\r\n<td>3300</td>\r\n<td>2400</td>\r\n<td>1700</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>при сжатии</td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>- незакаленный образец</td>\r\n<td>27800</td>\r\n<td>23900</td>\r\n<td>23300</td>\r\n<td>18100</td>\r\n<td>8500</td>\r\n<td>5100</td>\r\n<td>4800</td>\r\n<td>3800</td>\r\n<td>-</td>\r\n<td>2450</td>\r\n</tr>\r\n<tr>\r\n<td>- закаленный образец</td>\r\n<td>13200</td>\r\n<td>11300</td>\r\n<td>9800</td>\r\n<td>7400</td>\r\n<td>4700</td>\r\n<td>4000</td>\r\n<td>2900</td>\r\n<td>2180</td>\r\n<td>-</td>\r\n<td>1100</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\nДанные о зависимости физико-механических свойств фторопласта-4 от температуры приведены ниже.\r\n\r\n<strong>Физико-механические свойства фторопласта-4 при низких температурах\r\n</strong>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td><strong>Показатели</strong></td>\r\n<td colspan="6"><strong>Температура, °С</strong></td>\r\n</tr>\r\n<tr>\r\n<td></td>\r\n<td>-93</td>\r\n<td>-123</td>\r\n<td>-153</td>\r\n<td>-193</td>\r\n<td>-223</td>\r\n<td>-269</td>\r\n</tr>\r\n<tr>\r\n<td>Разрушающее напряжение при сжатии *, кгс/см<sup>2</sup></td>\r\n<td>350</td>\r\n<td>-</td>\r\n<td>980</td>\r\n<td>1260</td>\r\n<td>1554</td>\r\n<td>1750-1960</td>\r\n</tr>\r\n<tr>\r\n<td>Модуль упругости при сжатии, кгс/см<sup>2</sup></td>\r\n<td>-</td>\r\n<td>52500</td>\r\n<td>-</td>\r\n<td>-</td>\r\n<td>-</td>\r\n<td>70000</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n* Разрушающее напряжение при сжатии равно напряжению, при котором деформация составляет 0,2%.\r\n\r\n<strong>Зависимость деформации фторопласта-4 при сжатии от температуры:</strong>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td><strong>Деформация, %</strong></td>\r\n<td colspan="7"><strong>Нагрузка, вызывающая деформацию, кгс/см</strong><sup>2</sup></td>\r\n</tr>\r\n<tr>\r\n<td>-</td>\r\n<td>-50°С</td>\r\n<td> 0°С</td>\r\n<td> 25°С</td>\r\n<td>50°С</td>\r\n<td>100°С</td>\r\n<td>150°С</td>\r\n<td>200°С</td>\r\n</tr>\r\n<tr>\r\n<td>1</td>\r\n<td>203</td>\r\n<td>157</td>\r\n<td>62</td>\r\n<td>49</td>\r\n<td>31</td>\r\n<td>17,5</td>\r\n<td>11</td>\r\n</tr>\r\n<tr>\r\n<td>2</td>\r\n<td>304</td>\r\n<td>210</td>\r\n<td>92</td>\r\n<td>66</td>\r\n<td>39</td>\r\n<td>27</td>\r\n<td>20</td>\r\n</tr>\r\n<tr>\r\n<td>3</td>\r\n<td>350</td>\r\n<td>236</td>\r\n<td>105</td>\r\n<td>77</td>\r\n<td>48</td>\r\n<td>33</td>\r\n<td>27</td>\r\n</tr>\r\n<tr>\r\n<td>4</td>\r\n<td>374</td>\r\n<td>251</td>\r\n<td>120</td>\r\n<td>85</td>\r\n<td>59</td>\r\n<td>39</td>\r\n<td>31</td>\r\n</tr>\r\n<tr>\r\n<td>5</td>\r\n<td>390</td>\r\n<td>262</td>\r\n<td>127</td>\r\n<td>92</td>\r\n<td>62</td>\r\n<td>44</td>\r\n<td>35</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\nОдним из важнейших прочностных показателей является предел текучести при растяжении, т.е. то напряжение, при котором возникают остаточные деформации. Он зависит от степени кристалличности, скорости растяжения и температуры. При степени кристалличности 65% и скорости растяжения 100 мм/мин зависимость предела текучести от абсолютной температуры Т (в К) описывается эмпирической формулой (справедливой от 20 до 300°С):\r\nlgσT= 0,53166+483,64/Т\r\nНиже приведены значения пределов текучести для некоторых температур, рассчитанные по этой формуле:\r\nТемпература, °С ........................ 25.........50.........75......100.......150......200......250\r\nПредел текучести, кгс/см2 ....... 42,4.....106,9.....83,5.....67,2.....46,6.....35,5.....28,6\r\n\r\nПри длительном воздействии нагрузок остаточные деформации возникают при меньших напряжениях (40-50% от рассчитанных по формуле).\r\nПри конструировании изделий из фторопласта-4 следует учитывать ползучесть. Ползучесть (деформация при длительном действии нагрузки) рассчитывается по формуле:\r\nlgγt=lgγ1+a·lgt\r\nгде γt - деформация за t сут; γ1 - деформация за 1 сут; а - коэффициент, зависящий в основном от температуры и в меньшей степени от нагрузки, если она не превышает 40-50% предела текучести.\r\nЗначения коэффициента a и некоторые данные о ползучести для образцов со степенью кристалличности 50% приведены в таблице. Деформация за 1 сут (γ1) при других нагрузках и температурах определяется опытным путем. При степени кристалличности 65-68% ползучесть меньше.\r\n\r\n<strong>   Ползучесть фторопласта-4</strong>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td><strong>Температура, °С</strong></td>\r\n<td><strong>Нагрузка, кгс/см<sup>2</sup></strong></td>\r\n<td colspan="2"><strong>Деформация, %</strong></td>\r\n<td><strong>Коэффициент а\r\n</strong></td>\r\n</tr>\r\n<tr>\r\n<td colspan="2">Сжатие</td>\r\n<td>1 сут (γ1)</td>\r\n<td>4 сут (γ4)</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>20</td>\r\n<td>33</td>\r\n<td>6,00</td>\r\n<td>6,25</td>\r\n<td>0,030</td>\r\n</tr>\r\n<tr>\r\n<td>20</td>\r\n<td>21</td>\r\n<td>3,05</td>\r\n<td>3,19</td>\r\n<td>0,032</td>\r\n</tr>\r\n<tr>\r\n<td colspan="2">Растяжение</td>\r\n<td>1 сут (γ1)</td>\r\n<td>4 сут (γ4)</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>40</td>\r\n<td>28</td>\r\n<td>2,72</td>\r\n<td>2,87</td>\r\n<td>0,038</td>\r\n</tr>\r\n<tr>\r\n<td>100</td>\r\n<td>28</td>\r\n<td>5,58</td>\r\n<td>5,90</td>\r\n<td>0,040</td>\r\n</tr>\r\n<tr>\r\n<td>140</td>\r\n<td>21</td>\r\n<td>4,67</td>\r\n<td>4,94</td>\r\n<td>0,042</td>\r\n</tr>\r\n<tr>\r\n<td>200</td>\r\n<td>14</td>\r\n<td>4,08</td>\r\n<td>4,50</td>\r\n<td>0,048</td>\r\n</tr>\r\n<tr>\r\n<td>250</td>\r\n<td>14</td>\r\n<td>5,17</td>\r\n<td>5,58</td>\r\n<td>0,055</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<strong>                                           АНТИФРИКЦИОННЫЕ СВОЙСТВА ФТОРОПЛАСТА-4\r\n</strong>\r\nДанные о зависимости коэффициента трения от нагрузки [статической и динамической (при малых скоростях) коэффициенты трения фторопласта-4 по стали без смазки одинаковы] приведены ниже:\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Нагрузка, кгс/см2</td>\r\n<td>1</td>\r\n<td>3</td>\r\n<td>10</td>\r\n<td>20</td>\r\n</tr>\r\n<tr>\r\n<td>Коэффициент трения</td>\r\n<td>0,4</td>\r\n<td>0,1</td>\r\n<td>0,06</td>\r\n<td>0,05</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\nПри наличии смазки он примерно в 2 раза меньше.\r\nДинамический коэффициент трения фторопласта-4 по стали без смазки при нагрузке ~ 20 кгс/см2 зависит от скорости скольжения:\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Скорость скольжения, см/c</td>\r\n<td>4</td>\r\n<td>8</td>\r\n<td>20</td>\r\n<td>40</td>\r\n<td>80</td>\r\n<td>160</td>\r\n</tr>\r\n<tr>\r\n<td>Динамический коэффициент трения</td>\r\n<td>0,05</td>\r\n<td>0,1</td>\r\n<td>0,15</td>\r\n<td>0,23</td>\r\n<td>0,24</td>\r\n<td>0,27</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\nВ присутствии наполнителя при малых скоростях скольжения коэффициент трения несколько выше, а при больших скоростях - ниже, чем коэффициент трения чистого фторопласта-4 по стали.\r\nПри 327°С (на поверхности трения) коэффициент трения фторопласта-4 по стали резко возрастает (в несколько раз), что приводит к катастрофически быстрому износу и разрушению подшипника.\r\n\r\n<strong>                                  ТЕПЛОФИЗИЧЕСКИЕ СВОЙСТВА ФТОРОПЛАСТА-4\r\n</strong>\r\nНеспеченный фторопласт-4 (в виде порошка) имеет степень кристалличности 95 - 98%, после спекания - от 50% (закаленный) до 68 - 70% (незакаленный). Ниже 19,6°С элементарная ячейка кристалла фторопласта-4 состоит из 13 групп CF2, выше 19,6°С - из 15 групп CF2. При 19,6°С триклиническая упаковка переходит в менее упорядоченную, гексагональную, что сопровождается увеличение объема кристаллитов на 0,0058 см3/г (1,2 объемн. %), или увеличением объема образца при степени кристалличности 68% на 0,74%. При наличии внешнего давления точка перехода понижается на 0,013°С на каждую атмосферу. При 30°С имеет место второй переход кристаллической структуры, но изменение объема составляет едва 1/10 часть изменения объема при 19,6°С. Под высоким давлением (4500 кгс/см2 при 70°С) возникает третий переход.\r\nТемпература стеклования аморфных участков, определенная по температуре хрупкости, колеблется от -97 до -100°С, а по точке перегиба кривой зависимости модуля упругости составляет -120°С. Температура перехода аморфного твердого тела в переохлажденную жидкость равна 127°С.\r\nПри 327°С кристаллиты фторопласта-4 плавятся, и он становится полностью аморфным, совершенно прозрачным (при отсутствии пористости), высокоэластичным, но не течет (вязкость выше 1011 П). Объем возрастает на 20%.\r\n\r\nТочка плавления зависит от внешнего давления - на каждую атмосферу повышается на 0,154 °С. При остывании расплава ниже 327 °С образец мутнеет и становится непрозрачным - молочно-белым.   Скорость кристаллизации зависит от температуры (максимальная скорость при 310-315 °С), от продолжительности выдержки в расплавленном состоянии при 370-390 °С (чем больше время спекания, тем быстрее кристаллизуется образец) и от среднего молекулярного веса полимера (чем ниже молекулярный вес полимера, тем быстрее он кристаллизуется). На этом основан метод косвенной оценки молекулярного веса фторопласта-4: образец в виде диска толщиной 2 мм спекают при 370 °С в течение 13 ч и охлаждают от 370 до 250 °С в течение 5 ч. По плотности полученного образца при 23 °С можно оценить молекулярный вес: 2,16-2,19 г/см3-для высокомолекулярного полимера, 2,20-2,22 г/см3-для низкомолекулярного.\r\n\r\n<strong>Ниже приведены некоторые теплофизические свойства фторопласта-4:</strong>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Теплостойкость по Вика (при нагрузке 5 кгс), °С</td>\r\n<td>110</td>\r\n</tr>\r\n<tr>\r\n<td>Удельная теплоемкость, ккал/(кг·°С)</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>при 0°С</td>\r\n<td>0,23</td>\r\n</tr>\r\n<tr>\r\n<td>при 50°С</td>\r\n<td>0,25</td>\r\n</tr>\r\n<tr>\r\n<td>Коэффициент теплопроводности, ккал/(м·ч·°С)</td>\r\n<td>0,20</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\nТермический коэффициент линейного расширения зависит от температуры:\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Температура, °С</td>\r\n<td>от -60 до -10</td>\r\n<td>19,6</td>\r\n<td>30</td>\r\n<td>40</td>\r\n<td>200</td>\r\n<td>300</td>\r\n</tr>\r\n<tr>\r\n<td>Термический коэффициент линейного расширения α·105, 1/°С</td>\r\n<td>8</td>\r\n<td>54</td>\r\n<td>28</td>\r\n<td>11</td>\r\n<td>25</td>\r\n<td>64</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\nНа практике удобнее пользоваться средними значениями термического коэффициента линейного расширения для определенных интервалов температур. Следует также учитывать, что при нагревании изделий из фторопласта-4 в них часто возникают внутренние напряжения, вызывающие необратимое изменение размеров. Иногда вместо ожидаемого при нагревании удлинения образца он сокращается.\r\nДанные, приведенные ниже, относятся к образцам, в которых полностью отсутствуют внутренние напряжения:\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Температура, °C</td>\r\n<td>Термический коэффициент линейного расширения α·105, 1/°C</td>\r\n<td>Изменение размеров изделия*, %</td>\r\n<td>Температура, °C</td>\r\n<td>Термический коэффициент линейного расширения α·105, 1/°C</td>\r\n<td>Изменение размеров изделия*, %</td>\r\n</tr>\r\n<tr>\r\n<td>от -193 до +25</td>\r\n<td>8,6</td>\r\n<td>-1,85</td>\r\n<td>от +25 до +100</td>\r\n<td>12,4</td>\r\n<td>+0,93</td>\r\n</tr>\r\n<tr>\r\n<td>от -150 до +25</td>\r\n<td>9,6</td>\r\n<td>-1,68</td>\r\n<td>от +25 до +150</td>\r\n<td>13,5</td>\r\n<td>+1,59</td>\r\n</tr>\r\n<tr>\r\n<td>от -100 до +25</td>\r\n<td>11,2</td>\r\n<td>-1,40</td>\r\n<td>от +25 до +200</td>\r\n<td>15,1</td>\r\n<td>+2,64</td>\r\n</tr>\r\n<tr>\r\n<td>от -50 до +25</td>\r\n<td>13,5</td>\r\n<td>-1,01</td>\r\n<td>от +25 до +250</td>\r\n<td>17,4</td>\r\n<td>+3,92</td>\r\n</tr>\r\n<tr>\r\n<td> от 0 до +25</td>\r\n<td>20,0</td>\r\n<td>-0,50</td>\r\n<td>от +25 до +300</td>\r\n<td>21,8</td>\r\n<td>+5,99</td>\r\n</tr>\r\n<tr>\r\n<td>от +25 до +50</td>\r\n<td>12,4</td>\r\n<td>+0,31</td>\r\n<td>от +25 до +300</td>\r\n<td>21,8</td>\r\n<td>+5,99</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n* От размера при 25°С.\r\n\r\n<strong>ЭЛЕКТРИЧЕСКИЕ СВОЙТСВА ФТОРОПЛАСТА-4</strong>\r\n\r\nПоказатели электрических свойств фторопласта-4 приведены ниже:\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Удельное электрическое сопротивление:</td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>-поверхностное, Ом</td>\r\n<td>&gt;10<sup>17</sup></td>\r\n</tr>\r\n<tr>\r\n<td>-на воздухе со 100%-ной относительной влажностью</td>\r\n<td>&gt;10<sup>12</sup></td>\r\n</tr>\r\n<tr>\r\n<td>-объемное (до 150<sup>о</sup>С), Ом·см</td>\r\n<td>101<sup>7</sup> - 10<sup>20</sup></td>\r\n</tr>\r\n<tr>\r\n<td>-после длительного пребывания в воде не меняется</td>\r\n<td>1,9-2,2</td>\r\n</tr>\r\n<tr>\r\n<td>Диэлектрическая проницаемость (при 60 - 1010 Гц)</td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>Тангенс угла диэлектрических потерь (при 60 - 1010 Гц)</td>\r\n<td>&lt;1·10<sup>17</sup></td>\r\n</tr>\r\n<tr>\r\n<td>Электрическая прочность, кВ/мм:</td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>-при толщине образца 4 мм</td>\r\n<td>25-27</td>\r\n</tr>\r\n<tr>\r\n<td>-при толщине образца 0,1 - 0,3 мм</td>\r\n<td>40-80</td>\r\n</tr>\r\n<tr>\r\n<td>-при толщине образца 0,005 - 0,02 мм</td>\r\n<td>200-300</td>\r\n</tr>\r\n<tr>\r\n<td>Дугостойкость, с (сплошного токопроводящего слоя не образуется)</td>\r\n<td>250-700</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\nДанные о зависимости тангенса угла диэлектрических потерь от частоты приведены ниже:\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Частота, Гц</td>\r\n<td>60</td>\r\n<td>10<sup>3</sup></td>\r\n<td>10<sup>4</sup></td>\r\n<td>10<sup>5</sup></td>\r\n<td>10<sup>6</sup></td>\r\n<td>10<sup>7</sup></td>\r\n</tr>\r\n<tr>\r\n<td>tgδ·10<sup>4</sup></td>\r\n<td>0,5</td>\r\n<td>0,3</td>\r\n<td>0,4</td>\r\n<td>0,7</td>\r\n<td>0,7</td>\r\n<td>0,7</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\nДиэлектрическая проницаемость фторопласта-4 вплоть до 1010 Гц не зависит от частоты, а зависит от плотности: є= <u>1+0,238*d</u>\r\n2-0,119*d\r\nгде d - плотность при данной степени кристалличности и температуре.\r\nТангенс угла диэлектрических потерь остается постоянным при температуре от -60 до 250<sup>о</sup>С.\r\nПрогрев при 300<sup>о</sup>С в течение 6 месяцев не влияет на диэлектрические свойства фторопласта-4.\r\n\r\nХИМИЧЕСКИЕ И ДРУГИЕ СВОЙСТВА ФТОРОПЛАСТА-4\r\n\r\nФторопласт-4 является самым стойким из всех известных металлов - пластмасс, металлов, стекол, эмалей, сплавов и т.п. На него совершенно не действуют кислоты, окислители, щелочи, растворители. На фторопласт-4 действуют только расплавленные щелочные металлы и их комплексные соединения с аммиаком, нафталином, пиридином, а также трехфтористых хлор и элементный фтор при повышенных температурах. При температурах выше 327<sup>о</sup>С фторопласт набухает в жидких фторуглеродах, например в перфторкеросине. При 20<sup>о</sup>С фторопласт-4 слегка набухает (3 - 9%) в фторхлорсодержащих газах (фреонах).\r\nВыше 350<sup>о</sup>С фторопласт-4 реагирует с щелочеземельными металлами и их соединениями (окислами и карбонатами), а также с окислами некоторых других металлов (свинца, кадмия, меди).\r\nФторопласт-4 не смачивается водой при кратковременном погружении (угол смачивания 126<sup>о</sup>С), но смачивается при длительном пребывании в дистиллированной воде (15 - 20 суток). В соленой воде (например, морской) на поверхности фторопласта-4 через 15 - 20 суток отлагается пленка солей, смываемая дистиллированной водой.\r\nВодопоглощение за 24 часа (и более продолжительное время) - ниже ошибки взвешивания (0,00%).\r\nФторопласт-4 абсолютно стоек в тропических условиях и не подвижен действию грибков (но и не подавляет их развитие).\r\nВлагопроницаемость при 20<sup>о</sup>С равна 3·10<sup>-9</sup> - 6·10<sup>-9</sup> г/(см·ч·мм рт. ст.); паропроницаемость при 20<sup>о</sup>С составляет 0,6·10<sup>-9</sup> - 1,2·10<sup>-9</sup> г/(см·ч·мм рт. ст.).\r\nДанные о газопроницаемости пленки из фтороплавта-4 (при отсутствии пор) толщиной 0,1 мм при 20<sup>о</sup>С [в см<sup>3</sup>/(см·с·мм рт. ст.)] приведены ниже:\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Воздух</td>\r\n<td>1,1*10<sup>-9</sup></td>\r\n</tr>\r\n<tr>\r\n<td>Азот</td>\r\n<td>0,7*10<sup>-9</sup></td>\r\n</tr>\r\n<tr>\r\n<td>Кислород</td>\r\n<td>2,3*10<sup>-9</sup></td>\r\n</tr>\r\n<tr>\r\n<td>Водород</td>\r\n<td>6,3*10<sup>-9</sup></td>\r\n</tr>\r\n<tr>\r\n<td>Двуокись углерода</td>\r\n<td>4,8*10<sup>-9</sup></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\nПри наличии пористости проницаемость может увеличиваться до 1000 раз.\r\nФторопласт-4 предназначен для видимого света только при малой толщине пленки:\r\n<table class="responsive-table" width="100%">\r\n<tbody>\r\n<tr>\r\n<td width="95%"></td>\r\n</tr>\r\n</tbody>\r\n<tbody>\r\n<tr>\r\n<td>Толщина пленки, мм</td>\r\n<td>0,05</td>\r\n<td>0,10</td>\r\n<td>0,15</td>\r\n<td>1,00</td>\r\n</tr>\r\n<tr>\r\n<td>Пропускание, %</td>\r\n<td>88</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<table class="responsive-table" border="0" width="100%" cellspacing="0" cellpadding="0">\r\n<tbody>\r\n<tr>\r\n<td align="center" valign="middle" bgcolor="#FFFBFF" width="50%"></td>\r\n</tr>\r\n</tbody>\r\n</table>', 'Фторопласт - описание свойств от показателей', '', 'inherit', 'closed', 'closed', '', '2893-revision-v1', '', '', '2018-05-07 19:32:15', '2018-05-07 19:32:15', '', 2893, '<p>Фторопласт -4 - кристаллический полимер, температурой плавления кристаллитов 327°С и температурой стеклования аморфных участков от -100 до -120°С. Даже при температуре выше температуры разложения (415°С) фторопласт-4 не переходит в вязкотекучее состоян', 0, 'revision', '', 0);
INSERT INTO `fttwp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(3184, 1, '2018-05-07 19:34:51', '2018-05-07 19:34:51', '<p>Фторопласт -4 - кристаллический полимер, температурой плавления кристаллитов 327°С и температурой стеклования аморфных участков от -100 до -120°С. Даже при температуре выше температуры разложения (415°С) фторопласт-4 не переходит в вязкотекучее состояние (при 370°С вязкость его расплава равна ≈10<sup>11</sup>П, т.е. в 1000000 раз больше вязкости, (необходимой для литья под давлением), поэтому переработка его возможна только методом спекания отпрессованных таблеток.\r\n</p><p>\r\nВ зависимости от скорости охлаждения (до температуры ниже 250°С) после спекания можно получить закаленные изделия со степенью кристалличности ≈50% и плотностью ≈2,15 г/см<sup>3</sup> или незакаленные со степенью кристалличности более 65% плотностью выше 2,20 г/см3.При температуре эксплуатации и от -269°С до +260°С степень кристалличности, достигнутая при данном режиме охлаждения, не меняется, при температуре выше 260°С степень кристалличности постепенно увеличивается, особенно быстро она вырастает при 310 - 315°С.</p>\r\n<div>\r\n\r\n\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td><strong>Степень кристалличности, %</strong></td>\r\n<td><strong>Плотность при\r\n23°С, г/см<sup>3</sup></strong></td>\r\n<td><strong>Степень кристалличности, %</strong></td>\r\n<td><strong>Плотность при\r\n23°С, г/см<sup>3</sup></strong></td>\r\n</tr>\r\n<tr>\r\n<td>40.0</td>\r\n<td>2.12</td>\r\n<td>69.4</td>\r\n<td>2.21</td>\r\n</tr>\r\n<tr>\r\n<td>43.2</td>\r\n<td>2.13</td>\r\n<td>72.8</td>\r\n<td>2.22</td>\r\n</tr>\r\n<tr>\r\n<td>46.5</td>\r\n<td>2.14</td>\r\n<td>75.2</td>\r\n<td>2.23</td>\r\n</tr>\r\n<tr>\r\n<td>49.7</td>\r\n<td>2.15</td>\r\n<td>78.0</td>\r\n<td>2.24</td>\r\n</tr>\r\n<tr>\r\n<td>53.0</td>\r\n<td>2.16</td>\r\n<td>80.7</td>\r\n<td>2.25</td>\r\n</tr>\r\n<tr>\r\n<td>56.3</td>\r\n<td>2.17</td>\r\n<td>82.6</td>\r\n<td>2.26</td>\r\n</tr>\r\n<tr>\r\n<td>59.7</td>\r\n<td>2.18</td>\r\n<td>85.2</td>\r\n<td>2.27</td>\r\n</tr>\r\n<tr>\r\n<td>63.1</td>\r\n<td>2.19</td>\r\n<td>89.0</td>\r\n<td>2.28</td>\r\n</tr>\r\n<tr>\r\n<td>66.5</td>\r\n<td>2.20</td>\r\n<td>-</td>\r\n<td>-</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>Об отсутствии же пористости свидетельствует полная прозрачность образца во время спекания при 370-390°С. Даже незначительная пористость вызывает мутность образца. Пористость, равная примерно 0,1-0,2%, заметно влияет на точность определения плотности.\r\n</p><p>Данные о зависимости удельного объема и плотности от температуры для образца со степенью кристалличности 68% (плотность медленно охлажденного изделия) приведены ниже:</p>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td><strong>Температура, °С</strong></td>\r\n<td><strong>Удельный объем, см<sup>3</sup>/г</strong></td>\r\n<td><strong>Плотность, г/см<sup>3</sup></strong></td>\r\n<td><strong>Температура, °С</strong></td>\r\n<td><strong>Удельный объем, cм<sup>3</sup>/г</strong></td>\r\n<td><strong>Плотность, г/см<sup>3</sup></strong></td>\r\n</tr>\r\n<tr>\r\n<td>-50</td>\r\n<td>0.440</td>\r\n<td>2.27</td>\r\n<td>175</td>\r\n<td>0.4769</td>\r\n<td>2.10</td>\r\n</tr>\r\n<tr>\r\n<td>-25</td>\r\n<td>0.443</td>\r\n<td>2.26</td>\r\n<td>200</td>\r\n<td>0.482</td>\r\n<td>2.08</td>\r\n</tr>\r\n<tr>\r\n<td>0</td>\r\n<td>0.447</td>\r\n<td>2.24</td>\r\n<td>225</td>\r\n<td>0.488</td>\r\n<td>2.05</td>\r\n</tr>\r\n<tr>\r\n<td>+25</td>\r\n<td>0.453*</td>\r\n<td>2.21</td>\r\n<td>250</td>\r\n<td>0.495</td>\r\n<td>2.02</td>\r\n</tr>\r\n<tr>\r\n<td>+50</td>\r\n<td>0.456</td>\r\n<td>2.19</td>\r\n<td>275</td>\r\n<td>0.503</td>\r\n<td>1.99</td>\r\n</tr>\r\n<tr>\r\n<td>+75</td>\r\n<td>0.459</td>\r\n<td>2.18</td>\r\n<td>300</td>\r\n<td>0.514</td>\r\n<td>1.95</td>\r\n</tr>\r\n<tr>\r\n<td>+100</td>\r\n<td>0.463</td>\r\n<td>2.16</td>\r\n<td>325</td>\r\n<td>0.534</td>\r\n<td>1.88</td>\r\n</tr>\r\n<tr>\r\n<td>+125</td>\r\n<td>0.467</td>\r\n<td>2.14</td>\r\n<td>327</td>\r\n<td>0.640**</td>\r\n<td>1.57</td>\r\n</tr>\r\n<tr>\r\n<td>+150</td>\r\n<td>0.471</td>\r\n<td>2.12</td>\r\n<td>350</td>\r\n<td>0.655</td>\r\n<td>1.53</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n* При нагревании от 19,6 до 22°C удлиненный объём увеличивается на 0,74%\r\n** При 327°С удлиненный объём увеличивается на 20%.\r\n\r\n<h2>ФИЗИКО-МЕХАНИЧЕСКИЕ СВОЙСТВА ФТОРОПЛАСТА-4</h2>\r\n<p>Основные показатели физико-механических свойств фторопласта-4 приведены ниже:</p>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td><strong>Разрушающее напряжение, кгс/см<sup>2</sup></strong></td>\r\n<td>Значения</td>\r\n</tr>\r\n<tr>\r\n<td>при растяжении:</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- незакаленный образец (кристалличность 05-08%)</td>\r\n<td>140-350*</td>\r\n</tr>\r\n<tr>\r\n<td>- закаленный образец (кристалличность 50%)</td>\r\n<td>160-315*</td>\r\n</tr>\r\n<tr>\r\n<td>при сжатии:</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- при 1%-ной деформации</td>\r\n<td>100</td>\r\n</tr>\r\n<tr>\r\n<td>- 10%-ной деформации</td>\r\n<td>185</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Сопротивлению изгибу (стрела прогиба 6 мм)</strong></td>\r\n<td>185</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Относительное удлинение при разрыт, %</strong></td>\r\n<td>250-500</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Остаточное удлинение, %</strong></td>\r\n<td>250-350</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Напряжение при 10%-ном удлинении, кгс/см<sup>2</sup></strong></td>\r\n<td>110-120</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Модуль упругости, кгс/см<sup>2</sup></strong></td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- при изгибе при 20°С</td>\r\n<td>4700-8500</td>\r\n</tr>\r\n<tr>\r\n<td>- сдвиге 2700</td>\r\n<td>2700</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Ударная вязкость, кгс·см/см<sup>2</sup></strong></td>\r\n<td>100 (не ломается)</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Ударное растяжение, кгс·см/см<sup>2</sup> (DIN 53448)</strong></td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- при 20°С</td>\r\n<td>650</td>\r\n</tr>\r\n<tr>\r\n<td>- 23°С</td>\r\n<td>680</td>\r\n</tr>\r\n<tr>\r\n<td>(удлинение при 20°С - 20%, при 23°С - 30%)</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Твердость:</strong></td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>по Бринеллю, кгс/мм<sup>2</sup></td>\r\n<td>3-4</td>\r\n</tr>\r\n<tr>\r\n<td>по Шору при 20°С</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- шкала С</td>\r\n<td>85-87</td>\r\n</tr>\r\n<tr>\r\n<td>- шкала D</td>\r\n<td>55-59</td>\r\n</tr>\r\n<tr>\r\n<td>Твердость по Роквеллу</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- шкала I</td>\r\n<td>80-95</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>В зависимости от того, как вырезан образец: поперек направления прессования-высокие значения, вдоль направления прессования-малые.</p>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td><strong>Показатели</strong></td>\r\n<td colspan="10"><strong>Температура, °С</strong></td>\r\n</tr>\r\n<tr>\r\n<td>-</td>\r\n<td>-60</td>\r\n<td>-40</td>\r\n<td>-20</td>\r\n<td>0</td>\r\n<td>20</td>\r\n<td>40</td>\r\n<td>60</td>\r\n<td>80</td>\r\n<td>100</td>\r\n<td>120</td>\r\n</tr>\r\n<tr>\r\n<td>Разрушающее напряжение при растяжении, кгс/см<sup>2</sup></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>- незакаленный образец</td>\r\n<td>-</td>\r\n<td>350</td>\r\n<td>325</td>\r\n<td>300</td>\r\n<td>200</td>\r\n<td>180</td>\r\n<td>-</td>\r\n<td>135</td>\r\n<td>115</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- закаленный образец</td>\r\n<td>-</td>\r\n<td>500</td>\r\n<td>440</td>\r\n<td>330</td>\r\n<td>250</td>\r\n<td>240</td>\r\n<td>-</td>\r\n<td>200</td>\r\n<td>190</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>Относительное удлинение при разрыве, %</td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>- незакаленный образец</td>\r\n<td>-</td>\r\n<td>70</td>\r\n<td>100</td>\r\n<td>150</td>\r\n<td>470</td>\r\n<td>650</td>\r\n<td>-</td>\r\n<td>600</td>\r\n<td>540</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- закаленный образец</td>\r\n<td>-</td>\r\n<td>100</td>\r\n<td>160</td>\r\n<td>190</td>\r\n<td>400</td>\r\n<td>500</td>\r\n<td>-</td>\r\n<td>500</td>\r\n<td>480</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>Модуль упругости, кгс/см<sup>2</sup></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>при сжатии</td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>- незакаленный образец</td>\r\n<td>18000</td>\r\n<td>17000</td>\r\n<td>15000</td>\r\n<td>11000</td>\r\n<td>7000</td>\r\n<td>4500</td>\r\n<td>3300</td>\r\n<td>2400</td>\r\n<td>1700</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>при сжатии</td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>- незакаленный образец</td>\r\n<td>27800</td>\r\n<td>23900</td>\r\n<td>23300</td>\r\n<td>18100</td>\r\n<td>8500</td>\r\n<td>5100</td>\r\n<td>4800</td>\r\n<td>3800</td>\r\n<td>-</td>\r\n<td>2450</td>\r\n</tr>\r\n<tr>\r\n<td>- закаленный образец</td>\r\n<td>13200</td>\r\n<td>11300</td>\r\n<td>9800</td>\r\n<td>7400</td>\r\n<td>4700</td>\r\n<td>4000</td>\r\n<td>2900</td>\r\n<td>2180</td>\r\n<td>-</td>\r\n<td>1100</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>Данные о зависимости физико-механических свойств фторопласта-4 от температуры приведены ниже.</p>\r\n\r\n<h2>Физико-механические свойства фторопласта-4 при низких температурах\r\n</h2>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td><strong>Показатели</strong></td>\r\n<td colspan="6"><strong>Температура, °С</strong></td>\r\n</tr>\r\n<tr>\r\n<td></td>\r\n<td>-93</td>\r\n<td>-123</td>\r\n<td>-153</td>\r\n<td>-193</td>\r\n<td>-223</td>\r\n<td>-269</td>\r\n</tr>\r\n<tr>\r\n<td>Разрушающее напряжение при сжатии *, кгс/см<sup>2</sup></td>\r\n<td>350</td>\r\n<td>-</td>\r\n<td>980</td>\r\n<td>1260</td>\r\n<td>1554</td>\r\n<td>1750-1960</td>\r\n</tr>\r\n<tr>\r\n<td>Модуль упругости при сжатии, кгс/см<sup>2</sup></td>\r\n<td>-</td>\r\n<td>52500</td>\r\n<td>-</td>\r\n<td>-</td>\r\n<td>-</td>\r\n<td>70000</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>* Разрушающее напряжение при сжатии равно напряжению, при котором деформация составляет 0,2%.</p>\r\n\r\n<h2>Зависимость деформации фторопласта-4 при сжатии от температуры:</h2>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td><strong>Деформация, %</strong></td>\r\n<td colspan="7"><strong>Нагрузка, вызывающая деформацию, кгс/см</strong><sup>2</sup></td>\r\n</tr>\r\n<tr>\r\n<td>-</td>\r\n<td>-50°С</td>\r\n<td> 0°С</td>\r\n<td> 25°С</td>\r\n<td>50°С</td>\r\n<td>100°С</td>\r\n<td>150°С</td>\r\n<td>200°С</td>\r\n</tr>\r\n<tr>\r\n<td>1</td>\r\n<td>203</td>\r\n<td>157</td>\r\n<td>62</td>\r\n<td>49</td>\r\n<td>31</td>\r\n<td>17,5</td>\r\n<td>11</td>\r\n</tr>\r\n<tr>\r\n<td>2</td>\r\n<td>304</td>\r\n<td>210</td>\r\n<td>92</td>\r\n<td>66</td>\r\n<td>39</td>\r\n<td>27</td>\r\n<td>20</td>\r\n</tr>\r\n<tr>\r\n<td>3</td>\r\n<td>350</td>\r\n<td>236</td>\r\n<td>105</td>\r\n<td>77</td>\r\n<td>48</td>\r\n<td>33</td>\r\n<td>27</td>\r\n</tr>\r\n<tr>\r\n<td>4</td>\r\n<td>374</td>\r\n<td>251</td>\r\n<td>120</td>\r\n<td>85</td>\r\n<td>59</td>\r\n<td>39</td>\r\n<td>31</td>\r\n</tr>\r\n<tr>\r\n<td>5</td>\r\n<td>390</td>\r\n<td>262</td>\r\n<td>127</td>\r\n<td>92</td>\r\n<td>62</td>\r\n<td>44</td>\r\n<td>35</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\nОдним из важнейших прочностных показателей является предел текучести при растяжении, т.е. то напряжение, при котором возникают остаточные деформации. Он зависит от степени кристалличности, скорости растяжения и температуры. При степени кристалличности 65% и скорости растяжения 100 мм/мин зависимость предела текучести от абсолютной температуры Т (в К) описывается эмпирической формулой (справедливой от 20 до 300°С):\r\nlgσT= 0,53166+483,64/Т\r\nНиже приведены значения пределов текучести для некоторых температур, рассчитанные по этой формуле:\r\nТемпература, °С ........................ 25.........50.........75......100.......150......200......250\r\nПредел текучести, кгс/см2 ....... 42,4.....106,9.....83,5.....67,2.....46,6.....35,5.....28,6\r\n\r\nПри длительном воздействии нагрузок остаточные деформации возникают при меньших напряжениях (40-50% от рассчитанных по формуле).\r\nПри конструировании изделий из фторопласта-4 следует учитывать ползучесть. Ползучесть (деформация при длительном действии нагрузки) рассчитывается по формуле:\r\nlgγt=lgγ1+a·lgt\r\nгде γt - деформация за t сут; γ1 - деформация за 1 сут; а - коэффициент, зависящий в основном от температуры и в меньшей степени от нагрузки, если она не превышает 40-50% предела текучести.\r\nЗначения коэффициента a и некоторые данные о ползучести для образцов со степенью кристалличности 50% приведены в таблице. Деформация за 1 сут (γ1) при других нагрузках и температурах определяется опытным путем. При степени кристалличности 65-68% ползучесть меньше.\r\n\r\n<strong>   Ползучесть фторопласта-4</strong>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td><strong>Температура, °С</strong></td>\r\n<td><strong>Нагрузка, кгс/см<sup>2</sup></strong></td>\r\n<td colspan="2"><strong>Деформация, %</strong></td>\r\n<td><strong>Коэффициент а\r\n</strong></td>\r\n</tr>\r\n<tr>\r\n<td colspan="2">Сжатие</td>\r\n<td>1 сут (γ1)</td>\r\n<td>4 сут (γ4)</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>20</td>\r\n<td>33</td>\r\n<td>6,00</td>\r\n<td>6,25</td>\r\n<td>0,030</td>\r\n</tr>\r\n<tr>\r\n<td>20</td>\r\n<td>21</td>\r\n<td>3,05</td>\r\n<td>3,19</td>\r\n<td>0,032</td>\r\n</tr>\r\n<tr>\r\n<td colspan="2">Растяжение</td>\r\n<td>1 сут (γ1)</td>\r\n<td>4 сут (γ4)</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>40</td>\r\n<td>28</td>\r\n<td>2,72</td>\r\n<td>2,87</td>\r\n<td>0,038</td>\r\n</tr>\r\n<tr>\r\n<td>100</td>\r\n<td>28</td>\r\n<td>5,58</td>\r\n<td>5,90</td>\r\n<td>0,040</td>\r\n</tr>\r\n<tr>\r\n<td>140</td>\r\n<td>21</td>\r\n<td>4,67</td>\r\n<td>4,94</td>\r\n<td>0,042</td>\r\n</tr>\r\n<tr>\r\n<td>200</td>\r\n<td>14</td>\r\n<td>4,08</td>\r\n<td>4,50</td>\r\n<td>0,048</td>\r\n</tr>\r\n<tr>\r\n<td>250</td>\r\n<td>14</td>\r\n<td>5,17</td>\r\n<td>5,58</td>\r\n<td>0,055</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<strong>                                           АНТИФРИКЦИОННЫЕ СВОЙСТВА ФТОРОПЛАСТА-4\r\n</strong>\r\nДанные о зависимости коэффициента трения от нагрузки [статической и динамической (при малых скоростях) коэффициенты трения фторопласта-4 по стали без смазки одинаковы] приведены ниже:\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Нагрузка, кгс/см2</td>\r\n<td>1</td>\r\n<td>3</td>\r\n<td>10</td>\r\n<td>20</td>\r\n</tr>\r\n<tr>\r\n<td>Коэффициент трения</td>\r\n<td>0,4</td>\r\n<td>0,1</td>\r\n<td>0,06</td>\r\n<td>0,05</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\nПри наличии смазки он примерно в 2 раза меньше.\r\nДинамический коэффициент трения фторопласта-4 по стали без смазки при нагрузке ~ 20 кгс/см2 зависит от скорости скольжения:\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Скорость скольжения, см/c</td>\r\n<td>4</td>\r\n<td>8</td>\r\n<td>20</td>\r\n<td>40</td>\r\n<td>80</td>\r\n<td>160</td>\r\n</tr>\r\n<tr>\r\n<td>Динамический коэффициент трения</td>\r\n<td>0,05</td>\r\n<td>0,1</td>\r\n<td>0,15</td>\r\n<td>0,23</td>\r\n<td>0,24</td>\r\n<td>0,27</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\nВ присутствии наполнителя при малых скоростях скольжения коэффициент трения несколько выше, а при больших скоростях - ниже, чем коэффициент трения чистого фторопласта-4 по стали.\r\nПри 327°С (на поверхности трения) коэффициент трения фторопласта-4 по стали резко возрастает (в несколько раз), что приводит к катастрофически быстрому износу и разрушению подшипника.\r\n\r\n<strong>                                  ТЕПЛОФИЗИЧЕСКИЕ СВОЙСТВА ФТОРОПЛАСТА-4\r\n</strong>\r\nНеспеченный фторопласт-4 (в виде порошка) имеет степень кристалличности 95 - 98%, после спекания - от 50% (закаленный) до 68 - 70% (незакаленный). Ниже 19,6°С элементарная ячейка кристалла фторопласта-4 состоит из 13 групп CF2, выше 19,6°С - из 15 групп CF2. При 19,6°С триклиническая упаковка переходит в менее упорядоченную, гексагональную, что сопровождается увеличение объема кристаллитов на 0,0058 см3/г (1,2 объемн. %), или увеличением объема образца при степени кристалличности 68% на 0,74%. При наличии внешнего давления точка перехода понижается на 0,013°С на каждую атмосферу. При 30°С имеет место второй переход кристаллической структуры, но изменение объема составляет едва 1/10 часть изменения объема при 19,6°С. Под высоким давлением (4500 кгс/см2 при 70°С) возникает третий переход.\r\nТемпература стеклования аморфных участков, определенная по температуре хрупкости, колеблется от -97 до -100°С, а по точке перегиба кривой зависимости модуля упругости составляет -120°С. Температура перехода аморфного твердого тела в переохлажденную жидкость равна 127°С.\r\nПри 327°С кристаллиты фторопласта-4 плавятся, и он становится полностью аморфным, совершенно прозрачным (при отсутствии пористости), высокоэластичным, но не течет (вязкость выше 1011 П). Объем возрастает на 20%.\r\n\r\nТочка плавления зависит от внешнего давления - на каждую атмосферу повышается на 0,154 °С. При остывании расплава ниже 327 °С образец мутнеет и становится непрозрачным - молочно-белым.   Скорость кристаллизации зависит от температуры (максимальная скорость при 310-315 °С), от продолжительности выдержки в расплавленном состоянии при 370-390 °С (чем больше время спекания, тем быстрее кристаллизуется образец) и от среднего молекулярного веса полимера (чем ниже молекулярный вес полимера, тем быстрее он кристаллизуется). На этом основан метод косвенной оценки молекулярного веса фторопласта-4: образец в виде диска толщиной 2 мм спекают при 370 °С в течение 13 ч и охлаждают от 370 до 250 °С в течение 5 ч. По плотности полученного образца при 23 °С можно оценить молекулярный вес: 2,16-2,19 г/см3-для высокомолекулярного полимера, 2,20-2,22 г/см3-для низкомолекулярного.\r\n\r\n<strong>Ниже приведены некоторые теплофизические свойства фторопласта-4:</strong>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Теплостойкость по Вика (при нагрузке 5 кгс), °С</td>\r\n<td>110</td>\r\n</tr>\r\n<tr>\r\n<td>Удельная теплоемкость, ккал/(кг·°С)</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>при 0°С</td>\r\n<td>0,23</td>\r\n</tr>\r\n<tr>\r\n<td>при 50°С</td>\r\n<td>0,25</td>\r\n</tr>\r\n<tr>\r\n<td>Коэффициент теплопроводности, ккал/(м·ч·°С)</td>\r\n<td>0,20</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\nТермический коэффициент линейного расширения зависит от температуры:\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Температура, °С</td>\r\n<td>от -60 до -10</td>\r\n<td>19,6</td>\r\n<td>30</td>\r\n<td>40</td>\r\n<td>200</td>\r\n<td>300</td>\r\n</tr>\r\n<tr>\r\n<td>Термический коэффициент линейного расширения α·105, 1/°С</td>\r\n<td>8</td>\r\n<td>54</td>\r\n<td>28</td>\r\n<td>11</td>\r\n<td>25</td>\r\n<td>64</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\nНа практике удобнее пользоваться средними значениями термического коэффициента линейного расширения для определенных интервалов температур. Следует также учитывать, что при нагревании изделий из фторопласта-4 в них часто возникают внутренние напряжения, вызывающие необратимое изменение размеров. Иногда вместо ожидаемого при нагревании удлинения образца он сокращается.\r\nДанные, приведенные ниже, относятся к образцам, в которых полностью отсутствуют внутренние напряжения:\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Температура, °C</td>\r\n<td>Термический коэффициент линейного расширения α·105, 1/°C</td>\r\n<td>Изменение размеров изделия*, %</td>\r\n<td>Температура, °C</td>\r\n<td>Термический коэффициент линейного расширения α·105, 1/°C</td>\r\n<td>Изменение размеров изделия*, %</td>\r\n</tr>\r\n<tr>\r\n<td>от -193 до +25</td>\r\n<td>8,6</td>\r\n<td>-1,85</td>\r\n<td>от +25 до +100</td>\r\n<td>12,4</td>\r\n<td>+0,93</td>\r\n</tr>\r\n<tr>\r\n<td>от -150 до +25</td>\r\n<td>9,6</td>\r\n<td>-1,68</td>\r\n<td>от +25 до +150</td>\r\n<td>13,5</td>\r\n<td>+1,59</td>\r\n</tr>\r\n<tr>\r\n<td>от -100 до +25</td>\r\n<td>11,2</td>\r\n<td>-1,40</td>\r\n<td>от +25 до +200</td>\r\n<td>15,1</td>\r\n<td>+2,64</td>\r\n</tr>\r\n<tr>\r\n<td>от -50 до +25</td>\r\n<td>13,5</td>\r\n<td>-1,01</td>\r\n<td>от +25 до +250</td>\r\n<td>17,4</td>\r\n<td>+3,92</td>\r\n</tr>\r\n<tr>\r\n<td> от 0 до +25</td>\r\n<td>20,0</td>\r\n<td>-0,50</td>\r\n<td>от +25 до +300</td>\r\n<td>21,8</td>\r\n<td>+5,99</td>\r\n</tr>\r\n<tr>\r\n<td>от +25 до +50</td>\r\n<td>12,4</td>\r\n<td>+0,31</td>\r\n<td>от +25 до +300</td>\r\n<td>21,8</td>\r\n<td>+5,99</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n* От размера при 25°С.\r\n\r\n<strong>ЭЛЕКТРИЧЕСКИЕ СВОЙТСВА ФТОРОПЛАСТА-4</strong>\r\n\r\nПоказатели электрических свойств фторопласта-4 приведены ниже:\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Удельное электрическое сопротивление:</td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>-поверхностное, Ом</td>\r\n<td>&gt;10<sup>17</sup></td>\r\n</tr>\r\n<tr>\r\n<td>-на воздухе со 100%-ной относительной влажностью</td>\r\n<td>&gt;10<sup>12</sup></td>\r\n</tr>\r\n<tr>\r\n<td>-объемное (до 150<sup>о</sup>С), Ом·см</td>\r\n<td>101<sup>7</sup> - 10<sup>20</sup></td>\r\n</tr>\r\n<tr>\r\n<td>-после длительного пребывания в воде не меняется</td>\r\n<td>1,9-2,2</td>\r\n</tr>\r\n<tr>\r\n<td>Диэлектрическая проницаемость (при 60 - 1010 Гц)</td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>Тангенс угла диэлектрических потерь (при 60 - 1010 Гц)</td>\r\n<td>&lt;1·10<sup>17</sup></td>\r\n</tr>\r\n<tr>\r\n<td>Электрическая прочность, кВ/мм:</td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>-при толщине образца 4 мм</td>\r\n<td>25-27</td>\r\n</tr>\r\n<tr>\r\n<td>-при толщине образца 0,1 - 0,3 мм</td>\r\n<td>40-80</td>\r\n</tr>\r\n<tr>\r\n<td>-при толщине образца 0,005 - 0,02 мм</td>\r\n<td>200-300</td>\r\n</tr>\r\n<tr>\r\n<td>Дугостойкость, с (сплошного токопроводящего слоя не образуется)</td>\r\n<td>250-700</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\nДанные о зависимости тангенса угла диэлектрических потерь от частоты приведены ниже:\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Частота, Гц</td>\r\n<td>60</td>\r\n<td>10<sup>3</sup></td>\r\n<td>10<sup>4</sup></td>\r\n<td>10<sup>5</sup></td>\r\n<td>10<sup>6</sup></td>\r\n<td>10<sup>7</sup></td>\r\n</tr>\r\n<tr>\r\n<td>tgδ·10<sup>4</sup></td>\r\n<td>0,5</td>\r\n<td>0,3</td>\r\n<td>0,4</td>\r\n<td>0,7</td>\r\n<td>0,7</td>\r\n<td>0,7</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\nДиэлектрическая проницаемость фторопласта-4 вплоть до 1010 Гц не зависит от частоты, а зависит от плотности: є= <u>1+0,238*d</u>\r\n2-0,119*d\r\nгде d - плотность при данной степени кристалличности и температуре.\r\nТангенс угла диэлектрических потерь остается постоянным при температуре от -60 до 250<sup>о</sup>С.\r\nПрогрев при 300<sup>о</sup>С в течение 6 месяцев не влияет на диэлектрические свойства фторопласта-4.\r\n\r\nХИМИЧЕСКИЕ И ДРУГИЕ СВОЙСТВА ФТОРОПЛАСТА-4\r\n\r\nФторопласт-4 является самым стойким из всех известных металлов - пластмасс, металлов, стекол, эмалей, сплавов и т.п. На него совершенно не действуют кислоты, окислители, щелочи, растворители. На фторопласт-4 действуют только расплавленные щелочные металлы и их комплексные соединения с аммиаком, нафталином, пиридином, а также трехфтористых хлор и элементный фтор при повышенных температурах. При температурах выше 327<sup>о</sup>С фторопласт набухает в жидких фторуглеродах, например в перфторкеросине. При 20<sup>о</sup>С фторопласт-4 слегка набухает (3 - 9%) в фторхлорсодержащих газах (фреонах).\r\nВыше 350<sup>о</sup>С фторопласт-4 реагирует с щелочеземельными металлами и их соединениями (окислами и карбонатами), а также с окислами некоторых других металлов (свинца, кадмия, меди).\r\nФторопласт-4 не смачивается водой при кратковременном погружении (угол смачивания 126<sup>о</sup>С), но смачивается при длительном пребывании в дистиллированной воде (15 - 20 суток). В соленой воде (например, морской) на поверхности фторопласта-4 через 15 - 20 суток отлагается пленка солей, смываемая дистиллированной водой.\r\nВодопоглощение за 24 часа (и более продолжительное время) - ниже ошибки взвешивания (0,00%).\r\nФторопласт-4 абсолютно стоек в тропических условиях и не подвижен действию грибков (но и не подавляет их развитие).\r\nВлагопроницаемость при 20<sup>о</sup>С равна 3·10<sup>-9</sup> - 6·10<sup>-9</sup> г/(см·ч·мм рт. ст.); паропроницаемость при 20<sup>о</sup>С составляет 0,6·10<sup>-9</sup> - 1,2·10<sup>-9</sup> г/(см·ч·мм рт. ст.).\r\nДанные о газопроницаемости пленки из фтороплавта-4 (при отсутствии пор) толщиной 0,1 мм при 20<sup>о</sup>С [в см<sup>3</sup>/(см·с·мм рт. ст.)] приведены ниже:\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Воздух</td>\r\n<td>1,1*10<sup>-9</sup></td>\r\n</tr>\r\n<tr>\r\n<td>Азот</td>\r\n<td>0,7*10<sup>-9</sup></td>\r\n</tr>\r\n<tr>\r\n<td>Кислород</td>\r\n<td>2,3*10<sup>-9</sup></td>\r\n</tr>\r\n<tr>\r\n<td>Водород</td>\r\n<td>6,3*10<sup>-9</sup></td>\r\n</tr>\r\n<tr>\r\n<td>Двуокись углерода</td>\r\n<td>4,8*10<sup>-9</sup></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\nПри наличии пористости проницаемость может увеличиваться до 1000 раз.\r\nФторопласт-4 предназначен для видимого света только при малой толщине пленки:\r\n<table class="responsive-table" width="100%">\r\n<tbody>\r\n<tr>\r\n<td width="95%"></td>\r\n</tr>\r\n</tbody>\r\n<tbody>\r\n<tr>\r\n<td>Толщина пленки, мм</td>\r\n<td>0,05</td>\r\n<td>0,10</td>\r\n<td>0,15</td>\r\n<td>1,00</td>\r\n</tr>\r\n<tr>\r\n<td>Пропускание, %</td>\r\n<td>88</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<table class="responsive-table" border="0" width="100%" cellspacing="0" cellpadding="0">\r\n<tbody>\r\n<tr>\r\n<td align="center" valign="middle" bgcolor="#FFFBFF" width="50%"></td>\r\n</tr>\r\n</tbody>\r\n</table>', 'Фторопласт - описание свойств от показателей', '', 'inherit', 'closed', 'closed', '', '2893-revision-v1', '', '', '2018-05-07 19:34:51', '2018-05-07 19:34:51', '', 2893, '<p>Фторопласт -4 - кристаллический полимер, температурой плавления кристаллитов 327°С и температурой стеклования аморфных участков от -100 до -120°С. Даже при температуре выше температуры разложения (415°С) фторопласт-4 не переходит в вязкотекучее состоян', 0, 'revision', '', 0);
INSERT INTO `fttwp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(3185, 1, '2018-05-07 19:45:10', '2018-05-07 19:45:10', '<p>Фторопласт -4 - кристаллический полимер, температурой плавления кристаллитов 327°С и температурой стеклования аморфных участков от -100 до -120°С. Даже при температуре выше температуры разложения (415°С) фторопласт-4 не переходит в вязкотекучее состояние (при 370°С вязкость его расплава равна ≈10<sup>11</sup>П, т.е. в 1000000 раз больше вязкости, (необходимой для литья под давлением), поэтому переработка его возможна только методом спекания отпрессованных таблеток.\r\n</p><p>\r\nВ зависимости от скорости охлаждения (до температуры ниже 250°С) после спекания можно получить закаленные изделия со степенью кристалличности ≈50% и плотностью ≈2,15 г/см<sup>3</sup> или незакаленные со степенью кристалличности более 65% плотностью выше 2,20 г/см3.При температуре эксплуатации и от -269°С до +260°С степень кристалличности, достигнутая при данном режиме охлаждения, не меняется, при температуре выше 260°С степень кристалличности постепенно увеличивается, особенно быстро она вырастает при 310 - 315°С.</p>\r\n<div>\r\n\r\n\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td><strong>Степень кристалличности, %</strong></td>\r\n<td><strong>Плотность при\r\n23°С, г/см<sup>3</sup></strong></td>\r\n<td><strong>Степень кристалличности, %</strong></td>\r\n<td><strong>Плотность при\r\n23°С, г/см<sup>3</sup></strong></td>\r\n</tr>\r\n<tr>\r\n<td>40.0</td>\r\n<td>2.12</td>\r\n<td>69.4</td>\r\n<td>2.21</td>\r\n</tr>\r\n<tr>\r\n<td>43.2</td>\r\n<td>2.13</td>\r\n<td>72.8</td>\r\n<td>2.22</td>\r\n</tr>\r\n<tr>\r\n<td>46.5</td>\r\n<td>2.14</td>\r\n<td>75.2</td>\r\n<td>2.23</td>\r\n</tr>\r\n<tr>\r\n<td>49.7</td>\r\n<td>2.15</td>\r\n<td>78.0</td>\r\n<td>2.24</td>\r\n</tr>\r\n<tr>\r\n<td>53.0</td>\r\n<td>2.16</td>\r\n<td>80.7</td>\r\n<td>2.25</td>\r\n</tr>\r\n<tr>\r\n<td>56.3</td>\r\n<td>2.17</td>\r\n<td>82.6</td>\r\n<td>2.26</td>\r\n</tr>\r\n<tr>\r\n<td>59.7</td>\r\n<td>2.18</td>\r\n<td>85.2</td>\r\n<td>2.27</td>\r\n</tr>\r\n<tr>\r\n<td>63.1</td>\r\n<td>2.19</td>\r\n<td>89.0</td>\r\n<td>2.28</td>\r\n</tr>\r\n<tr>\r\n<td>66.5</td>\r\n<td>2.20</td>\r\n<td>-</td>\r\n<td>-</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>Об отсутствии же пористости свидетельствует полная прозрачность образца во время спекания при 370-390°С. Даже незначительная пористость вызывает мутность образца. Пористость, равная примерно 0,1-0,2%, заметно влияет на точность определения плотности.\r\n</p><p>Данные о зависимости удельного объема и плотности от температуры для образца со степенью кристалличности 68% (плотность медленно охлажденного изделия) приведены ниже:</p>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td><strong>Температура, °С</strong></td>\r\n<td><strong>Удельный объем, см<sup>3</sup>/г</strong></td>\r\n<td><strong>Плотность, г/см<sup>3</sup></strong></td>\r\n<td><strong>Температура, °С</strong></td>\r\n<td><strong>Удельный объем, cм<sup>3</sup>/г</strong></td>\r\n<td><strong>Плотность, г/см<sup>3</sup></strong></td>\r\n</tr>\r\n<tr>\r\n<td>-50</td>\r\n<td>0.440</td>\r\n<td>2.27</td>\r\n<td>175</td>\r\n<td>0.4769</td>\r\n<td>2.10</td>\r\n</tr>\r\n<tr>\r\n<td>-25</td>\r\n<td>0.443</td>\r\n<td>2.26</td>\r\n<td>200</td>\r\n<td>0.482</td>\r\n<td>2.08</td>\r\n</tr>\r\n<tr>\r\n<td>0</td>\r\n<td>0.447</td>\r\n<td>2.24</td>\r\n<td>225</td>\r\n<td>0.488</td>\r\n<td>2.05</td>\r\n</tr>\r\n<tr>\r\n<td>+25</td>\r\n<td>0.453*</td>\r\n<td>2.21</td>\r\n<td>250</td>\r\n<td>0.495</td>\r\n<td>2.02</td>\r\n</tr>\r\n<tr>\r\n<td>+50</td>\r\n<td>0.456</td>\r\n<td>2.19</td>\r\n<td>275</td>\r\n<td>0.503</td>\r\n<td>1.99</td>\r\n</tr>\r\n<tr>\r\n<td>+75</td>\r\n<td>0.459</td>\r\n<td>2.18</td>\r\n<td>300</td>\r\n<td>0.514</td>\r\n<td>1.95</td>\r\n</tr>\r\n<tr>\r\n<td>+100</td>\r\n<td>0.463</td>\r\n<td>2.16</td>\r\n<td>325</td>\r\n<td>0.534</td>\r\n<td>1.88</td>\r\n</tr>\r\n<tr>\r\n<td>+125</td>\r\n<td>0.467</td>\r\n<td>2.14</td>\r\n<td>327</td>\r\n<td>0.640**</td>\r\n<td>1.57</td>\r\n</tr>\r\n<tr>\r\n<td>+150</td>\r\n<td>0.471</td>\r\n<td>2.12</td>\r\n<td>350</td>\r\n<td>0.655</td>\r\n<td>1.53</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n* При нагревании от 19,6 до 22°C удлиненный объём увеличивается на 0,74%\r\n** При 327°С удлиненный объём увеличивается на 20%.\r\n\r\n<h2>ФИЗИКО-МЕХАНИЧЕСКИЕ СВОЙСТВА ФТОРОПЛАСТА-4</h2>\r\n<p>Основные показатели физико-механических свойств фторопласта-4 приведены ниже:</p>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td><strong>Разрушающее напряжение, кгс/см<sup>2</sup></strong></td>\r\n<td>Значения</td>\r\n</tr>\r\n<tr>\r\n<td>при растяжении:</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- незакаленный образец (кристалличность 05-08%)</td>\r\n<td>140-350*</td>\r\n</tr>\r\n<tr>\r\n<td>- закаленный образец (кристалличность 50%)</td>\r\n<td>160-315*</td>\r\n</tr>\r\n<tr>\r\n<td>при сжатии:</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- при 1%-ной деформации</td>\r\n<td>100</td>\r\n</tr>\r\n<tr>\r\n<td>- 10%-ной деформации</td>\r\n<td>185</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Сопротивлению изгибу (стрела прогиба 6 мм)</strong></td>\r\n<td>185</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Относительное удлинение при разрыт, %</strong></td>\r\n<td>250-500</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Остаточное удлинение, %</strong></td>\r\n<td>250-350</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Напряжение при 10%-ном удлинении, кгс/см<sup>2</sup></strong></td>\r\n<td>110-120</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Модуль упругости, кгс/см<sup>2</sup></strong></td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- при изгибе при 20°С</td>\r\n<td>4700-8500</td>\r\n</tr>\r\n<tr>\r\n<td>- сдвиге 2700</td>\r\n<td>2700</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Ударная вязкость, кгс·см/см<sup>2</sup></strong></td>\r\n<td>100 (не ломается)</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Ударное растяжение, кгс·см/см<sup>2</sup> (DIN 53448)</strong></td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- при 20°С</td>\r\n<td>650</td>\r\n</tr>\r\n<tr>\r\n<td>- 23°С</td>\r\n<td>680</td>\r\n</tr>\r\n<tr>\r\n<td>(удлинение при 20°С - 20%, при 23°С - 30%)</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Твердость:</strong></td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>по Бринеллю, кгс/мм<sup>2</sup></td>\r\n<td>3-4</td>\r\n</tr>\r\n<tr>\r\n<td>по Шору при 20°С</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- шкала С</td>\r\n<td>85-87</td>\r\n</tr>\r\n<tr>\r\n<td>- шкала D</td>\r\n<td>55-59</td>\r\n</tr>\r\n<tr>\r\n<td>Твердость по Роквеллу</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- шкала I</td>\r\n<td>80-95</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>В зависимости от того, как вырезан образец: поперек направления прессования-высокие значения, вдоль направления прессования-малые.</p>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td><strong>Показатели</strong></td>\r\n<td colspan="10"><strong>Температура, °С</strong></td>\r\n</tr>\r\n<tr>\r\n<td>-</td>\r\n<td>-60</td>\r\n<td>-40</td>\r\n<td>-20</td>\r\n<td>0</td>\r\n<td>20</td>\r\n<td>40</td>\r\n<td>60</td>\r\n<td>80</td>\r\n<td>100</td>\r\n<td>120</td>\r\n</tr>\r\n<tr>\r\n<td>Разрушающее напряжение при растяжении, кгс/см<sup>2</sup></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>- незакаленный образец</td>\r\n<td>-</td>\r\n<td>350</td>\r\n<td>325</td>\r\n<td>300</td>\r\n<td>200</td>\r\n<td>180</td>\r\n<td>-</td>\r\n<td>135</td>\r\n<td>115</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- закаленный образец</td>\r\n<td>-</td>\r\n<td>500</td>\r\n<td>440</td>\r\n<td>330</td>\r\n<td>250</td>\r\n<td>240</td>\r\n<td>-</td>\r\n<td>200</td>\r\n<td>190</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>Относительное удлинение при разрыве, %</td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>- незакаленный образец</td>\r\n<td>-</td>\r\n<td>70</td>\r\n<td>100</td>\r\n<td>150</td>\r\n<td>470</td>\r\n<td>650</td>\r\n<td>-</td>\r\n<td>600</td>\r\n<td>540</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- закаленный образец</td>\r\n<td>-</td>\r\n<td>100</td>\r\n<td>160</td>\r\n<td>190</td>\r\n<td>400</td>\r\n<td>500</td>\r\n<td>-</td>\r\n<td>500</td>\r\n<td>480</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>Модуль упругости, кгс/см<sup>2</sup></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>при сжатии</td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>- незакаленный образец</td>\r\n<td>18000</td>\r\n<td>17000</td>\r\n<td>15000</td>\r\n<td>11000</td>\r\n<td>7000</td>\r\n<td>4500</td>\r\n<td>3300</td>\r\n<td>2400</td>\r\n<td>1700</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>при сжатии</td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>- незакаленный образец</td>\r\n<td>27800</td>\r\n<td>23900</td>\r\n<td>23300</td>\r\n<td>18100</td>\r\n<td>8500</td>\r\n<td>5100</td>\r\n<td>4800</td>\r\n<td>3800</td>\r\n<td>-</td>\r\n<td>2450</td>\r\n</tr>\r\n<tr>\r\n<td>- закаленный образец</td>\r\n<td>13200</td>\r\n<td>11300</td>\r\n<td>9800</td>\r\n<td>7400</td>\r\n<td>4700</td>\r\n<td>4000</td>\r\n<td>2900</td>\r\n<td>2180</td>\r\n<td>-</td>\r\n<td>1100</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>Данные о зависимости физико-механических свойств фторопласта-4 от температуры приведены ниже.</p>\r\n\r\n<h2>Физико-механические свойства фторопласта-4 при низких температурах\r\n</h2>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td><strong>Показатели</strong></td>\r\n<td colspan="6"><strong>Температура, °С</strong></td>\r\n</tr>\r\n<tr>\r\n<td></td>\r\n<td>-93</td>\r\n<td>-123</td>\r\n<td>-153</td>\r\n<td>-193</td>\r\n<td>-223</td>\r\n<td>-269</td>\r\n</tr>\r\n<tr>\r\n<td>Разрушающее напряжение при сжатии *, кгс/см<sup>2</sup></td>\r\n<td>350</td>\r\n<td>-</td>\r\n<td>980</td>\r\n<td>1260</td>\r\n<td>1554</td>\r\n<td>1750-1960</td>\r\n</tr>\r\n<tr>\r\n<td>Модуль упругости при сжатии, кгс/см<sup>2</sup></td>\r\n<td>-</td>\r\n<td>52500</td>\r\n<td>-</td>\r\n<td>-</td>\r\n<td>-</td>\r\n<td>70000</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>* Разрушающее напряжение при сжатии равно напряжению, при котором деформация составляет 0,2%.</p>\r\n\r\n<h2>Зависимость деформации фторопласта-4 при сжатии от температуры:</h2>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td><strong>Деформация, %</strong></td>\r\n<td colspan="7"><strong>Нагрузка, вызывающая деформацию, кгс/см</strong><sup>2</sup></td>\r\n</tr>\r\n<tr>\r\n<td>-</td>\r\n<td>-50°С</td>\r\n<td> 0°С</td>\r\n<td> 25°С</td>\r\n<td>50°С</td>\r\n<td>100°С</td>\r\n<td>150°С</td>\r\n<td>200°С</td>\r\n</tr>\r\n<tr>\r\n<td>1</td>\r\n<td>203</td>\r\n<td>157</td>\r\n<td>62</td>\r\n<td>49</td>\r\n<td>31</td>\r\n<td>17,5</td>\r\n<td>11</td>\r\n</tr>\r\n<tr>\r\n<td>2</td>\r\n<td>304</td>\r\n<td>210</td>\r\n<td>92</td>\r\n<td>66</td>\r\n<td>39</td>\r\n<td>27</td>\r\n<td>20</td>\r\n</tr>\r\n<tr>\r\n<td>3</td>\r\n<td>350</td>\r\n<td>236</td>\r\n<td>105</td>\r\n<td>77</td>\r\n<td>48</td>\r\n<td>33</td>\r\n<td>27</td>\r\n</tr>\r\n<tr>\r\n<td>4</td>\r\n<td>374</td>\r\n<td>251</td>\r\n<td>120</td>\r\n<td>85</td>\r\n<td>59</td>\r\n<td>39</td>\r\n<td>31</td>\r\n</tr>\r\n<tr>\r\n<td>5</td>\r\n<td>390</td>\r\n<td>262</td>\r\n<td>127</td>\r\n<td>92</td>\r\n<td>62</td>\r\n<td>44</td>\r\n<td>35</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>Одним из важнейших прочностных показателей является предел текучести при растяжении, т.е. то напряжение, при котором возникают остаточные деформации. Он зависит от степени кристалличности, скорости растяжения и температуры. При степени кристалличности 65% и скорости растяжения 100 мм/мин зависимость предела текучести от абсолютной температуры Т (в К) описывается эмпирической формулой (справедливой от 20 до 300°С):\r\nlgσT= 0,53166+483,64/Т</p>\r\n<p>Ниже приведены значения пределов текучести для некоторых температур, рассчитанные по этой формуле:</p>\r\n\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tr>\r\n<td>Температура, °С</td><td>  25</td><td>50</td><td>75</td><td>100</td><td>150</td><td>200</td><td>250</td></tr>\r\n<tr><td>Предел текучести, кгс/см2</td><td>42,4</td><td>106,9</td><td>83,5</td><td>67,2</td><td>46,6</td><td>35,5</td><td>28,6</tr></table>\r\n\r\n<p>При длительном воздействии нагрузок остаточные деформации возникают при меньших напряжениях (40-50% от рассчитанных по формуле).</p><p>\r\nПри конструировании изделий из фторопласта-4 следует учитывать ползучесть. Ползучесть (деформация при длительном действии нагрузки) рассчитывается по формуле:<br>\r\nlgγt=lgγ1+a·lgt<br>\r\nгде γt - деформация за t сут; γ1 - деформация за 1 сут; а - коэффициент, зависящий в основном от температуры и в меньшей степени от нагрузки, если она не превышает 40-50% предела текучести.</p><p>\r\nЗначения коэффициента a и некоторые данные о ползучести для образцов со степенью кристалличности 50% приведены в таблице. Деформация за 1 сут (γ1) при других нагрузках и температурах определяется опытным путем. При степени кристалличности 65-68% ползучесть меньше.</p>\r\n\r\n<h2>   Ползучесть фторопласта-4</h2>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td><strong>Температура, °С</strong></td>\r\n<td><strong>Нагрузка, кгс/см<sup>2</sup></strong></td>\r\n<td colspan="2"><strong>Деформация, %</strong></td>\r\n<td><strong>Коэффициент а\r\n</strong></td>\r\n</tr>\r\n<tr>\r\n<td colspan="2">Сжатие</td>\r\n<td>1 сут (γ1)</td>\r\n<td>4 сут (γ4)</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>20</td>\r\n<td>33</td>\r\n<td>6,00</td>\r\n<td>6,25</td>\r\n<td>0,030</td>\r\n</tr>\r\n<tr>\r\n<td>20</td>\r\n<td>21</td>\r\n<td>3,05</td>\r\n<td>3,19</td>\r\n<td>0,032</td>\r\n</tr>\r\n<tr>\r\n<td colspan="2">Растяжение</td>\r\n<td>1 сут (γ1)</td>\r\n<td>4 сут (γ4)</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>40</td>\r\n<td>28</td>\r\n<td>2,72</td>\r\n<td>2,87</td>\r\n<td>0,038</td>\r\n</tr>\r\n<tr>\r\n<td>100</td>\r\n<td>28</td>\r\n<td>5,58</td>\r\n<td>5,90</td>\r\n<td>0,040</td>\r\n</tr>\r\n<tr>\r\n<td>140</td>\r\n<td>21</td>\r\n<td>4,67</td>\r\n<td>4,94</td>\r\n<td>0,042</td>\r\n</tr>\r\n<tr>\r\n<td>200</td>\r\n<td>14</td>\r\n<td>4,08</td>\r\n<td>4,50</td>\r\n<td>0,048</td>\r\n</tr>\r\n<tr>\r\n<td>250</td>\r\n<td>14</td>\r\n<td>5,17</td>\r\n<td>5,58</td>\r\n<td>0,055</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<h2>                                           АНТИФРИКЦИОННЫЕ СВОЙСТВА ФТОРОПЛАСТА-4\r\n</h2>\r\nДанные о зависимости коэффициента трения от нагрузки [статической и динамической (при малых скоростях) коэффициенты трения фторопласта-4 по стали без смазки одинаковы] приведены ниже:\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Нагрузка, кгс/см2</td>\r\n<td>1</td>\r\n<td>3</td>\r\n<td>10</td>\r\n<td>20</td>\r\n</tr>\r\n<tr>\r\n<td>Коэффициент трения</td>\r\n<td>0,4</td>\r\n<td>0,1</td>\r\n<td>0,06</td>\r\n<td>0,05</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>При наличии смазки он примерно в 2 раза меньше.</p><p>\r\nДинамический коэффициент трения фторопласта-4 по стали без смазки при нагрузке ~ 20 кгс/см2 зависит от скорости скольжения:</p>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Скорость скольжения, см/c</td>\r\n<td>4</td>\r\n<td>8</td>\r\n<td>20</td>\r\n<td>40</td>\r\n<td>80</td>\r\n<td>160</td>\r\n</tr>\r\n<tr>\r\n<td>Динамический коэффициент трения</td>\r\n<td>0,05</td>\r\n<td>0,1</td>\r\n<td>0,15</td>\r\n<td>0,23</td>\r\n<td>0,24</td>\r\n<td>0,27</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>В присутствии наполнителя при малых скоростях скольжения коэффициент трения несколько выше, а при больших скоростях - ниже, чем коэффициент трения чистого фторопласта-4 по стали.</p><p>\r\nПри 327°С (на поверхности трения) коэффициент трения фторопласта-4 по стали резко возрастает (в несколько раз), что приводит к катастрофически быстрому износу и разрушению подшипника.<p>\r\n\r\n<h2> ТЕПЛОФИЗИЧЕСКИЕ СВОЙСТВА ФТОРОПЛАСТА-4</h2>\r\n<p>Неспеченный фторопласт-4 (в виде порошка) имеет степень кристалличности 95 - 98%, после спекания - от 50% (закаленный) до 68 - 70% (незакаленный). Ниже 19,6°С элементарная ячейка кристалла фторопласта-4 состоит из 13 групп CF2, выше 19,6°С - из 15 групп CF2. При 19,6°С триклиническая упаковка переходит в менее упорядоченную, гексагональную, что сопровождается увеличение объема кристаллитов на 0,0058 см3/г (1,2 объемн. %), или увеличением объема образца при степени кристалличности 68% на 0,74%. При наличии внешнего давления точка перехода понижается на 0,013°С на каждую атмосферу. При 30°С имеет место второй переход кристаллической структуры, но изменение объема составляет едва 1/10 часть изменения объема при 19,6°С. Под высоким давлением (4500 кгс/см2 при 70°С) возникает третий переход.</p><p>\r\nТемпература стеклования аморфных участков, определенная по температуре хрупкости, колеблется от -97 до -100°С, а по точке перегиба кривой зависимости модуля упругости составляет -120°С. Температура перехода аморфного твердого тела в переохлажденную жидкость равна 127°С.</p><p>\r\nПри 327°С кристаллиты фторопласта-4 плавятся, и он становится полностью аморфным, совершенно прозрачным (при отсутствии пористости), высокоэластичным, но не течет (вязкость выше 1011 П). Объем возрастает на 20%.\r\n</p><p>\r\nТочка плавления зависит от внешнего давления - на каждую атмосферу повышается на 0,154 °С. При остывании расплава ниже 327 °С образец мутнеет и становится непрозрачным - молочно-белым.   Скорость кристаллизации зависит от температуры (максимальная скорость при 310-315 °С), от продолжительности выдержки в расплавленном состоянии при 370-390 °С (чем больше время спекания, тем быстрее кристаллизуется образец) и от среднего молекулярного веса полимера (чем ниже молекулярный вес полимера, тем быстрее он кристаллизуется). На этом основан метод косвенной оценки молекулярного веса фторопласта-4: образец в виде диска толщиной 2 мм спекают при 370 °С в течение 13 ч и охлаждают от 370 до 250 °С в течение 5 ч. По плотности полученного образца при 23 °С можно оценить молекулярный вес: 2,16-2,19 г/см3-для высокомолекулярного полимера, 2,20-2,22 г/см3-для низкомолекулярного.\r\n</p><p>\r\n<h2>Ниже приведены некоторые теплофизические свойства фторопласта-4:</h2>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Теплостойкость по Вика (при нагрузке 5 кгс), °С</td>\r\n<td>110</td>\r\n</tr>\r\n<tr>\r\n<td>Удельная теплоемкость, ккал/(кг·°С)</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>при 0°С</td>\r\n<td>0,23</td>\r\n</tr>\r\n<tr>\r\n<td>при 50°С</td>\r\n<td>0,25</td>\r\n</tr>\r\n<tr>\r\n<td>Коэффициент теплопроводности, ккал/(м·ч·°С)</td>\r\n<td>0,20</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>Термический коэффициент линейного расширения зависит от температуры:</p>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Температура, °С</td>\r\n<td>от -60 до -10</td>\r\n<td>19,6</td>\r\n<td>30</td>\r\n<td>40</td>\r\n<td>200</td>\r\n<td>300</td>\r\n</tr>\r\n<tr>\r\n<td>Термический коэффициент линейного расширения α·105, 1/°С</td>\r\n<td>8</td>\r\n<td>54</td>\r\n<td>28</td>\r\n<td>11</td>\r\n<td>25</td>\r\n<td>64</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>На практике удобнее пользоваться средними значениями термического коэффициента линейного расширения для определенных интервалов температур. Следует также учитывать, что при нагревании изделий из фторопласта-4 в них часто возникают внутренние напряжения, вызывающие необратимое изменение размеров. Иногда вместо ожидаемого при нагревании удлинения образца он сокращается.</p><p>\r\nДанные, приведенные ниже, относятся к образцам, в которых полностью отсутствуют внутренние напряжения:</p>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Температура, °C</td>\r\n<td>Термический коэффициент линейного расширения α·105, 1/°C</td>\r\n<td>Изменение размеров изделия*, %</td>\r\n<td>Температура, °C</td>\r\n<td>Термический коэффициент линейного расширения α·105, 1/°C</td>\r\n<td>Изменение размеров изделия*, %</td>\r\n</tr>\r\n<tr>\r\n<td>от -193 до +25</td>\r\n<td>8,6</td>\r\n<td>-1,85</td>\r\n<td>от +25 до +100</td>\r\n<td>12,4</td>\r\n<td>+0,93</td>\r\n</tr>\r\n<tr>\r\n<td>от -150 до +25</td>\r\n<td>9,6</td>\r\n<td>-1,68</td>\r\n<td>от +25 до +150</td>\r\n<td>13,5</td>\r\n<td>+1,59</td>\r\n</tr>\r\n<tr>\r\n<td>от -100 до +25</td>\r\n<td>11,2</td>\r\n<td>-1,40</td>\r\n<td>от +25 до +200</td>\r\n<td>15,1</td>\r\n<td>+2,64</td>\r\n</tr>\r\n<tr>\r\n<td>от -50 до +25</td>\r\n<td>13,5</td>\r\n<td>-1,01</td>\r\n<td>от +25 до +250</td>\r\n<td>17,4</td>\r\n<td>+3,92</td>\r\n</tr>\r\n<tr>\r\n<td> от 0 до +25</td>\r\n<td>20,0</td>\r\n<td>-0,50</td>\r\n<td>от +25 до +300</td>\r\n<td>21,8</td>\r\n<td>+5,99</td>\r\n</tr>\r\n<tr>\r\n<td>от +25 до +50</td>\r\n<td>12,4</td>\r\n<td>+0,31</td>\r\n<td>от +25 до +300</td>\r\n<td>21,8</td>\r\n<td>+5,99</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>* От размера при 25°С.</p>\r\n\r\n<h2>ЭЛЕКТРИЧЕСКИЕ СВОЙТСВА ФТОРОПЛАСТА-4</h2>\r\n\r\n<p>Показатели электрических свойств фторопласта-4 приведены ниже:</p>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Удельное электрическое сопротивление:</td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>-поверхностное, Ом</td>\r\n<td>&gt;10<sup>17</sup></td>\r\n</tr>\r\n<tr>\r\n<td>-на воздухе со 100%-ной относительной влажностью</td>\r\n<td>&gt;10<sup>12</sup></td>\r\n</tr>\r\n<tr>\r\n<td>-объемное (до 150<sup>о</sup>С), Ом·см</td>\r\n<td>101<sup>7</sup> - 10<sup>20</sup></td>\r\n</tr>\r\n<tr>\r\n<td>-после длительного пребывания в воде не меняется</td>\r\n<td>1,9-2,2</td>\r\n</tr>\r\n<tr>\r\n<td>Диэлектрическая проницаемость (при 60 - 1010 Гц)</td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>Тангенс угла диэлектрических потерь (при 60 - 1010 Гц)</td>\r\n<td>&lt;1·10<sup>17</sup></td>\r\n</tr>\r\n<tr>\r\n<td>Электрическая прочность, кВ/мм:</td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>-при толщине образца 4 мм</td>\r\n<td>25-27</td>\r\n</tr>\r\n<tr>\r\n<td>-при толщине образца 0,1 - 0,3 мм</td>\r\n<td>40-80</td>\r\n</tr>\r\n<tr>\r\n<td>-при толщине образца 0,005 - 0,02 мм</td>\r\n<td>200-300</td>\r\n</tr>\r\n<tr>\r\n<td>Дугостойкость, с (сплошного токопроводящего слоя не образуется)</td>\r\n<td>250-700</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>Данные о зависимости тангенса угла диэлектрических потерь от частоты приведены ниже:</p>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Частота, Гц</td>\r\n<td>60</td>\r\n<td>10<sup>3</sup></td>\r\n<td>10<sup>4</sup></td>\r\n<td>10<sup>5</sup></td>\r\n<td>10<sup>6</sup></td>\r\n<td>10<sup>7</sup></td>\r\n</tr>\r\n<tr>\r\n<td>tgδ·10<sup>4</sup></td>\r\n<td>0,5</td>\r\n<td>0,3</td>\r\n<td>0,4</td>\r\n<td>0,7</td>\r\n<td>0,7</td>\r\n<td>0,7</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>Диэлектрическая проницаемость фторопласта-4 вплоть до 1010 Гц не зависит от частоты, а зависит от плотности: є= <u>1+0,238*d</u>\r\n2-0,119*d\r\nгде d - плотность при данной степени кристалличности и температуре.\r\nТангенс угла диэлектрических потерь остается постоянным при температуре от -60 до 250<sup>о</sup>С.\r\nПрогрев при 300<sup>о</sup>С в течение 6 месяцев не влияет на диэлектрические свойства фторопласта-4.<p>\r\n\r\n<h2>ХИМИЧЕСКИЕ И ДРУГИЕ СВОЙСТВА ФТОРОПЛАСТА-4</h2>\r\n\r\nФторопласт-4 является самым стойким из всех известных металлов - пластмасс, металлов, стекол, эмалей, сплавов и т.п. На него совершенно не действуют кислоты, окислители, щелочи, растворители. На фторопласт-4 действуют только расплавленные щелочные металлы и их комплексные соединения с аммиаком, нафталином, пиридином, а также трехфтористых хлор и элементный фтор при повышенных температурах. При температурах выше 327<sup>о</sup>С фторопласт набухает в жидких фторуглеродах, например в перфторкеросине. При 20<sup>о</sup>С фторопласт-4 слегка набухает (3 - 9%) в фторхлорсодержащих газах (фреонах).\r\nВыше 350<sup>о</sup>С фторопласт-4 реагирует с щелочеземельными металлами и их соединениями (окислами и карбонатами), а также с окислами некоторых других металлов (свинца, кадмия, меди).\r\nФторопласт-4 не смачивается водой при кратковременном погружении (угол смачивания 126<sup>о</sup>С), но смачивается при длительном пребывании в дистиллированной воде (15 - 20 суток). В соленой воде (например, морской) на поверхности фторопласта-4 через 15 - 20 суток отлагается пленка солей, смываемая дистиллированной водой.\r\nВодопоглощение за 24 часа (и более продолжительное время) - ниже ошибки взвешивания (0,00%).\r\nФторопласт-4 абсолютно стоек в тропических условиях и не подвижен действию грибков (но и не подавляет их развитие).\r\nВлагопроницаемость при 20<sup>о</sup>С равна 3·10<sup>-9</sup> - 6·10<sup>-9</sup> г/(см·ч·мм рт. ст.); паропроницаемость при 20<sup>о</sup>С составляет 0,6·10<sup>-9</sup> - 1,2·10<sup>-9</sup> г/(см·ч·мм рт. ст.).\r\nДанные о газопроницаемости пленки из фтороплавта-4 (при отсутствии пор) толщиной 0,1 мм при 20<sup>о</sup>С [в см<sup>3</sup>/(см·с·мм рт. ст.)] приведены ниже:\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Воздух</td>\r\n<td>1,1*10<sup>-9</sup></td>\r\n</tr>\r\n<tr>\r\n<td>Азот</td>\r\n<td>0,7*10<sup>-9</sup></td>\r\n</tr>\r\n<tr>\r\n<td>Кислород</td>\r\n<td>2,3*10<sup>-9</sup></td>\r\n</tr>\r\n<tr>\r\n<td>Водород</td>\r\n<td>6,3*10<sup>-9</sup></td>\r\n</tr>\r\n<tr>\r\n<td>Двуокись углерода</td>\r\n<td>4,8*10<sup>-9</sup></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\nПри наличии пористости проницаемость может увеличиваться до 1000 раз.\r\nФторопласт-4 предназначен для видимого света только при малой толщине пленки:\r\n<table class="responsive-table" width="100%">\r\n<tbody>\r\n<tr>\r\n<td width="95%"></td>\r\n</tr>\r\n</tbody>\r\n<tbody>\r\n<tr>\r\n<td>Толщина пленки, мм</td>\r\n<td>0,05</td>\r\n<td>0,10</td>\r\n<td>0,15</td>\r\n<td>1,00</td>\r\n</tr>\r\n<tr>\r\n<td>Пропускание, %</td>\r\n<td>88</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<table class="responsive-table" border="0" width="100%" cellspacing="0" cellpadding="0">\r\n<tbody>\r\n<tr>\r\n<td align="center" valign="middle" bgcolor="#FFFBFF" width="50%"></td>\r\n</tr>\r\n</tbody>\r\n</table>', 'Фторопласт - описание свойств от показателей', '', 'inherit', 'closed', 'closed', '', '2893-revision-v1', '', '', '2018-05-07 19:45:10', '2018-05-07 19:45:10', '', 2893, '<p>Фторопласт -4 - кристаллический полимер, температурой плавления кристаллитов 327°С и температурой стеклования аморфных участков от -100 до -120°С. Даже при температуре выше температуры разложения (415°С) фторопласт-4 не переходит в вязкотекучее состоян', 0, 'revision', '', 0);
INSERT INTO `fttwp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(3186, 1, '2018-05-07 19:47:12', '2018-05-07 19:47:12', '<p>Фторопласт -4 - кристаллический полимер, температурой плавления кристаллитов 327°С и температурой стеклования аморфных участков от -100 до -120°С. Даже при температуре выше температуры разложения (415°С) фторопласт-4 не переходит в вязкотекучее состояние (при 370°С вязкость его расплава равна ≈10<sup>11</sup>П, т.е. в 1000000 раз больше вязкости, (необходимой для литья под давлением), поэтому переработка его возможна только методом спекания отпрессованных таблеток.\r\n</p><p>\r\nВ зависимости от скорости охлаждения (до температуры ниже 250°С) после спекания можно получить закаленные изделия со степенью кристалличности ≈50% и плотностью ≈2,15 г/см<sup>3</sup> или незакаленные со степенью кристалличности более 65% плотностью выше 2,20 г/см3.При температуре эксплуатации и от -269°С до +260°С степень кристалличности, достигнутая при данном режиме охлаждения, не меняется, при температуре выше 260°С степень кристалличности постепенно увеличивается, особенно быстро она вырастает при 310 - 315°С.</p>\r\n<div>\r\n\r\n\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td><strong>Степень кристалличности, %</strong></td>\r\n<td><strong>Плотность при\r\n23°С, г/см<sup>3</sup></strong></td>\r\n<td><strong>Степень кристалличности, %</strong></td>\r\n<td><strong>Плотность при\r\n23°С, г/см<sup>3</sup></strong></td>\r\n</tr>\r\n<tr>\r\n<td>40.0</td>\r\n<td>2.12</td>\r\n<td>69.4</td>\r\n<td>2.21</td>\r\n</tr>\r\n<tr>\r\n<td>43.2</td>\r\n<td>2.13</td>\r\n<td>72.8</td>\r\n<td>2.22</td>\r\n</tr>\r\n<tr>\r\n<td>46.5</td>\r\n<td>2.14</td>\r\n<td>75.2</td>\r\n<td>2.23</td>\r\n</tr>\r\n<tr>\r\n<td>49.7</td>\r\n<td>2.15</td>\r\n<td>78.0</td>\r\n<td>2.24</td>\r\n</tr>\r\n<tr>\r\n<td>53.0</td>\r\n<td>2.16</td>\r\n<td>80.7</td>\r\n<td>2.25</td>\r\n</tr>\r\n<tr>\r\n<td>56.3</td>\r\n<td>2.17</td>\r\n<td>82.6</td>\r\n<td>2.26</td>\r\n</tr>\r\n<tr>\r\n<td>59.7</td>\r\n<td>2.18</td>\r\n<td>85.2</td>\r\n<td>2.27</td>\r\n</tr>\r\n<tr>\r\n<td>63.1</td>\r\n<td>2.19</td>\r\n<td>89.0</td>\r\n<td>2.28</td>\r\n</tr>\r\n<tr>\r\n<td>66.5</td>\r\n<td>2.20</td>\r\n<td>-</td>\r\n<td>-</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>Об отсутствии же пористости свидетельствует полная прозрачность образца во время спекания при 370-390°С. Даже незначительная пористость вызывает мутность образца. Пористость, равная примерно 0,1-0,2%, заметно влияет на точность определения плотности.\r\n</p><p>Данные о зависимости удельного объема и плотности от температуры для образца со степенью кристалличности 68% (плотность медленно охлажденного изделия) приведены ниже:</p>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td><strong>Температура, °С</strong></td>\r\n<td><strong>Удельный объем, см<sup>3</sup>/г</strong></td>\r\n<td><strong>Плотность, г/см<sup>3</sup></strong></td>\r\n<td><strong>Температура, °С</strong></td>\r\n<td><strong>Удельный объем, cм<sup>3</sup>/г</strong></td>\r\n<td><strong>Плотность, г/см<sup>3</sup></strong></td>\r\n</tr>\r\n<tr>\r\n<td>-50</td>\r\n<td>0.440</td>\r\n<td>2.27</td>\r\n<td>175</td>\r\n<td>0.4769</td>\r\n<td>2.10</td>\r\n</tr>\r\n<tr>\r\n<td>-25</td>\r\n<td>0.443</td>\r\n<td>2.26</td>\r\n<td>200</td>\r\n<td>0.482</td>\r\n<td>2.08</td>\r\n</tr>\r\n<tr>\r\n<td>0</td>\r\n<td>0.447</td>\r\n<td>2.24</td>\r\n<td>225</td>\r\n<td>0.488</td>\r\n<td>2.05</td>\r\n</tr>\r\n<tr>\r\n<td>+25</td>\r\n<td>0.453*</td>\r\n<td>2.21</td>\r\n<td>250</td>\r\n<td>0.495</td>\r\n<td>2.02</td>\r\n</tr>\r\n<tr>\r\n<td>+50</td>\r\n<td>0.456</td>\r\n<td>2.19</td>\r\n<td>275</td>\r\n<td>0.503</td>\r\n<td>1.99</td>\r\n</tr>\r\n<tr>\r\n<td>+75</td>\r\n<td>0.459</td>\r\n<td>2.18</td>\r\n<td>300</td>\r\n<td>0.514</td>\r\n<td>1.95</td>\r\n</tr>\r\n<tr>\r\n<td>+100</td>\r\n<td>0.463</td>\r\n<td>2.16</td>\r\n<td>325</td>\r\n<td>0.534</td>\r\n<td>1.88</td>\r\n</tr>\r\n<tr>\r\n<td>+125</td>\r\n<td>0.467</td>\r\n<td>2.14</td>\r\n<td>327</td>\r\n<td>0.640**</td>\r\n<td>1.57</td>\r\n</tr>\r\n<tr>\r\n<td>+150</td>\r\n<td>0.471</td>\r\n<td>2.12</td>\r\n<td>350</td>\r\n<td>0.655</td>\r\n<td>1.53</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n* При нагревании от 19,6 до 22°C удлиненный объём увеличивается на 0,74%\r\n** При 327°С удлиненный объём увеличивается на 20%.\r\n\r\n<h2>ФИЗИКО-МЕХАНИЧЕСКИЕ СВОЙСТВА ФТОРОПЛАСТА-4</h2>\r\n<p>Основные показатели физико-механических свойств фторопласта-4 приведены ниже:</p>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td><strong>Разрушающее напряжение, кгс/см<sup>2</sup></strong></td>\r\n<td>Значения</td>\r\n</tr>\r\n<tr>\r\n<td>при растяжении:</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- незакаленный образец (кристалличность 05-08%)</td>\r\n<td>140-350*</td>\r\n</tr>\r\n<tr>\r\n<td>- закаленный образец (кристалличность 50%)</td>\r\n<td>160-315*</td>\r\n</tr>\r\n<tr>\r\n<td>при сжатии:</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- при 1%-ной деформации</td>\r\n<td>100</td>\r\n</tr>\r\n<tr>\r\n<td>- 10%-ной деформации</td>\r\n<td>185</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Сопротивлению изгибу (стрела прогиба 6 мм)</strong></td>\r\n<td>185</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Относительное удлинение при разрыт, %</strong></td>\r\n<td>250-500</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Остаточное удлинение, %</strong></td>\r\n<td>250-350</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Напряжение при 10%-ном удлинении, кгс/см<sup>2</sup></strong></td>\r\n<td>110-120</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Модуль упругости, кгс/см<sup>2</sup></strong></td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- при изгибе при 20°С</td>\r\n<td>4700-8500</td>\r\n</tr>\r\n<tr>\r\n<td>- сдвиге 2700</td>\r\n<td>2700</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Ударная вязкость, кгс·см/см<sup>2</sup></strong></td>\r\n<td>100 (не ломается)</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Ударное растяжение, кгс·см/см<sup>2</sup> (DIN 53448)</strong></td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- при 20°С</td>\r\n<td>650</td>\r\n</tr>\r\n<tr>\r\n<td>- 23°С</td>\r\n<td>680</td>\r\n</tr>\r\n<tr>\r\n<td>(удлинение при 20°С - 20%, при 23°С - 30%)</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Твердость:</strong></td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>по Бринеллю, кгс/мм<sup>2</sup></td>\r\n<td>3-4</td>\r\n</tr>\r\n<tr>\r\n<td>по Шору при 20°С</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- шкала С</td>\r\n<td>85-87</td>\r\n</tr>\r\n<tr>\r\n<td>- шкала D</td>\r\n<td>55-59</td>\r\n</tr>\r\n<tr>\r\n<td>Твердость по Роквеллу</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- шкала I</td>\r\n<td>80-95</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>В зависимости от того, как вырезан образец: поперек направления прессования-высокие значения, вдоль направления прессования-малые.</p>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td><strong>Показатели</strong></td>\r\n<td colspan="10"><strong>Температура, °С</strong></td>\r\n</tr>\r\n<tr>\r\n<td>-</td>\r\n<td>-60</td>\r\n<td>-40</td>\r\n<td>-20</td>\r\n<td>0</td>\r\n<td>20</td>\r\n<td>40</td>\r\n<td>60</td>\r\n<td>80</td>\r\n<td>100</td>\r\n<td>120</td>\r\n</tr>\r\n<tr>\r\n<td>Разрушающее напряжение при растяжении, кгс/см<sup>2</sup></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>- незакаленный образец</td>\r\n<td>-</td>\r\n<td>350</td>\r\n<td>325</td>\r\n<td>300</td>\r\n<td>200</td>\r\n<td>180</td>\r\n<td>-</td>\r\n<td>135</td>\r\n<td>115</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- закаленный образец</td>\r\n<td>-</td>\r\n<td>500</td>\r\n<td>440</td>\r\n<td>330</td>\r\n<td>250</td>\r\n<td>240</td>\r\n<td>-</td>\r\n<td>200</td>\r\n<td>190</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>Относительное удлинение при разрыве, %</td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>- незакаленный образец</td>\r\n<td>-</td>\r\n<td>70</td>\r\n<td>100</td>\r\n<td>150</td>\r\n<td>470</td>\r\n<td>650</td>\r\n<td>-</td>\r\n<td>600</td>\r\n<td>540</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- закаленный образец</td>\r\n<td>-</td>\r\n<td>100</td>\r\n<td>160</td>\r\n<td>190</td>\r\n<td>400</td>\r\n<td>500</td>\r\n<td>-</td>\r\n<td>500</td>\r\n<td>480</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>Модуль упругости, кгс/см<sup>2</sup></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>при сжатии</td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>- незакаленный образец</td>\r\n<td>18000</td>\r\n<td>17000</td>\r\n<td>15000</td>\r\n<td>11000</td>\r\n<td>7000</td>\r\n<td>4500</td>\r\n<td>3300</td>\r\n<td>2400</td>\r\n<td>1700</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>при сжатии</td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>- незакаленный образец</td>\r\n<td>27800</td>\r\n<td>23900</td>\r\n<td>23300</td>\r\n<td>18100</td>\r\n<td>8500</td>\r\n<td>5100</td>\r\n<td>4800</td>\r\n<td>3800</td>\r\n<td>-</td>\r\n<td>2450</td>\r\n</tr>\r\n<tr>\r\n<td>- закаленный образец</td>\r\n<td>13200</td>\r\n<td>11300</td>\r\n<td>9800</td>\r\n<td>7400</td>\r\n<td>4700</td>\r\n<td>4000</td>\r\n<td>2900</td>\r\n<td>2180</td>\r\n<td>-</td>\r\n<td>1100</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>Данные о зависимости физико-механических свойств фторопласта-4 от температуры приведены ниже.</p>\r\n\r\n<h2>Физико-механические свойства фторопласта-4 при низких температурах\r\n</h2>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td><strong>Показатели</strong></td>\r\n<td colspan="6"><strong>Температура, °С</strong></td>\r\n</tr>\r\n<tr>\r\n<td></td>\r\n<td>-93</td>\r\n<td>-123</td>\r\n<td>-153</td>\r\n<td>-193</td>\r\n<td>-223</td>\r\n<td>-269</td>\r\n</tr>\r\n<tr>\r\n<td>Разрушающее напряжение при сжатии *, кгс/см<sup>2</sup></td>\r\n<td>350</td>\r\n<td>-</td>\r\n<td>980</td>\r\n<td>1260</td>\r\n<td>1554</td>\r\n<td>1750-1960</td>\r\n</tr>\r\n<tr>\r\n<td>Модуль упругости при сжатии, кгс/см<sup>2</sup></td>\r\n<td>-</td>\r\n<td>52500</td>\r\n<td>-</td>\r\n<td>-</td>\r\n<td>-</td>\r\n<td>70000</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>* Разрушающее напряжение при сжатии равно напряжению, при котором деформация составляет 0,2%.</p>\r\n\r\n<h2>Зависимость деформации фторопласта-4 при сжатии от температуры:</h2>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td><strong>Деформация, %</strong></td>\r\n<td colspan="7"><strong>Нагрузка, вызывающая деформацию, кгс/см</strong><sup>2</sup></td>\r\n</tr>\r\n<tr>\r\n<td>-</td>\r\n<td>-50°С</td>\r\n<td> 0°С</td>\r\n<td> 25°С</td>\r\n<td>50°С</td>\r\n<td>100°С</td>\r\n<td>150°С</td>\r\n<td>200°С</td>\r\n</tr>\r\n<tr>\r\n<td>1</td>\r\n<td>203</td>\r\n<td>157</td>\r\n<td>62</td>\r\n<td>49</td>\r\n<td>31</td>\r\n<td>17,5</td>\r\n<td>11</td>\r\n</tr>\r\n<tr>\r\n<td>2</td>\r\n<td>304</td>\r\n<td>210</td>\r\n<td>92</td>\r\n<td>66</td>\r\n<td>39</td>\r\n<td>27</td>\r\n<td>20</td>\r\n</tr>\r\n<tr>\r\n<td>3</td>\r\n<td>350</td>\r\n<td>236</td>\r\n<td>105</td>\r\n<td>77</td>\r\n<td>48</td>\r\n<td>33</td>\r\n<td>27</td>\r\n</tr>\r\n<tr>\r\n<td>4</td>\r\n<td>374</td>\r\n<td>251</td>\r\n<td>120</td>\r\n<td>85</td>\r\n<td>59</td>\r\n<td>39</td>\r\n<td>31</td>\r\n</tr>\r\n<tr>\r\n<td>5</td>\r\n<td>390</td>\r\n<td>262</td>\r\n<td>127</td>\r\n<td>92</td>\r\n<td>62</td>\r\n<td>44</td>\r\n<td>35</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>Одним из важнейших прочностных показателей является предел текучести при растяжении, т.е. то напряжение, при котором возникают остаточные деформации. Он зависит от степени кристалличности, скорости растяжения и температуры. При степени кристалличности 65% и скорости растяжения 100 мм/мин зависимость предела текучести от абсолютной температуры Т (в К) описывается эмпирической формулой (справедливой от 20 до 300°С):\r\nlgσT= 0,53166+483,64/Т</p>\r\n<p>Ниже приведены значения пределов текучести для некоторых температур, рассчитанные по этой формуле:</p>\r\n\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tr>\r\n<td>Температура, °С</td><td>  25</td><td>50</td><td>75</td><td>100</td><td>150</td><td>200</td><td>250</td></tr>\r\n<tr><td>Предел текучести, кгс/см2</td><td>42,4</td><td>106,9</td><td>83,5</td><td>67,2</td><td>46,6</td><td>35,5</td><td>28,6</tr></table>\r\n\r\n<p>При длительном воздействии нагрузок остаточные деформации возникают при меньших напряжениях (40-50% от рассчитанных по формуле).</p><p>\r\nПри конструировании изделий из фторопласта-4 следует учитывать ползучесть. Ползучесть (деформация при длительном действии нагрузки) рассчитывается по формуле:<br>\r\nlgγt=lgγ1+a·lgt<br>\r\nгде γt - деформация за t сут; γ1 - деформация за 1 сут; а - коэффициент, зависящий в основном от температуры и в меньшей степени от нагрузки, если она не превышает 40-50% предела текучести.</p><p>\r\nЗначения коэффициента a и некоторые данные о ползучести для образцов со степенью кристалличности 50% приведены в таблице. Деформация за 1 сут (γ1) при других нагрузках и температурах определяется опытным путем. При степени кристалличности 65-68% ползучесть меньше.</p>\r\n\r\n<h2>   Ползучесть фторопласта-4</h2>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td><strong>Температура, °С</strong></td>\r\n<td><strong>Нагрузка, кгс/см<sup>2</sup></strong></td>\r\n<td colspan="2"><strong>Деформация, %</strong></td>\r\n<td><strong>Коэффициент а\r\n</strong></td>\r\n</tr>\r\n<tr>\r\n<td colspan="2">Сжатие</td>\r\n<td>1 сут (γ1)</td>\r\n<td>4 сут (γ4)</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>20</td>\r\n<td>33</td>\r\n<td>6,00</td>\r\n<td>6,25</td>\r\n<td>0,030</td>\r\n</tr>\r\n<tr>\r\n<td>20</td>\r\n<td>21</td>\r\n<td>3,05</td>\r\n<td>3,19</td>\r\n<td>0,032</td>\r\n</tr>\r\n<tr>\r\n<td colspan="2">Растяжение</td>\r\n<td>1 сут (γ1)</td>\r\n<td>4 сут (γ4)</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>40</td>\r\n<td>28</td>\r\n<td>2,72</td>\r\n<td>2,87</td>\r\n<td>0,038</td>\r\n</tr>\r\n<tr>\r\n<td>100</td>\r\n<td>28</td>\r\n<td>5,58</td>\r\n<td>5,90</td>\r\n<td>0,040</td>\r\n</tr>\r\n<tr>\r\n<td>140</td>\r\n<td>21</td>\r\n<td>4,67</td>\r\n<td>4,94</td>\r\n<td>0,042</td>\r\n</tr>\r\n<tr>\r\n<td>200</td>\r\n<td>14</td>\r\n<td>4,08</td>\r\n<td>4,50</td>\r\n<td>0,048</td>\r\n</tr>\r\n<tr>\r\n<td>250</td>\r\n<td>14</td>\r\n<td>5,17</td>\r\n<td>5,58</td>\r\n<td>0,055</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<h2>АНТИФРИКЦИОННЫЕ СВОЙСТВА ФТОРОПЛАСТА-4</h2>\r\nДанные о зависимости коэффициента трения от нагрузки [статической и динамической (при малых скоростях) коэффициенты трения фторопласта-4 по стали без смазки одинаковы] приведены ниже:\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Нагрузка, кгс/см2</td>\r\n<td>1</td>\r\n<td>3</td>\r\n<td>10</td>\r\n<td>20</td>\r\n</tr>\r\n<tr>\r\n<td>Коэффициент трения</td>\r\n<td>0,4</td>\r\n<td>0,1</td>\r\n<td>0,06</td>\r\n<td>0,05</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>При наличии смазки он примерно в 2 раза меньше.</p><p>\r\nДинамический коэффициент трения фторопласта-4 по стали без смазки при нагрузке ~ 20 кгс/см2 зависит от скорости скольжения:</p>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Скорость скольжения, см/c</td>\r\n<td>4</td>\r\n<td>8</td>\r\n<td>20</td>\r\n<td>40</td>\r\n<td>80</td>\r\n<td>160</td>\r\n</tr>\r\n<tr>\r\n<td>Динамический коэффициент трения</td>\r\n<td>0,05</td>\r\n<td>0,1</td>\r\n<td>0,15</td>\r\n<td>0,23</td>\r\n<td>0,24</td>\r\n<td>0,27</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>В присутствии наполнителя при малых скоростях скольжения коэффициент трения несколько выше, а при больших скоростях - ниже, чем коэффициент трения чистого фторопласта-4 по стали.</p><p>\r\nПри 327°С (на поверхности трения) коэффициент трения фторопласта-4 по стали резко возрастает (в несколько раз), что приводит к катастрофически быстрому износу и разрушению подшипника.<p>\r\n\r\n<h2>ТЕПЛОФИЗИЧЕСКИЕ СВОЙСТВА ФТОРОПЛАСТА-4</h2>\r\n<p>Неспеченный фторопласт-4 (в виде порошка) имеет степень кристалличности 95 - 98%, после спекания - от 50% (закаленный) до 68 - 70% (незакаленный). Ниже 19,6°С элементарная ячейка кристалла фторопласта-4 состоит из 13 групп CF2, выше 19,6°С - из 15 групп CF2. При 19,6°С триклиническая упаковка переходит в менее упорядоченную, гексагональную, что сопровождается увеличение объема кристаллитов на 0,0058 см3/г (1,2 объемн. %), или увеличением объема образца при степени кристалличности 68% на 0,74%. При наличии внешнего давления точка перехода понижается на 0,013°С на каждую атмосферу. При 30°С имеет место второй переход кристаллической структуры, но изменение объема составляет едва 1/10 часть изменения объема при 19,6°С. Под высоким давлением (4500 кгс/см2 при 70°С) возникает третий переход.</p><p>\r\nТемпература стеклования аморфных участков, определенная по температуре хрупкости, колеблется от -97 до -100°С, а по точке перегиба кривой зависимости модуля упругости составляет -120°С. Температура перехода аморфного твердого тела в переохлажденную жидкость равна 127°С.</p><p>\r\nПри 327°С кристаллиты фторопласта-4 плавятся, и он становится полностью аморфным, совершенно прозрачным (при отсутствии пористости), высокоэластичным, но не течет (вязкость выше 1011 П). Объем возрастает на 20%.\r\n</p><p>\r\nТочка плавления зависит от внешнего давления - на каждую атмосферу повышается на 0,154 °С. При остывании расплава ниже 327 °С образец мутнеет и становится непрозрачным - молочно-белым.   Скорость кристаллизации зависит от температуры (максимальная скорость при 310-315 °С), от продолжительности выдержки в расплавленном состоянии при 370-390 °С (чем больше время спекания, тем быстрее кристаллизуется образец) и от среднего молекулярного веса полимера (чем ниже молекулярный вес полимера, тем быстрее он кристаллизуется). На этом основан метод косвенной оценки молекулярного веса фторопласта-4: образец в виде диска толщиной 2 мм спекают при 370 °С в течение 13 ч и охлаждают от 370 до 250 °С в течение 5 ч. По плотности полученного образца при 23 °С можно оценить молекулярный вес: 2,16-2,19 г/см3-для высокомолекулярного полимера, 2,20-2,22 г/см3-для низкомолекулярного.\r\n</p><p>\r\n<h2>Ниже приведены некоторые теплофизические свойства фторопласта-4:</h2>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Теплостойкость по Вика (при нагрузке 5 кгс), °С</td>\r\n<td>110</td>\r\n</tr>\r\n<tr>\r\n<td>Удельная теплоемкость, ккал/(кг·°С)</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>при 0°С</td>\r\n<td>0,23</td>\r\n</tr>\r\n<tr>\r\n<td>при 50°С</td>\r\n<td>0,25</td>\r\n</tr>\r\n<tr>\r\n<td>Коэффициент теплопроводности, ккал/(м·ч·°С)</td>\r\n<td>0,20</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>Термический коэффициент линейного расширения зависит от температуры:</p>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Температура, °С</td>\r\n<td>от -60 до -10</td>\r\n<td>19,6</td>\r\n<td>30</td>\r\n<td>40</td>\r\n<td>200</td>\r\n<td>300</td>\r\n</tr>\r\n<tr>\r\n<td>Термический коэффициент линейного расширения α·105, 1/°С</td>\r\n<td>8</td>\r\n<td>54</td>\r\n<td>28</td>\r\n<td>11</td>\r\n<td>25</td>\r\n<td>64</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>На практике удобнее пользоваться средними значениями термического коэффициента линейного расширения для определенных интервалов температур. Следует также учитывать, что при нагревании изделий из фторопласта-4 в них часто возникают внутренние напряжения, вызывающие необратимое изменение размеров. Иногда вместо ожидаемого при нагревании удлинения образца он сокращается.</p><p>\r\nДанные, приведенные ниже, относятся к образцам, в которых полностью отсутствуют внутренние напряжения:</p>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Температура, °C</td>\r\n<td>Термический коэффициент линейного расширения α·105, 1/°C</td>\r\n<td>Изменение размеров изделия*, %</td>\r\n<td>Температура, °C</td>\r\n<td>Термический коэффициент линейного расширения α·105, 1/°C</td>\r\n<td>Изменение размеров изделия*, %</td>\r\n</tr>\r\n<tr>\r\n<td>от -193 до +25</td>\r\n<td>8,6</td>\r\n<td>-1,85</td>\r\n<td>от +25 до +100</td>\r\n<td>12,4</td>\r\n<td>+0,93</td>\r\n</tr>\r\n<tr>\r\n<td>от -150 до +25</td>\r\n<td>9,6</td>\r\n<td>-1,68</td>\r\n<td>от +25 до +150</td>\r\n<td>13,5</td>\r\n<td>+1,59</td>\r\n</tr>\r\n<tr>\r\n<td>от -100 до +25</td>\r\n<td>11,2</td>\r\n<td>-1,40</td>\r\n<td>от +25 до +200</td>\r\n<td>15,1</td>\r\n<td>+2,64</td>\r\n</tr>\r\n<tr>\r\n<td>от -50 до +25</td>\r\n<td>13,5</td>\r\n<td>-1,01</td>\r\n<td>от +25 до +250</td>\r\n<td>17,4</td>\r\n<td>+3,92</td>\r\n</tr>\r\n<tr>\r\n<td> от 0 до +25</td>\r\n<td>20,0</td>\r\n<td>-0,50</td>\r\n<td>от +25 до +300</td>\r\n<td>21,8</td>\r\n<td>+5,99</td>\r\n</tr>\r\n<tr>\r\n<td>от +25 до +50</td>\r\n<td>12,4</td>\r\n<td>+0,31</td>\r\n<td>от +25 до +300</td>\r\n<td>21,8</td>\r\n<td>+5,99</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>* От размера при 25°С.</p>\r\n\r\n<h2>ЭЛЕКТРИЧЕСКИЕ СВОЙТСВА ФТОРОПЛАСТА-4</h2>\r\n<p>Показатели электрических свойств фторопласта-4 приведены ниже:</p>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Удельное электрическое сопротивление:</td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>-поверхностное, Ом</td>\r\n<td>&gt;10<sup>17</sup></td>\r\n</tr>\r\n<tr>\r\n<td>-на воздухе со 100%-ной относительной влажностью</td>\r\n<td>&gt;10<sup>12</sup></td>\r\n</tr>\r\n<tr>\r\n<td>-объемное (до 150<sup>о</sup>С), Ом·см</td>\r\n<td>101<sup>7</sup> - 10<sup>20</sup></td>\r\n</tr>\r\n<tr>\r\n<td>-после длительного пребывания в воде не меняется</td>\r\n<td>1,9-2,2</td>\r\n</tr>\r\n<tr>\r\n<td>Диэлектрическая проницаемость (при 60 - 1010 Гц)</td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>Тангенс угла диэлектрических потерь (при 60 - 1010 Гц)</td>\r\n<td>&lt;1·10<sup>17</sup></td>\r\n</tr>\r\n<tr>\r\n<td>Электрическая прочность, кВ/мм:</td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>-при толщине образца 4 мм</td>\r\n<td>25-27</td>\r\n</tr>\r\n<tr>\r\n<td>-при толщине образца 0,1 - 0,3 мм</td>\r\n<td>40-80</td>\r\n</tr>\r\n<tr>\r\n<td>-при толщине образца 0,005 - 0,02 мм</td>\r\n<td>200-300</td>\r\n</tr>\r\n<tr>\r\n<td>Дугостойкость, с (сплошного токопроводящего слоя не образуется)</td>\r\n<td>250-700</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>Данные о зависимости тангенса угла диэлектрических потерь от частоты приведены ниже:</p>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Частота, Гц</td>\r\n<td>60</td>\r\n<td>10<sup>3</sup></td>\r\n<td>10<sup>4</sup></td>\r\n<td>10<sup>5</sup></td>\r\n<td>10<sup>6</sup></td>\r\n<td>10<sup>7</sup></td>\r\n</tr>\r\n<tr>\r\n<td>tgδ·10<sup>4</sup></td>\r\n<td>0,5</td>\r\n<td>0,3</td>\r\n<td>0,4</td>\r\n<td>0,7</td>\r\n<td>0,7</td>\r\n<td>0,7</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>Диэлектрическая проницаемость фторопласта-4 вплоть до 1010 Гц не зависит от частоты, а зависит от плотности: є= <u>1+0,238*d</u>\r\n2-0,119*d\r\nгде d - плотность при данной степени кристалличности и температуре.\r\nТангенс угла диэлектрических потерь остается постоянным при температуре от -60 до 250<sup>о</sup>С.\r\nПрогрев при 300<sup>о</sup>С в течение 6 месяцев не влияет на диэлектрические свойства фторопласта-4.<p>\r\n\r\n<h2>ХИМИЧЕСКИЕ И ДРУГИЕ СВОЙСТВА ФТОРОПЛАСТА-4</h2>\r\n<p>Фторопласт-4 является самым стойким из всех известных металлов - пластмасс, металлов, стекол, эмалей, сплавов и т.п. На него совершенно не действуют кислоты, окислители, щелочи, растворители. На фторопласт-4 действуют только расплавленные щелочные металлы и их комплексные соединения с аммиаком, нафталином, пиридином, а также трехфтористых хлор и элементный фтор при повышенных температурах. При температурах выше 327<sup>о</sup>С фторопласт набухает в жидких фторуглеродах, например в перфторкеросине. При 20<sup>о</sup>С фторопласт-4 слегка набухает (3 - 9%) в фторхлорсодержащих газах (фреонах).</p><p>\r\nВыше 350<sup>о</sup>С фторопласт-4 реагирует с щелочеземельными металлами и их соединениями (окислами и карбонатами), а также с окислами некоторых других металлов (свинца, кадмия, меди).</p><p>\r\nФторопласт-4 не смачивается водой при кратковременном погружении (угол смачивания 126<sup>о</sup>С), но смачивается при длительном пребывании в дистиллированной воде (15 - 20 суток). В соленой воде (например, морской) на поверхности фторопласта-4 через 15 - 20 суток отлагается пленка солей, смываемая дистиллированной водой.</p><p>\r\nВодопоглощение за 24 часа (и более продолжительное время) - ниже ошибки взвешивания (0,00%).</p><p>\r\nФторопласт-4 абсолютно стоек в тропических условиях и не подвижен действию грибков (но и не подавляет их развитие).</p><p>\r\nВлагопроницаемость при 20<sup>о</sup>С равна 3·10<sup>-9</sup> - 6·10<sup>-9</sup> г/(см·ч·мм рт. ст.); паропроницаемость при 20<sup>о</sup>С составляет 0,6·10<sup>-9</sup> - 1,2·10<sup>-9</sup> г/(см·ч·мм рт. ст.).</p><p>\r\nДанные о газопроницаемости пленки из фтороплавта-4 (при отсутствии пор) толщиной 0,1 мм при 20<sup>о</sup>С [в см<sup>3</sup>/(см·с·мм рт. ст.)] приведены ниже:</p>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Воздух</td>\r\n<td>1,1*10<sup>-9</sup></td>\r\n</tr>\r\n<tr>\r\n<td>Азот</td>\r\n<td>0,7*10<sup>-9</sup></td>\r\n</tr>\r\n<tr>\r\n<td>Кислород</td>\r\n<td>2,3*10<sup>-9</sup></td>\r\n</tr>\r\n<tr>\r\n<td>Водород</td>\r\n<td>6,3*10<sup>-9</sup></td>\r\n</tr>\r\n<tr>\r\n<td>Двуокись углерода</td>\r\n<td>4,8*10<sup>-9</sup></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>При наличии пористости проницаемость может увеличиваться до 1000 раз.</p><p>\r\nФторопласт-4 предназначен для видимого света только при малой толщине пленки:</p>\r\n<table class="responsive-table" width="100%">\r\n<tbody>\r\n<tr>\r\n<td width="95%"></td>\r\n</tr>\r\n</tbody>\r\n<tbody>\r\n<tr>\r\n<td>Толщина пленки, мм</td>\r\n<td>0,05</td>\r\n<td>0,10</td>\r\n<td>0,15</td>\r\n<td>1,00</td>\r\n</tr>\r\n<tr>\r\n<td>Пропускание, %</td>\r\n<td>88</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<table class="responsive-table" border="0" width="100%" cellspacing="0" cellpadding="0">\r\n<tbody>\r\n<tr>\r\n<td align="center" valign="middle" bgcolor="#FFFBFF" width="50%"></td>\r\n</tr>\r\n</tbody>\r\n</table>', 'Фторопласт - описание свойств от показателей', '', 'inherit', 'closed', 'closed', '', '2893-revision-v1', '', '', '2018-05-07 19:47:12', '2018-05-07 19:47:12', '', 2893, '<p>Фторопласт -4 - кристаллический полимер, температурой плавления кристаллитов 327°С и температурой стеклования аморфных участков от -100 до -120°С. Даже при температуре выше температуры разложения (415°С) фторопласт-4 не переходит в вязкотекучее состоян', 0, 'revision', '', 0);
INSERT INTO `fttwp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(3189, 1, '2018-05-07 20:45:39', '2018-05-07 20:45:39', '<div>Настоящие технические условия распространяются на детали из фторопласта (далее детали), изготовленные методом механической обработки фторопластовых заготовок.</div>\r\n<div>Заготовки изготавливаются из фторопласта-4, фторопласта-4 модифицированного, фторопласта-4А и из фторопластовых композиций Ф4К20, Ф4С15, Ф4К15М5.</div>\r\n<div>Детали (втулки, кольца, прокладки, манжеты, седла и др., далее - детали), применяются как уплотнительные, антифрикционные, электроизоляционные, химически стойкие элементы конструкций в различных отраслях промышленности, в том числе пищевых. Детали из фторопласта поставляются производственным предприятиям как комплектующие для изготовления частей, узлов оборудования, далее поставляемых ими на предприятия различных отраслей, в том числе: производство молочных продуктов, производство растительных и животных жиров. Фторопластовые изделия обладают высокой термостойкостью и абсолютной инертностью к пищевым средам.</div>\r\n<div>Материалом, используемым для изготовления деталей, контактирующих с пищевыми продуктами, является фторопласт-4 (марки «О» или «ПН»), изготовленный по ГОСТ 10007-80.</div>\r\n<div>Фторопластовые изделия имеют уникальные физические, химические, механические и электроизоляционные характеристики. Изделия из фторопластов не растворимы в воде, плохо растворимы или не растворимы в большинстве органических растворителей.</div>\r\n<div>Фторопластовые изделия обладают стойкостью ко всем минеральным и органическим кислотам, щелочам, органическим растворителям, газам и другим агрессивным средам. Разрушение материала наблюдается лишь при действии расплавленных щелочных металлов.</div>\r\n<div>Диапазон температуры эксплуатации деталей из:</div>\r\n<div>-   заготовок из фторопласта-4, фторопласта-4 модифицированного, фторопласта-4А -от минус 269° до плюс 250°С;</div>\r\n<div>-   заготовок из композиций Ф4К20, Ф4С15, Ф4К15М5от минус 60° до плюс 250°С.</div>\r\n<div>Технические условия устанавливают единые требования к деталям, изготовленным для внутреннего рынка и для экспорта.</div>\r\n<div>Условное обозначение детали при заказе должно содержать: наименование детали, обозначение чертежа, материал заготовки, обозначение настоящих технических условий.</div>\r\n<div>Перечень нормативных документов, на которые даны ссылки в настоящих ТУ, приведен в приложении А.</div>\r\n<div></div>\r\n<div>1 Технические требования</div>\r\n<div>1.1   Детали должны соответствовать требованиям настоящих технических условий, чертежам и изготавливаться по технологической документации, утвержденной в установленном порядке.</div>\r\n<div>1.2           Размеры деталей, чистота поверхности должны соответствовать чертежам, согласованным между заказчиком и изготовителем. Допускаются по согласованию с заказчиком отклонения от размеров чертежа.</div>\r\n<div>1.3                        Заготовки, предназначенные для изготовления деталей, не должны</div>\r\n<div>ТУ 2291-001-57919065-2010 С.3</div>\r\n<div></div>\r\n<div>иметь внутренних дефектов, трещин, раковин, снижающих эксплуатационные свойства деталей.</div>\r\n<div>1.4                        Специфические требования к деталям, работающим в особых условиях, оговариваются в договоре или указываются в чертеже.</div>\r\n<div>1.5           По показателям качества детали должны соответствовать требованиям и нормам, указанным в таблице 1.</div>\r\n<div>\r\n<table class="responsive-table" width="100%">\r\n<tbody>\r\n<tr>\r\n<td width="246">\r\n<div>Наименование</div>\r\n<div>показателей</div></td>\r\n<td width="302">\r\n<div>Норма</div></td>\r\n<td width="104">\r\n<div>Метод испытаний</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="246">\r\n<div>1. Внешний вид</div></td>\r\n<td valign="top" width="302">\r\n<div>На поверхности деталей не допускаются вмятины, сколы, царапины глубиной более 0,5 мм и длиной более 15 мм</div></td>\r\n<td width="104">\r\n<div>5.1</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="246">\r\n<div>2. Цвет изделий из:</div>\r\n<div>2.1 фторопласта - 4, 4А, Ф-4 модифицированного;</div>\r\n<div>2.2 фторопластовых композиций Ф4К20, Ф4С15, Ф4К15М5</div></td>\r\n<td valign="top" width="302">\r\n<div></div>\r\n<div>От белого до серого. Допускается разнотонность окраски, включения.</div>\r\n<div>От темно-серого до черного цвета. Допускается разнотонность окраски.</div></td>\r\n<td width="104">\r\n<div>5.1</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="246">\r\n<div>3. Состояние внутренних слоев деталей при проверке в проходящем свете изделий из Ф4, Ф4А</div></td>\r\n<td valign="top" width="302">\r\n<div>Детали не должны иметь внутренних дефектов, трещин, пустот.</div></td>\r\n<td width="104">\r\n<div>5.3</div></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n<div>Таблица 1</div>\r\n<div></div>\r\n<div>1.6                         По согласованию с потребителем допускаются отклонения по внешнему виду.</div>\r\n<div>1.7                         Маркировка</div>\r\n<div>1.7.1.     Содержание, способ и необходимость нанесения маркировки на деталях указывают в чертежах или оговаривают при заказе.</div>\r\n<div>1.7.2.   Транспортную маркировку проводят по ГОСТ 14192 с указанием:</div>\r\n<div>−    страны-изготовителя;</div>\r\n<div>−    наименования предприятия-изготовителя;</div>\r\n<div>−    наименование продукции, назначение;</div>\r\n<div>−    номера партии;</div>\r\n<div>−    масса брутто и нетто;</div>\r\n<div>−    даты изготовления;</div>\r\n<div>−    штамп ОТК.</div>\r\n<div>1.8       Упаковка</div>\r\n<div>1.8.1    Детали упаковывают в ящики деревянные по ГОСТ 18573.</div>\r\n<div>Допускаются другие виды упаковки деталей, обеспечивающей сохранность изделий при хранении и транспортировке.</div>\r\n<div>1.8.2            По согласованию с заказчиком допускается упаковывать в один ящик разные детали.</div>\r\n<div>1.8.3            Упаковка деталей, поставляемых в районы Крайнего Севера и труднодоступные районы, должна отвечать требованиям ГОСТ 15846 и п.1.8. настоящих технических условий и оговариваться при заключении договора на поставку.</div>\r\n<div>ТУ 2291-001-57919065-2010 С.4</div>\r\n<div></div>\r\n<div>Деревянные ящики должны быть выстланы с внутренней стороны водонепроницаемым материалом.</div>\r\n<div>1.8.4   Детали, предназначенные на экспорт, упаковывают в деревянные ящики тип II-1 или III -1 по ГОСТ 2991, отвечающие требованиям ГОСТ 24634, и оговариваются при заключении договора на поставку.</div>\r\n<div></div>\r\n<div>2 Требования безопасности</div>\r\n<div></div>\r\n<div>2.1   Детали, полученные путем механической обработки заготовок из фторопласта-4, 4А, фторопласта-4 модифицированного и фторопластовых композиций при комнатной температуре невзрывоопасны, негорючи и не оказывают вредного влияния на организм человека при непосредственном контакте.</div>\r\n<div>2.2            Класс опасности по ГОСТ 12.1. 007-76 - четвертый (вещества малоопасные). Детали из фторопластовых заготовок не оказывают раздражающего действия на кожные покровы и слизистые оболочки глаз при однократном и повторных воздействиях.</div>\r\n<div>Летучие компоненты, выделяющиеся из материала, не оказывают выраженного раздражающего действия на слизистые оболочки глаз и верхних дыхательных путей.</div>\r\n<div>При изготовлении, применении и нагревании свыше +260°С в воздух рабочей зоны выделяются химические вещества: пыль стекловолокна - ПДК -   -/4 мг/м<sup>3</sup>; молибден, нерастворимые соединения - ПДК - 6/1 мг/м<sup>3</sup>; пыль кокса - ПДК - -/6 мг/м<sup>3</sup>; тетрафторэтилен - ПДК - 30 мг/м<sup>3</sup>; фтористый водород (по фтор-иону) - ПДК - 0,5/0,1 мг/м<sup>3</sup>; оксид углерода - ПДК - 20 мг/м<sup>3</sup>; аэрозоль фторопласта - ПДК - 10 мг/м<sup>3</sup>. Предельно допустимые концентрации веществ установлены гигиеническими нормативами ГН2.2.5.1313-03.</div>\r\n<div>2.3 Детали нетоксичны, индекс токсичности 99,8%, при норме 70&lt;It&lt;120.</div>\r\n<div>2.4 Детали, изготовленные из фторопластовых заготовок, предназначенные для контакта с пищевыми средами, не должны отдавать в контактирующие с ними модельные растворы и воздушную среду вещества в количествах, вредных для здоровья человека, превышающих допустимые количества миграции, а также соединения, способные вызвать канцерогенный, мутагенный и другие отдаленные эффекты.</div>\r\n<div>Уровни миграции химических веществ из деталей в модельные среды не превышают допустимые, а именно: формальдегида - не более 0,1 мг/л, фтор-иона (суммарно) - не более 0,5 мг/л, гексана - не более 0,1 мг/л, гептана - не более 0,1 мг/л.</div>\r\n<div>Уровни выделения химических веществ из деталей при насыщении 0,1 м<sup>2</sup>/м<sup>3</sup> не превышают допустимые, а именно: формальдегида - не более 0,003 мг/м<sup>3</sup>, углеводородов/по гексану/ - не более 60 мг/м<sup>3</sup>.</div>\r\n<div>Предельно допустимые количества химических веществ, выделяющихся из материалов, контактирующих с пищевыми продуктами, установлены гигиеническими нормативами ГН 2.3.3.972-00.</div>\r\n<div></div>\r\n<div></div>\r\n<div>ТУ 2291-001-57919065-2010 С.5</div>\r\n<div></div>\r\n<div>2.5 При работе с заготовками из фторопласта возможно скопление зарядов статического электричества. В соответствии с правилами защиты от статического электричества оборудование должно быть заземлено и относительная влажность в рабочих помещениях должна быть не менее 50% в соответствии с ГОСТ 10007-80.</div>\r\n<div>2.6            Производственные помещения должны быть оборудованы приточно-вытяжной <b>и</b> местной вентиляцией, обеспечивающей содержание токсичных веществ в воздухе рабочей зоны в пределах допустимых концентраций по ГОСТ 12.1.005-88. Кратность воздухообмена - 8.</div>\r\n<div>2.7            В помещении, в котором производится работа с заготовками, включение открытых нагревательных приборов (электроплиток) и приборов с температурой поверхности нагрева выше 260°С, разрешается только в вытяжных шкафах при включенной вентиляции.</div>\r\n<div>В производственных помещениях курение не допускается.</div>\r\n<div>2.8       Средства пожаротушения: вода, пена, песок.</div>\r\n<div>2.9                Средства индивидуальной защиты: специальная одежда, обувь, средства защиты органов дыхания, глаз, выдаются работающим при работе с заготовками из фторопласта и фторопластовых композиций в соответствии с «Правилами обеспечения работников специальной одеждой, обувью и другими средствами индивидуальной защиты», утвержденными Постановлением Минтруда и социального развития РФ от 18 декабря 1998 г. №51 и статьи 221 Трудового кодекса РФ от 30.06.2006 №90-ФЗ.</div>\r\n<div>2.10       К работе допускаются лица не моложе 18 лет, прошедшие медицинский осмотр, инструктаж по охране труда, обучение безопасным методам работы и прошедшие проверку знаний в комиссии предприятия на право допуска к самостоятельной работе. Предварительные и периодические медицинские осмотры (обследования) работников проводятся в соответствии с приказом Минздрава РФ № 83 от 16.08.2004 г. и №90 от 14.03.1996 г.</div>\r\n<div></div>\r\n<div><b>3      </b> <b>Требования по охране окружающей среды</b></div>\r\n<div></div>\r\n<div>3.1                          Охрана окружающей среды осуществляется в соответствии с Федеральным законом «Об охране окружающей среды №7-ФЗ от 10.01.2002 г.».</div>\r\n<div>Контроль за выбросами в атмосферный воздух проводится в соответствии с ГОСТ 17.2.3.02.</div>\r\n<div>3.2            Сточные воды в процессе переработки фторопластовых материалов не образуются.</div>\r\n<div>3.3                          Работа по обращению с отходами производства на предприятии проводится согласно Федеральному закону РФ № 89-ФЗ от 24.06.1998 «Об отходах производства и потребления». Размещение и обезвреживание отходов осуществляется в соответствии с СанПин 2.1.7.1322-03.</div>\r\n<div><b>4      </b> <b>Правила приемки</b></div>\r\n<div></div>\r\n<div>4.1                          Детали принимают партиями. Партией считают детали одного типоразмера, изготовленные из заготовок одной марки, сопровождаемые одним документом о качестве.</div>\r\n<div>4.2            Документы о качестве должны содержать:</div>\r\n<div></div>\r\n<div>-         страну-изготовитель;</div>\r\n<div>ТУ 2291-001-57919065-2010 С.6</div>\r\n<div></div>\r\n<div>-         наименование предприятия-изготовителя;</div>\r\n<div>-         наименование детали;</div>\r\n<div>-         материал детали;</div>\r\n<div>-         номер партии;</div>\r\n<div>-         обозначение настоящих технических условий;</div>\r\n<div>-         массу партии деталей, кг;</div>\r\n<div>-         дату изготовления;</div>\r\n<div>-         штамп ОТК.</div>\r\n<div>4.3   Для проверки соответствия качества изделий из фторопластовых заготовок требованиям настоящих ТУ каждую партию подвергают приемо-сдаточным испытаниям. При приемо-сдаточных испытаниях проводят контроль внешнего вида изделий, размеров, маркировки (при наличии), состояние внутренних слоев. Гигиенические показатели определяются один раз в год.</div>\r\n<div>4.4 Проверку размеров производят выборочно на 10% изделий от партии.</div>\r\n<div>4.5 Внешний вид изделий и состояние внутренних слоёв (для Ф4 и Ф4А) при проверке в проходящем свете определяют на 100% изделий.</div>\r\n<div>4.6 Маркировку определяют выборочно на 2% изделий от партии.</div>\r\n<div>4.7 В случае отклонения размеров от требований настоящих ТУ производят проверку по этому показателю на 100% изделий.</div>\r\n<div>5 Методы контроля</div>\r\n<div></div>\r\n<div>5.1                Внешний вид, цвет деталей проверяют визуально без применения увеличительных приборов.</div>\r\n<div>5.2                Контроль размеров деталей по п. 1.2. настоящих технических условий проводят универсальными измерительными инструментами, обеспечивающими точность измерения в соответствии с чертежом на конкретную деталь.</div>\r\n<div>5.3                Предельно допустимые количества химических веществ, выделяющихся из материалов, контактирующих с пищевыми продуктами, определяются согласно требованиям гигиенических нормативов ГН 2.3.3.972-00 по следующим методикам:</div>\r\n<div>\r\n<pre>- Инструкция N 880-71;\r\n\r\n</pre>\r\n</div>\r\n<div>\r\n<pre>- РД 52.04.186-89;\r\n\r\n</pre>\r\n</div>\r\n<div>\r\n<pre>- ПНД Ф 14.1:2:4.84-96;\r\n\r\n</pre>\r\n</div>\r\n<div>\r\n<pre>- ГОСТ 24295-80;\r\n\r\n</pre>\r\n</div>\r\n<div>\r\n<pre>- МР № 01.024-07.\r\n\r\n</pre>\r\n</div>\r\n<div>5.4                Определение состояния внутренних слоев деталей в проходящем свете.</div>\r\n<div>5.4.1   Приборы, материалы</div>\r\n<div>Лампа электрическая мощностью 100 Вт или ламповый дефектоскоп.</div>\r\n<div>Допускается применение лампы другой мощности, обеспечивающей достаточный контроль.</div>\r\n<div>Спирт этиловый по ТУ 2421-033-00479095.</div>\r\n<div>Ткань по ГОСТ 29298-92 или марля по ГОСТ 11109.</div>\r\n<div>5.4.2   Проведение испытания</div>\r\n<div>Детали из фторопласта-4 и фторопласта-4А с загрязненной поверхностью непосредственно перед проведением испытаний протирают</div>\r\n<div></div>\r\n<div>ТУ 2291-001-57919065-2010 С.7</div>\r\n<div></div>\r\n<div>чистой тканью или марлей, смоченной спиртом.</div>\r\n<div>Детали осматривают невооруженным глазом в проходящем свете, создаваемом лампой или с помощью лампового дефектоскопа. Детали располагают по отношению к источнику света по следующей схеме (рис. 1).</div>\r\n<div>Включения во внутренних слоях детали характеризуется как явно различимые на белом фоне точки темного цвета.</div>\r\n<div>Окрашенные частицы внутри деталей характеризуются как слабо различимые в проходящем свете небольшие (точечные) пятна (ореолы) от светло-желтого до светло-коричневого цвета.</div>\r\n<div>Разнотонность окраски определяют в проходящем свете путем сравнения с контрольным образцом.</div>\r\n&nbsp;\r\n<div>ТУ 2291-001-57919065-2010 С.8</div>\r\n<div>ТУ 2291-001-57919065-2010 С.9</div>\r\n<div>6 Транспортирование и хранение</div>\r\n<div></div>\r\n<div>6.1   Упакованные детали транспортируются всеми видами транспорта в крытых транспортных средствах в соответствии с правилами перевозки грузов, действующими на данном виде транспорта.</div>\r\n<div>6.2  Изделия в упакованном виде должны храниться в закрытых складских помещениях в условиях, обеспечивающих их сохранность.</div>\r\n<div>7 Гарантии изготовителя</div>\r\n<div></div>\r\n<div>7.1                         Изготовитель гарантирует соответствие качества деталей требованиям чертежей и настоящих технических условий при соблюдении условий упаковки, транспортирования и хранения.</div>\r\n<div>7.2                         Гарантийный срок хранения деталей 10 лет со дня изготовления.</div>\r\n&nbsp;\r\n<div>ТУ 2291-001-57919065-2010 С.10</div>\r\n<div></div>\r\n<div>Приложение А</div>\r\n<div>(справочное)</div>\r\n<div></div>\r\n<div>Перечень нормативных документов, на которые даны ссылки в настоящих технических условиях</div>\r\n<div></div>\r\n<div>\r\n<table class="responsive-table" width="100%">\r\n<tbody>\r\n<tr>\r\n<td width="600">\r\n<div>Обозначение и наименование документа</div></td>\r\n<td width="85">\r\n<div>Номер пункта</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="600">\r\n<div>ГОСТ 12.4.011-89 ССБТ Средства защиты работающих. Общие</div>\r\n<div>требования и классификация</div></td>\r\n<td width="85">\r\n<div>2.8</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="600">\r\n<div>ГОСТ 17.2.3.01-86. Охрана природы: Атмосфера. Правила контроля качества воздуха населенных пунктов.</div>\r\n<div>ГОСТ 17.2.3.02-78. Охрана природы. Атмосфера. Правила установления допустимых выбросов вредных веществ промышленности предприятиями</div></td>\r\n<td width="85">\r\n<div>3.1</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="600">\r\n<div>ГОСТ 2991-85 Ящики дощатые неразборные для грузов массой до 500 кг ОТУ</div></td>\r\n<td width="85">\r\n<div>1.7.4</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="600">\r\n<div>ГОСТ 11109-90 Марля бытовая хлопчатобумажная ОТУ</div></td>\r\n<td width="85">\r\n<div>5.3.1</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="600">\r\n<div>ГОСТ 15846-79 Продукция, отправляемая в районы Крайнего Севера и труднодоступные районы. Упаковка, маркировка, транспортирование и хранение</div></td>\r\n<td width="85">\r\n<div>1.7.3</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="600">\r\n<div>ГОСТ 14192-96 Маркировка грузов</div></td>\r\n<td width="85">\r\n<div>1.6.2</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="600">\r\n<div>ГОСТ 18573-86 Ящики деревянные для продукции химической промышленности. ТУ</div></td>\r\n<td width="85">\r\n<div>1.7.1</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="600">\r\n<div>ГОСТ 24634-81.Э Ящики деревянные для продукции, поставляемой для экспорта ОТУ</div></td>\r\n<td width="85">\r\n<div>1.7.4</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="600">\r\n<div>ГОСТ 29298-92 Ткани хлопчатобумажные и смешанные бытовые. ОТУ</div></td>\r\n<td width="85">\r\n<div>5.3.1</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="600">\r\n<div>ТУ 2421-033-00479095-2000. Спирт этиловый синтетический ректификованный технический</div></td>\r\n<td width="85">\r\n<div>5.3.1</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="600">\r\n<div>ГОСТ 24634-81.Э Ящики деревянные для продукции, поставляемой для экспорта ОТУ</div></td>\r\n<td width="85">\r\n<div>1.8.4</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="600">\r\n<div><strong>ГН 2.3.3.972-00 Гигиена питания. Тара, посуда, упаковка, оборудование и другие виды продукции, контактирующие с пищевыми продуктами. Предельно допустимые количества химических веществ, выделяющихся из материалов, контактирующих с пищевыми продуктами</strong></div></td>\r\n<td width="85">\r\n<div>2.4</div>\r\n<div>5.3</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="600">\r\n<div>Инструкция N 880-71. Инструкция по санитарно-химическому исследованию изделий, изготовленных из полимерных и других синтетических материалов, предназначенных для  контакта с пищевыми продуктами</div></td>\r\n<td width="85">\r\n<div>5.3</div></td>\r\n</tr>\r\n<tr>\r\n<td width="600">\r\n<h1>РД 52.04.186-89. Руководство по контролю загрязнения атмосферы</h1>\r\n</td>\r\n<td width="85">\r\n<div>5.3</div></td>\r\n</tr>\r\n<tr>\r\n<td width="600">\r\n<h1>ПНД Ф 14.1:2:4.84-96. Количественный химический анализ вод. Методика выполнения измерений массовой концентрации формальдегида в пробах питьевых, природных и сточных вод фотометрическим методом</h1>\r\n</td>\r\n<td width="85">\r\n<div>5.3</div></td>\r\n</tr>\r\n<tr>\r\n<td width="600">\r\n<h1>ГОСТ 24295-80. Посуда хозяйственная стальная эмалированная. Методы анализа вытяжек</h1>\r\n</td>\r\n<td width="85">\r\n<div>5.3</div></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n<div></div>\r\n<div></div>\r\n<div>ТУ 2291-001-57919065-2010 С.11</div>\r\n<div></div>\r\n<div>\r\n<table class="responsive-table" width="100%">\r\n<tbody>\r\n<tr>\r\n<td width="600">\r\n<div>Обозначение и наименование документа</div></td>\r\n<td width="85">\r\n<div>Номер пункта</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="600">\r\n<div>МР № 01.024-07. " Газохроматографическое определение гексана, гептана, ацетальдегида, ацетона, метилацетата, этилацетата, метанола, изо-пропанола, акрилонитрола, н-пропанола, н-пропилацетата, бутилацетата, изо-бутанола, н-бутанола, бензола, толуола, этилбензола, м-, о-, n-ксилолов, изопропилбензола, стирола, альфа-метилстирола в водных вытяжках из материалов различного состава."</div></td>\r\n<td width="85">\r\n<div>5.3</div></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n<div></div>\r\n<div>Правила перевозки грузов и Устав железных дорог РФ, МПС, М., изд. «Транспорт», 1983 г.</div>\r\n<div>Правила перевозки грузов автомобильным транспортом, М., изд. «Транспорт», 1983 г. •</div>\r\n<div>Руководство по грузовым перевозкам на внутренних воздушных линиях РФ, МГА, РИО «Гражданская авиация», 1984 г.</div>\r\n<div>Правила безопасности, морской перевозки генеральных грузов, Минморфлот, М., ЦРН «Морфлот», 1988 г.</div>\r\n&nbsp;\r\n<div>ТУ 2291-001-57919065-2010 С.12</div>\r\n<div></div>\r\n<div>ЛИСТ РЕГИСТРАЦИИ ИЗМЕНЕНИЙ</div>\r\n<div></div>\r\n<div>\r\n<div></div>\r\n<div></div>\r\n<div></div>\r\n<div></div>\r\n<div></div>\r\n<table class="responsive-table" width="100%">\r\n<tbody>\r\n<tr>\r\n<td rowspan="2" width="66">\r\n<div>Изм.</div></td>\r\n<td colspan="4" width="262">\r\n<div>Номера листов (страниц)</div></td>\r\n<td rowspan="2" width="76">\r\n<div>Всего</div>\r\n<div>листов (страниц)</div>\r\n<div>в докум.</div></td>\r\n<td rowspan="2" width="54">\r\n<div>№ докум.</div></td>\r\n<td rowspan="2" width="81">\r\n<div>Входящий № сопроводит. документа    и дата</div></td>\r\n<td rowspan="2" width="54">\r\n<div>Подпись</div></td>\r\n<td rowspan="2" width="68">\r\n<div>Дата</div></td>\r\n</tr>\r\n<tr>\r\n<td width="67">\r\n<div>Изменен-ных</div></td>\r\n<td width="75">\r\n<div>Замененных</div></td>\r\n<td width="45">\r\n<div>Новых</div></td>\r\n<td width="76">\r\n<div>Аннулиро-ванных</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="66">\r\n<div></div></td>\r\n<td valign="top" width="67">\r\n<div></div></td>\r\n<td valign="top" width="75">\r\n<div></div></td>\r\n<td valign="top" width="45">\r\n<div></div></td>\r\n<td valign="top" width="76">\r\n<div></div></td>\r\n<td width="76">\r\n<div></div></td>\r\n<td width="54">\r\n<div></div></td>\r\n<td width="81">\r\n<div></div></td>\r\n<td valign="top" width="54">\r\n<div></div></td>\r\n<td valign="top" width="68">\r\n<div></div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="66">\r\n<div></div></td>\r\n<td valign="top" width="67">\r\n<div></div></td>\r\n<td valign="top" width="75">\r\n<div></div></td>\r\n<td valign="top" width="45">\r\n<div></div></td>\r\n<td valign="top" width="76">\r\n<div></div></td>\r\n<td width="76">\r\n<div></div></td>\r\n<td width="54">\r\n<div></div></td>\r\n<td width="81">\r\n<div></div></td>\r\n<td valign="top" width="54">\r\n<div></div></td>\r\n<td valign="top" width="68">\r\n<div></div></td>\r\n</tr>\r\n<tr>\r