\n<td valign="top">\r\n<div>600</div></td>\r\n</tr>\r\n<tr>\r\n<td colspan="5" valign="top">\r\n<div>Разное</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top">\r\n<div>Цвет</div></td>\r\n<td valign="top">\r\n<div>Натуральный/черный/другие</div></td>\r\n<td valign="top">\r\n<div>Черный</div></td>\r\n<td valign="top">\r\n<div>Темно-серый</div></td>\r\n<td valign="top">\r\n<div>Синий</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top">\r\n<div>Плотность</div></td>\r\n<td valign="top">\r\n<div>1,145</div></td>\r\n<td valign="top">\r\n<div>1,15</div></td>\r\n<td valign="top">\r\n<div>1.15</div></td>\r\n<td valign="top">\r\n<div>1,15</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top">\r\n<div>Сопротивление износу, мг/Км</div></td>\r\n<td valign="top">\r\n<div>0,44</div></td>\r\n<td valign="top">\r\n<div>0,11</div></td>\r\n<td valign="top">\r\n<div>0.23</div></td>\r\n<td valign="top">\r\n<div>0,41</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top">\r\n<div>Коэффициент трения</div></td>\r\n<td valign="top">\r\n<div>0,39</div></td>\r\n<td valign="top">\r\n<div>0,15</div></td>\r\n<td valign="top">\r\n<div>0.25</div></td>\r\n<td valign="top">\r\n<div>0,39</div></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\nсм. <a title="Полиамид-6" href="http://www.ftoroplastmsk.ru/interesnyestati/poliamid.jdx" target="_blank" rel="noopener">полиамид</a>', 'Свойства капролона', '', 'inherit', 'closed', 'closed', '', '2962-revision-v1', '', '', '2018-06-13 19:36:59', '2018-06-13 19:36:59', '', 2962, '<h2>Модификации КАПРОЛОНА ПА-6:</h2>\r\n<strong title="Капролон - Полиамид ПА-6">КАПРОЛОН</strong> МАСЛОНАПОЛНЕННЫЙ - самосмазывающийся материал. Коэффициент трения в 2,5-3 раза ниже, чем у капролона; абразивный износ - в 4- 5 раз меньше (подшипники скольже', 0, 'revision', '', 0);
