\r\n<td valign="top">\r\n<div title="тепловой коэффциент линейного расширения изделий из капролона - полиамида 6">Тепловой коэффициент линейного расширения</div></td>\r\n<td valign="top">\r\n<div>8*(10)</div></td>\r\n<td valign="top">\r\n<div>5-8</div></td>\r\n<td valign="top">\r\n<div>5-8</div></td>\r\n<td valign="top">\r\n<div>5-8</div></td>\r\n</tr>\r\n<tr>\r\n<td colspan="5" valign="top">\r\n<div title="Электрические свойства изделий из капролона - полиамида 6">Электрические</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top">\r\n<div title="Диэлектрическая проницаемость капролона - полиамида 6">Диэлектрическая проницаемость</div></td>\r\n<td valign="top">\r\n<div>3,7</div></td>\r\n<td valign="top">\r\n<div>3,7</div></td>\r\n<td valign="top">\r\n<div>3.7</div></td>\r\n<td valign="top">\r\n<div>3,7</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top">\r\n<div title="Диэлектрическая прочность капролона - полиамида">Диэлектрическая прочность, КВ/мм</div></td>\r\n<td valign="top">\r\n<div>25</div></td>\r\n<td valign="top">\r\n<div>&gt;25</div></td>\r\n<td valign="top">\r\n<div>&gt;25</div></td>\r\n<td valign="top">\r\n<div>&gt;25</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top">\r\n<div title="Удельное объемное сопротивление капролона - полиамида">Удельное объемное сопротивление, Ом см</div></td>\r\n<td valign="top">\r\n<div>1*(10)</div></td>\r\n<td valign="top">\r\n<div>1*(10)</div></td>\r\n<td valign="top">\r\n<div>1*(10)</div></td>\r\n<td valign="top">\r\n<div>1*(10)</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top">\r\n<div>Поверхностное удельное сопротивление, Ом</div></td>\r\n<td valign="top">\r\n<div>1*(10)</div></td>\r\n<td valign="top">\r\n<div>1*(10)</div></td>\r\n<td valign="top">\r\n<div>1*(10)</div></td>\r\n<td valign="top">\r\n<div>1*(10)</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top">\r\n<div>Сопротивление трекинга, CTI</div></td>\r\n<td valign="top">\r\n<div>600</div></td>\r\n<td valign="top">\r\n<div>600</div></td>\r\n<td valign="top">\r\n<div>600</div></td>\r\n<td valign="top">\r\n<div>600</div></td>\r\n</tr>\r\n<tr>\r\n<td colspan="5" valign="top">\r\n<div>Разное</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top">\r\n<div>Цвет</div></td>\r\n<td valign="top">\r\n<div>Натуральный/черный/другие</div></td>\r\n<td valign="top">\r\n<div>Черный</div></td>\r\n<td valign="top">\r\n<div>Темно-серый</div></td>\r\n<td valign="top">\r\n<div>Синий</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top">\r\n<div>Плотность</div></td>\r\n<td valign="top">\r\n<div>1,145</div></td>\r\n<td valign="top">\r\n<div>1,15</div></td>\r\n<td valign="top">\r\n<div>1.15</div></td>\r\n<td valign="top">\r\n<div>1,15</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top">\r\n<div>Сопротивление износу, мг/Км</div></td>\r\n<td valign="top">\r\n<div>0,44</div></td>\r\n<td valign="top">\r\n<div>0,11</div></td>\r\n<td valign="top">\r\n<div>0.23</div></td>\r\n<td valign="top">\r\n<div>0,41</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top">\r\n<div>Коэффициент трения</div></td>\r\n<td valign="top">\r\n<div>0,39</div></td>\r\n<td valign="top">\r\n<div>0,15</div></td>\r\n<td valign="top">\r\n<div>0.25</div></td>\r\n<td valign="top">\r\n<div>0,39</div></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\nсм. <a title="Полиамид-6" href="http://www.ftoroplastmsk.ru/interesnyestati/poliamid.jdx" target="_blank" rel="noopener">полиамид</a>', 'Свойства капролона', '', 'inherit', 'closed', 'closed', '', '2962-revision-v1', '', '', '2018-06-13 19:37:21', '2018-06-13 19:37:21', '', 2962, '<h2>Модификации КАПРОЛОНА ПА-6:</h2>\r\n<strong title="Капролон - Полиамид ПА-6">КАПРОЛОН МАСЛОНАПОЛНЕННЫЙ</strong> - самосмазывающийся материал. Коэффициент трения в 2,5-3 раза ниже, чем у капролона; абразивный износ - в 4- 5 раз меньше (подшипники скольже', 0, 'revision', '', 0);
INSERT INTO `fttwp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(3709, 1, '2018-06-13 19:46:12', '2018-06-13 19:46:12', '<p>Фторопласт -4 - кристаллический полимер, температурой плавления кристаллитов 327°С и температурой стеклования аморфных участков от -100 до -120°С. Даже при температуре выше температуры разложения (415°С) фторопласт-4 не переходит в вязкотекучее состояние (при 370°С вязкость его расплава равна ≈10<sup>11</sup>П, т.е. в 1000000 раз больше вязкости, (необходимой для литья под давлением), поэтому переработка его возможна только методом спекания отпрессованных таблеток.\r\n</p><p>\r\nВ зависимости от скорости охлаждения (до температуры ниже 250°С) после спекания можно получить закаленные изделия со степенью кристалличности ≈50% и плотностью ≈2,15 г/см<sup>3</sup> или незакаленные со степенью кристалличности более 65% плотностью выше 2,20 г/см3.При температуре эксплуатации и от -269°С до +260°С степень кристалличности, достигнутая при данном режиме охлаждения, не меняется, при температуре выше 260°С степень кристалличности постепенно увеличивается, особенно быстро она вырастает при 310 - 315°С.</p>\r\n<div>\r\n\r\n\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td><strong>Степень кристалличности, %</strong></td>\r\n<td><strong>Плотность при\r\n23°С, г/см<sup>3</sup></strong></td>\r\n<td><strong>Степень кристалличности, %</strong></td>\r\n<td><strong>Плотность при\r\n23°С, г/см<sup>3</sup></strong></td>\r\n</tr>\r\n<tr>\r\n<td>40.0</td>\r\n<td>2.12</td>\r\n<td>69.4</td>\r\n<td>2.21</td>\r\n</tr>\r\n<tr>\r\n<td>43.2</td>\r\n<td>2.13</td>\r\n<td>72.8</td>\r\n<td>2.22</td>\r\n</tr>\r\n<tr>\r\n<td>46.5</td>\r\n<td>2.14</td>\r\n<td>75.2</td>\r\n<td>2.23</td>\r\n</tr>\r\n<tr>\r\n<td>49.7</td>\r\n<td>2.15</td>\r\n<td>78.0</td>\r\n<td>2.24</td>\r\n</tr>\r\n<tr>\r\n<td>53.0</td>\r\n<td>2.16</td>\r\n<td>80.7</td>\r\n<td>2.25</td>\r\n</tr>\r\n<tr>\r\n<td>56.3</td>\r\n<td>2.17</td>\r\n<td>82.6</td>\r\n<td>2.26</td>\r\n</tr>\r\n<tr>\r\n<td>59.7</td>\r\n<td>2.18</td>\r\n<td>85.2</td>\r\n<td>2.27</td>\r\n</tr>\r\n<tr>\r\n<td>63.1</td>\r\n<td>2.19</td>\r\n<td>89.0</td>\r\n<td>2.28</td>\r\n</tr>\r\n<tr>\r\n<td>66.5</td>\r\n<td>2.20</td>\r\n<td>-</td>\r\n<td>-</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>Об отсутствии же пористости свидетельствует полная прозрачность образца во время спекания при 370-390°С. Даже незначительная пористость вызывает мутность образца. Пористость, равная примерно 0,1-0,2%, заметно влияет на точность определения плотности.\r\n</p><p>Данные о зависимости удельного объема и плотности от температуры для образца со степенью кристалличности 68% (плотность медленно охлажденного изделия) приведены ниже:</p>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td><strong>Температура, °С</strong></td>\r\n<td><strong>Удельный объем, см<sup>3</sup>/г</strong></td>\r\n<td><strong>Плотность, г/см<sup>3</sup></strong></td>\r\n<td><strong>Температура, °С</strong></td>\r\n<td><strong>Удельный объем, cм<sup>3</sup>/г</strong></td>\r\n<td><strong>Плотность, г/см<sup>3</sup></strong></td>\r\n</tr>\r\n<tr>\r\n<td>-50</td>\r\n<td>0.440</td>\r\n<td>2.27</td>\r\n<td>175</td>\r\n<td>0.4769</td>\r\n<td>2.10</td>\r\n</tr>\r\n<tr>\r\n<td>-25</td>\r\n<td>0.443</td>\r\n<td>2.26</td>\r\n<td>200</td>\r\n<td>0.482</td>\r\n<td>2.08</td>\r\n</tr>\r\n<tr>\r\n<td>0</td>\r\n<td>0.447</td>\r\n<td>2.24</td>\r\n<td>225</td>\r\n<td>0.488</td>\r\n<td>2.05</td>\r\n</tr>\r\n<tr>\r\n<td>+25</td>\r\n<td>0.453*</td>\r\n<td>2.21</td>\r\n<td>250</td>\r\n<td>0.495</td>\r\n<td>2.02</td>\r\n</tr>\r\n<tr>\r\n<td>+50</td>\r\n<td>0.456</td>\r\n<td>2.19</td>\r\n<td>275</td>\r\n<td>0.503</td>\r\n<td>1.99</td>\r\n</tr>\r\n<tr>\r\n<td>+75</td>\r\n<td>0.459</td>\r\n<td>2.18</td>\r\n<td>300</td>\r\n<td>0.514</td>\r\n<td>1.95</td>\r\n</tr>\r\n<tr>\r\n<td>+100</td>\r\n<td>0.463</td>\r\n<td>2.16</td>\r\n<td>325</td>\r\n<td>0.534</td>\r\n<td>1.88</td>\r\n</tr>\r\n<tr>\r\n<td>+125</td>\r\n<td>0.467</td>\r\n<td>2.14</td>\r\n<td>327</td>\r\n<td>0.640**</td>\r\n<td>1.57</td>\r\n</tr>\r\n<tr>\r\n<td>+150</td>\r\n<td>0.471</td>\r\n<td>2.12</td>\r\n<td>350</td>\r\n<td>0.655</td>\r\n<td>1.53</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n* При нагревании от 19,6 до 22°C удлиненный объём увеличивается на 0,74%\r\n** При 327°С удлиненный объём увеличивается на 20%.\r\n\r\n<h2>ФИЗИКО-МЕХАНИЧЕСКИЕ СВОЙСТВА ФТОРОПЛАСТА-4</h2>\r\n<p>Основные показатели физико-механических свойств фторопласта-4 приведены ниже:</p>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td><strong>Разрушающее напряжение, кгс/см<sup>2</sup></strong></td>\r\n<td>Значения</td>\r\n</tr>\r\n<tr>\r\n<td>при растяжении:</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- незакаленный образец (кристалличность 05-08%)</td>\r\n<td>140-350*</td>\r\n</tr>\r\n<tr>\r\n<td>- закаленный образец (кристалличность 50%)</td>\r\n<td>160-315*</td>\r\n</tr>\r\n<tr>\r\n<td>при сжатии:</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- при 1%-ной деформации</td>\r\n<td>100</td>\r\n</tr>\r\n<tr>\r\n<td>- 10%-ной деформации</td>\r\n<td>185</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Сопротивлению изгибу (стрела прогиба 6 мм)</strong></td>\r\n<td>185</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Относительное удлинение при разрыт, %</strong></td>\r\n<td>250-500</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Остаточное удлинение, %</strong></td>\r\n<td>250-350</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Напряжение при 10%-ном удлинении, кгс/см<sup>2</sup></strong></td>\r\n<td>110-120</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Модуль упругости, кгс/см<sup>2</sup></strong></td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- при изгибе при 20°С</td>\r\n<td>4700-8500</td>\r\n</tr>\r\n<tr>\r\n<td>- сдвиге 2700</td>\r\n<td>2700</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Ударная вязкость, кгс·см/см<sup>2</sup></strong></td>\r\n<td>100 (не ломается)</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Ударное растяжение, кгс·см/см<sup>2</sup> (DIN 53448)</strong></td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- при 20°С</td>\r\n<td>650</td>\r\n</tr>\r\n<tr>\r\n<td>- 23°С</td>\r\n<td>680</td>\r\n</tr>\r\n<tr>\r\n<td>(удлинение при 20°С - 20%, при 23°С - 30%)</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Твердость:</strong></td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>по Бринеллю, кгс/мм<sup>2</sup></td>\r\n<td>3-4</td>\r\n</tr>\r\n<tr>\r\n<td>по Шору при 20°С</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- шкала С</td>\r\n<td>85-87</td>\r\n</tr>\r\n<tr>\r\n<td>- шкала D</td>\r\n<td>55-59</td>\r\n</tr>\r\n<tr>\r\n<td>Твердость по Роквеллу</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- шкала I</td>\r\n<td>80-95</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>В зависимости от того, как вырезан образец: поперек направления прессования-высокие значения, вдоль направления прессования-малые.</p>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td><strong>Показатели</strong></td>\r\n<td colspan="10"><strong>Температура, °С</strong></td>\r\n</tr>\r\n<tr>\r\n<td>-</td>\r\n<td>-60</td>\r\n<td>-40</td>\r\n<td>-20</td>\r\n<td>0</td>\r\n<td>20</td>\r\n<td>40</td>\r\n<td>60</td>\r\n<td>80</td>\r\n<td>100</td>\r\n<td>120</td>\r\n</tr>\r\n<tr>\r\n<td>Разрушающее напряжение при растяжении, кгс/см<sup>2</sup></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>- незакаленный образец</td>\r\n<td>-</td>\r\n<td>350</td>\r\n<td>325</td>\r\n<td>300</td>\r\n<td>200</td>\r\n<td>180</td>\r\n<td>-</td>\r\n<td>135</td>\r\n<td>115</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- закаленный образец</td>\r\n<td>-</td>\r\n<td>500</td>\r\n<td>440</td>\r\n<td>330</td>\r\n<td>250</td>\r\n<td>240</td>\r\n<td>-</td>\r\n<td>200</td>\r\n<td>190</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>Относительное удлинение при разрыве, %</td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>- незакаленный образец</td>\r\n<td>-</td>\r\n<td>70</td>\r\n<td>100</td>\r\n<td>150</td>\r\n<td>470</td>\r\n<td>650</td>\r\n<td>-</td>\r\n<td>600</td>\r\n<td>540</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>- закаленный образец</td>\r\n<td>-</td>\r\n<td>100</td>\r\n<td>160</td>\r\n<td>190</td>\r\n<td>400</td>\r\n<td>500</td>\r\n<td>-</td>\r\n<td>500</td>\r\n<td>480</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>Модуль упругости, кгс/см<sup>2</sup></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>при сжатии</td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>- незакаленный образец</td>\r\n<td>18000</td>\r\n<td>17000</td>\r\n<td>15000</td>\r\n<td>11000</td>\r\n<td>7000</td>\r\n<td>4500</td>\r\n<td>3300</td>\r\n<td>2400</td>\r\n<td>1700</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>при сжатии</td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>- незакаленный образец</td>\r\n<td>27800</td>\r\n<td>23900</td>\r\n<td>23300</td>\r\n<td>18100</td>\r\n<td>8500</td>\r\n<td>5100</td>\r\n<td>4800</td>\r\n<td>3800</td>\r\n<td>-</td>\r\n<td>2450</td>\r\n</tr>\r\n<tr>\r\n<td>- закаленный образец</td>\r\n<td>13200</td>\r\n<td>11300</td>\r\n<td>9800</td>\r\n<td>7400</td>\r\n<td>4700</td>\r\n<td>4000</td>\r\n<td>2900</td>\r\n<td>2180</td>\r\n<td>-</td>\r\n<td>1100</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>Данные о зависимости физико-механических свойств фторопласта-4 от температуры приведены ниже.</p>\r\n\r\n<h2>Физико-механические свойства фторопласта-4 при низких температурах\r\n</h2>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td><strong>Показатели</strong></td>\r\n<td colspan="6"><strong>Температура, °С</strong></td>\r\n</tr>\r\n<tr>\r\n<td></td>\r\n<td>-93</td>\r\n<td>-123</td>\r\n<td>-153</td>\r\n<td>-193</td>\r\n<td>-223</td>\r\n<td>-269</td>\r\n</tr>\r\n<tr>\r\n<td>Разрушающее напряжение при сжатии *, кгс/см<sup>2</sup></td>\r\n<td>350</td>\r\n<td>-</td>\r\n<td>980</td>\r\n<td>1260</td>\r\n<td>1554</td>\r\n<td>1750-1960</td>\r\n</tr>\r\n<tr>\r\n<td>Модуль упругости при сжатии, кгс/см<sup>2</sup></td>\r\n<td>-</td>\r\n<td>52500</td>\r\n<td>-</td>\r\n<td>-</td>\r\n<td>-</td>\r\n<td>70000</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>* Разрушающее напряжение при сжатии равно напряжению, при котором деформация составляет 0,2%.</p>\r\n\r\n<h2>Зависимость деформации фторопласта-4 при сжатии от температуры:</h2>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td><strong>Деформация, %</strong></td>\r\n<td colspan="7"><strong>Нагрузка, вызывающая деформацию, кгс/см</strong><sup>2</sup></td>\r\n</tr>\r\n<tr>\r\n<td>-</td>\r\n<td>-50°С</td>\r\n<td> 0°С</td>\r\n<td> 25°С</td>\r\n<td>50°С</td>\r\n<td>100°С</td>\r\n<td>150°С</td>\r\n<td>200°С</td>\r\n</tr>\r\n<tr>\r\n<td>1</td>\r\n<td>203</td>\r\n<td>157</td>\r\n<td>62</td>\r\n<td>49</td>\r\n<td>31</td>\r\n<td>17,5</td>\r\n<td>11</td>\r\n</tr>\r\n<tr>\r\n<td>2</td>\r\n<td>304</td>\r\n<td>210</td>\r\n<td>92</td>\r\n<td>66</td>\r\n<td>39</td>\r\n<td>27</td>\r\n<td>20</td>\r\n</tr>\r\n<tr>\r\n<td>3</td>\r\n<td>350</td>\r\n<td>236</td>\r\n<td>105</td>\r\n<td>77</td>\r\n<td>48</td>\r\n<td>33</td>\r\n<td>27</td>\r\n</tr>\r\n<tr>\r\n<td>4</td>\r\n<td>374</td>\r\n<td>251</td>\r\n<td>120</td>\r\n<td>85</td>\r\n<td>59</td>\r\n<td>39</td>\r\n<td>31</td>\r\n</tr>\r\n<tr>\r\n<td>5</td>\r\n<td>390</td>\r\n<td>262</td>\r\n<td>127</td>\r\n<td>92</td>\r\n<td>62</td>\r\n<td>44</td>\r\n<td>35</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>Одним из важнейших прочностных показателей является предел текучести при растяжении, т.е. то напряжение, при котором возникают остаточные деформации. Он зависит от степени кристалличности, скорости растяжения и температуры. При степени кристалличности 65% и скорости растяжения 100 мм/мин зависимость предела текучести от абсолютной температуры Т (в К) описывается эмпирической формулой (справедливой от 20 до 300°С):\r\nlgσT= 0,53166+483,64/Т</p>\r\n<p>Ниже приведены значения пределов текучести для некоторых температур, рассчитанные по этой формуле:</p>\r\n\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tr>\r\n<td>Температура, °С</td><td>  25</td><td>50</td><td>75</td><td>100</td><td>150</td><td>200</td><td>250</td></tr>\r\n<tr><td>Предел текучести, кгс/см2</td><td>42,4</td><td>106,9</td><td>83,5</td><td>67,2</td><td>46,6</td><td>35,5</td><td>28,6</tr></table>\r\n\r\n<p>При длительном воздействии нагрузок остаточные деформации возникают при меньших напряжениях (40-50% от рассчитанных по формуле).</p><p>\r\nПри конструировании изделий из фторопласта-4 следует учитывать ползучесть. Ползучесть (деформация при длительном действии нагрузки) рассчитывается по формуле:<br>\r\nlgγt=lgγ1+a·lgt<br>\r\nгде γt - деформация за t сут; γ1 - деформация за 1 сут; а - коэффициент, зависящий в основном от температуры и в меньшей степени от нагрузки, если она не превышает 40-50% предела текучести.</p><p>\r\nЗначения коэффициента a и некоторые данные о ползучести для образцов со степенью кристалличности 50% приведены в таблице. Деформация за 1 сут (γ1) при других нагрузках и температурах определяется опытным путем. При степени кристалличности 65-68% ползучесть меньше.</p>\r\n\r\n<h2>   Ползучесть фторопласта-4</h2>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td><strong>Температура, °С</strong></td>\r\n<td><strong>Нагрузка, кгс/см<sup>2</sup></strong></td>\r\n<td colspan="2"><strong>Деформация, %</strong></td>\r\n<td><strong>Коэффициент а\r\n</strong></td>\r\n</tr>\r\n<tr>\r\n<td colspan="2">Сжатие</td>\r\n<td>1 сут (γ1)</td>\r\n<td>4 сут (γ4)</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>20</td>\r\n<td>33</td>\r\n<td>6,00</td>\r\n<td>6,25</td>\r\n<td>0,030</td>\r\n</tr>\r\n<tr>\r\n<td>20</td>\r\n<td>21</td>\r\n<td>3,05</td>\r\n<td>3,19</td>\r\n<td>0,032</td>\r\n</tr>\r\n<tr>\r\n<td colspan="2">Растяжение</td>\r\n<td>1 сут (γ1)</td>\r\n<td>4 сут (γ4)</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>40</td>\r\n<td>28</td>\r\n<td>2,72</td>\r\n<td>2,87</td>\r\n<td>0,038</td>\r\n</tr>\r\n<tr>\r\n<td>100</td>\r\n<td>28</td>\r\n<td>5,58</td>\r\n<td>5,90</td>\r\n<td>0,040</td>\r\n</tr>\r\n<tr>\r\n<td>140</td>\r\n<td>21</td>\r\n<td>4,67</td>\r\n<td>4,94</td>\r\n<td>0,042</td>\r\n</tr>\r\n<tr>\r\n<td>200</td>\r\n<td>14</td>\r\n<td>4,08</td>\r\n<td>4,50</td>\r\n<td>0,048</td>\r\n</tr>\r\n<tr>\r\n<td>250</td>\r\n<td>14</td>\r\n<td>5,17</td>\r\n<td>5,58</td>\r\n<td>0,055</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<h2>АНТИФРИКЦИОННЫЕ СВОЙСТВА ФТОРОПЛАСТА-4</h2>\r\nДанные о зависимости коэффициента трения от нагрузки [статической и динамической (при малых скоростях) коэффициенты трения фторопласта-4 по стали без смазки одинаковы] приведены ниже:\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Нагрузка, кгс/см2</td>\r\n<td>1</td>\r\n<td>3</td>\r\n<td>10</td>\r\n<td>20</td>\r\n</tr>\r\n<tr>\r\n<td>Коэффициент трения</td>\r\n<td>0,4</td>\r\n<td>0,1</td>\r\n<td>0,06</td>\r\n<td>0,05</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>При наличии смазки он примерно в 2 раза меньше.</p><p>\r\nДинамический коэффициент трения фторопласта-4 по стали без смазки при нагрузке ~ 20 кгс/см2 зависит от скорости скольжения:</p>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Скорость скольжения, см/c</td>\r\n<td>4</td>\r\n<td>8</td>\r\n<td>20</td>\r\n<td>40</td>\r\n<td>80</td>\r\n<td>160</td>\r\n</tr>\r\n<tr>\r\n<td>Динамический коэффициент трения</td>\r\n<td>0,05</td>\r\n<td>0,1</td>\r\n<td>0,15</td>\r\n<td>0,23</td>\r\n<td>0,24</td>\r\n<td>0,27</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>В присутствии наполнителя при малых скоростях скольжения коэффициент трения несколько выше, а при больших скоростях - ниже, чем коэффициент трения чистого фторопласта-4 по стали.</p><p>\r\nПри 327°С (на поверхности трения) коэффициент трения фторопласта-4 по стали резко возрастает (в несколько раз), что приводит к катастрофически быстрому износу и разрушению подшипника.<p>\r\n\r\n<h2>ТЕПЛОФИЗИЧЕСКИЕ СВОЙСТВА ФТОРОПЛАСТА-4</h2>\r\n<p>Неспеченный фторопласт-4 (в виде порошка) имеет степень кристалличности 95 - 98%, после спекания - от 50% (закаленный) до 68 - 70% (незакаленный). Ниже 19,6°С элементарная ячейка кристалла фторопласта-4 состоит из 13 групп CF2, выше 19,6°С - из 15 групп CF2. При 19,6°С триклиническая упаковка переходит в менее упорядоченную, гексагональную, что сопровождается увеличение объема кристаллитов на 0,0058 см3/г (1,2 объемн. %), или увеличением объема образца при степени кристалличности 68% на 0,74%. При наличии внешнего давления точка перехода понижается на 0,013°С на каждую атмосферу. При 30°С имеет место второй переход кристаллической структуры, но изменение объема составляет едва 1/10 часть изменения объема при 19,6°С. Под высоким давлением (4500 кгс/см2 при 70°С) возникает третий переход.</p><p>\r\nТемпература стеклования аморфных участков, определенная по температуре хрупкости, колеблется от -97 до -100°С, а по точке перегиба кривой зависимости модуля упругости составляет -120°С. Температура перехода аморфного твердого тела в переохлажденную жидкость равна 127°С.</p><p>\r\nПри 327°С кристаллиты фторопласта-4 плавятся, и он становится полностью аморфным, совершенно прозрачным (при отсутствии пористости), высокоэластичным, но не течет (вязкость выше 1011 П). Объем возрастает на 20%.\r\n</p><p>\r\nТочка плавления зависит от внешнего давления - на каждую атмосферу повышается на 0,154 °С. При остывании расплава ниже 327 °С образец мутнеет и становится непрозрачным - молочно-белым.   Скорость кристаллизации зависит от температуры (максимальная скорость при 310-315 °С), от продолжительности выдержки в расплавленном состоянии при 370-390 °С (чем больше время спекания, тем быстрее кристаллизуется образец) и от среднего молекулярного веса полимера (чем ниже молекулярный вес полимера, тем быстрее он кристаллизуется). На этом основан метод косвенной оценки молекулярного веса фторопласта-4: образец в виде диска толщиной 2 мм спекают при 370 °С в течение 13 ч и охлаждают от 370 до 250 °С в течение 5 ч. По плотности полученного образца при 23 °С можно оценить молекулярный вес: 2,16-2,19 г/см3-для высокомолекулярного полимера, 2,20-2,22 г/см3-для низкомолекулярного.\r\n</p><p>\r\n<h2>Ниже приведены некоторые теплофизические свойства фторопласта-4:</h2>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Теплостойкость по Вика (при нагрузке 5 кгс), °С</td>\r\n<td>110</td>\r\n</tr>\r\n<tr>\r\n<td>Удельная теплоемкость, ккал/(кг·°С)</td>\r\n<td>-</td>\r\n</tr>\r\n<tr>\r\n<td>при 0°С</td>\r\n<td>0,23</td>\r\n</tr>\r\n<tr>\r\n<td>при 50°С</td>\r\n<td>0,25</td>\r\n</tr>\r\n<tr>\r\n<td>Коэффициент теплопроводности, ккал/(м·ч·°С)</td>\r\n<td>0,20</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>Термический коэффициент линейного расширения зависит от температуры:</p>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Температура, °С</td>\r\n<td>от -60 до -10</td>\r\n<td>19,6</td>\r\n<td>30</td>\r\n<td>40</td>\r\n<td>200</td>\r\n<td>300</td>\r\n</tr>\r\n<tr>\r\n<td>Термический коэффициент линейного расширения α·105, 1/°С</td>\r\n<td>8</td>\r\n<td>54</td>\r\n<td>28</td>\r\n<td>11</td>\r\n<td>25</td>\r\n<td>64</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>На практике удобнее пользоваться средними значениями термического коэффициента линейного расширения для определенных интервалов температур. Следует также учитывать, что при нагревании изделий из фторопласта-4 в них часто возникают внутренние напряжения, вызывающие необратимое изменение размеров. Иногда вместо ожидаемого при нагревании удлинения образца он сокращается.</p><p>\r\nДанные, приведенные ниже, относятся к образцам, в которых полностью отсутствуют внутренние напряжения:</p>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Температура, °C</td>\r\n<td>Термический коэффициент линейного расширения α·105, 1/°C</td>\r\n<td>Изменение размеров изделия*, %</td>\r\n<td>Температура, °C</td>\r\n<td>Термический коэффициент линейного расширения α·105, 1/°C</td>\r\n<td>Изменение размеров изделия*, %</td>\r\n</tr>\r\n<tr>\r\n<td>от -193 до +25</td>\r\n<td>8,6</td>\r\n<td>-1,85</td>\r\n<td>от +25 до +100</td>\r\n<td>12,4</td>\r\n<td>+0,93</td>\r\n</tr>\r\n<tr>\r\n<td>от -150 до +25</td>\r\n<td>9,6</td>\r\n<td>-1,68</td>\r\n<td>от +25 до +150</td>\r\n<td>13,5</td>\r\n<td>+1,59</td>\r\n</tr>\r\n<tr>\r\n<td>от -100 до +25</td>\r\n<td>11,2</td>\r\n<td>-1,40</td>\r\n<td>от +25 до +200</td>\r\n<td>15,1</td>\r\n<td>+2,64</td>\r\n</tr>\r\n<tr>\r\n<td>от -50 до +25</td>\r\n<td>13,5</td>\r\n<td>-1,01</td>\r\n<td>от +25 до +250</td>\r\n<td>17,4</td>\r\n<td>+3,92</td>\r\n</tr>\r\n<tr>\r\n<td> от 0 до +25</td>\r\n<td>20,0</td>\r\n<td>-0,50</td>\r\n<td>от +25 до +300</td>\r\n<td>21,8</td>\r\n<td>+5,99</td>\r\n</tr>\r\n<tr>\r\n<td>от +25 до +50</td>\r\n<td>12,4</td>\r\n<td>+0,31</td>\r\n<td>от +25 до +300</td>\r\n<td>21,8</td>\r\n<td>+5,99</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>* От размера при 25°С.</p>\r\n\r\n<h2>ЭЛЕКТРИЧЕСКИЕ СВОЙТСВА ФТОРОПЛАСТА-4</h2>\r\n<p>Показатели электрических свойств фторопласта-4 приведены ниже:</p>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Удельное электрическое сопротивление:</td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>-поверхностное, Ом</td>\r\n<td>&gt;10<sup>17</sup></td>\r\n</tr>\r\n<tr>\r\n<td>-на воздухе со 100%-ной относительной влажностью</td>\r\n<td>&gt;10<sup>12</sup></td>\r\n</tr>\r\n<tr>\r\n<td>-объемное (до 150<sup>о</sup>С), Ом·см</td>\r\n<td>101<sup>7</sup> - 10<sup>20</sup></td>\r\n</tr>\r\n<tr>\r\n<td>-после длительного пребывания в воде не меняется</td>\r\n<td>1,9-2,2</td>\r\n</tr>\r\n<tr>\r\n<td>Диэлектрическая проницаемость (при 60 - 1010 Гц)</td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>Тангенс угла диэлектрических потерь (при 60 - 1010 Гц)</td>\r\n<td>&lt;1·10<sup>17</sup></td>\r\n</tr>\r\n<tr>\r\n<td>Электрическая прочность, кВ/мм:</td>\r\n<td></td>\r\n</tr>\r\n<tr>\r\n<td>-при толщине образца 4 мм</td>\r\n<td>25-27</td>\r\n</tr>\r\n<tr>\r\n<td>-при толщине образца 0,1 - 0,3 мм</td>\r\n<td>40-80</td>\r\n</tr>\r\n<tr>\r\n<td>-при толщине образца 0,005 - 0,02 мм</td>\r\n<td>200-300</td>\r\n</tr>\r\n<tr>\r\n<td>Дугостойкость, с (сплошного токопроводящего слоя не образуется)</td>\r\n<td>250-700</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>Данные о зависимости тангенса угла диэлектрических потерь от частоты приведены ниже:</p>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Частота, Гц</td>\r\n<td>60</td>\r\n<td>10<sup>3</sup></td>\r\n<td>10<sup>4</sup></td>\r\n<td>10<sup>5</sup></td>\r\n<td>10<sup>6</sup></td>\r\n<td>10<sup>7</sup></td>\r\n</tr>\r\n<tr>\r\n<td>tgδ·10<sup>4</sup></td>\r\n<td>0,5</td>\r\n<td>0,3</td>\r\n<td>0,4</td>\r\n<td>0,7</td>\r\n<td>0,7</td>\r\n<td>0,7</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>Диэлектрическая проницаемость фторопласта-4 вплоть до 1010 Гц не зависит от частоты, а зависит от плотности: є= <u>1+0,238*d</u>\r\n2-0,119*d\r\nгде d - плотность при данной степени кристалличности и температуре.\r\nТангенс угла диэлектрических потерь остается постоянным при температуре от -60 до 250<sup>о</sup>С.\r\nПрогрев при 300<sup>о</sup>С в течение 6 месяцев не влияет на диэлектрические свойства фторопласта-4.<p>\r\n\r\n<h2>ХИМИЧЕСКИЕ И ДРУГИЕ СВОЙСТВА ФТОРОПЛАСТА-4</h2>\r\n<p>Фторопласт-4 является самым стойким из всех известных металлов - пластмасс, металлов, стекол, эмалей, сплавов и т.п. На него совершенно не действуют кислоты, окислители, щелочи, растворители. На фторопласт-4 действуют только расплавленные щелочные металлы и их комплексные соединения с аммиаком, нафталином, пиридином, а также трехфтористых хлор и элементный фтор при повышенных температурах. При температурах выше 327<sup>о</sup>С фторопласт набухает в жидких фторуглеродах, например в перфторкеросине. При 20<sup>о</sup>С фторопласт-4 слегка набухает (3 - 9%) в фторхлорсодержащих газах (фреонах).</p><p>\r\nВыше 350<sup>о</sup>С фторопласт-4 реагирует с щелочеземельными металлами и их соединениями (окислами и карбонатами), а также с окислами некоторых других металлов (свинца, кадмия, меди).</p><p>\r\nФторопласт-4 не смачивается водой при кратковременном погружении (угол смачивания 126<sup>о</sup>С), но смачивается при длительном пребывании в дистиллированной воде (15 - 20 суток). В соленой воде (например, морской) на поверхности фторопласта-4 через 15 - 20 суток отлагается пленка солей, смываемая дистиллированной водой.</p><p>\r\nВодопоглощение за 24 часа (и более продолжительное время) - ниже ошибки взвешивания (0,00%).</p><p>\r\nФторопласт-4 абсолютно стоек в тропических условиях и не подвижен действию грибков (но и не подавляет их развитие).</p><p>\r\nВлагопроницаемость при 20<sup>о</sup>С равна 3·10<sup>-9</sup> - 6·10<sup>-9</sup> г/(см·ч·мм рт. ст.); паропроницаемость при 20<sup>о</sup>С составляет 0,6·10<sup>-9</sup> - 1,2·10<sup>-9</sup> г/(см·ч·мм рт. ст.).</p><p>\r\nДанные о газопроницаемости пленки из фтороплавта-4 (при отсутствии пор) толщиной 0,1 мм при 20<sup>о</sup>С [в см<sup>3</sup>/(см·с·мм рт. ст.)] приведены ниже:</p>\r\n<table class="responsive-table" border="1" width="100%" cellspacing="1" cellpadding="1">\r\n<tbody>\r\n<tr>\r\n<td>Воздух</td>\r\n<td>1,1*10<sup>-9</sup></td>\r\n</tr>\r\n<tr>\r\n<td>Азот</td>\r\n<td>0,7*10<sup>-9</sup></td>\r\n</tr>\r\n<tr>\r\n<td>Кислород</td>\r\n<td>2,3*10<sup>-9</sup></td>\r\n</tr>\r\n<tr>\r\n<td>Водород</td>\r\n<td>6,3*10<sup>-9</sup></td>\r\n</tr>\r\n<tr>\r\n<td>Двуокись углерода</td>\r\n<td>4,8*10<sup>-9</sup></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>При наличии пористости проницаемость может увеличиваться до 1000 раз.</p><p>\r\nФторопласт-4 предназначен для видимого света только при малой толщине пленки:</p>\r\n<table class="responsive-table" width="100%">\r\n<tbody>\r\n<tr>\r\n<td width="95%"></td>\r\n</tr>\r\n</tbody>\r\n<tbody>\r\n<tr>\r\n<td>Толщина пленки, мм</td>\r\n<td>0,05</td>\r\n<td>0,10</td>\r\n<td>0,15</td>\r\n<td>1,00</td>\r\n</tr>\r\n<tr>\r\n<td>Пропускание, %</td>\r\n<td>88</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n', 'Фторопласт - описание свойств от показателей', '', 'inherit', 'closed', 'closed', '', '2893-revision-v1', '', '', '2018-06-13 19:46:12', '2018-06-13 19:46:12', '', 2893, '<p>Фторопласт -4 - кристаллический полимер, температурой плавления кристаллитов 327°С и температурой стеклования аморфных участков от -100 до -120°С. Даже при температуре выше температуры разложения (415°С) фторопласт-4 не переходит в вязкотекучее состоян', 0, 'revision', '', 0),
(3711, 1, '2018-06-13 19:54:16', '2018-06-13 19:54:16', '<p>ЗАО «Фторопластовые технологии» (ДП) приняло участие в четвертой международной выставке "EIA: электроника и промышленная автоматизация 2009", которая прошла в выставочном центре "КиевЭкспоПлаза"с  6 по 9 апреля 2009 г.</p>\r\n\r\n<p><b>Страной-партнером elcomUkraine 2009 выступила Федеративная Республика Германия</b>. Данная акция направлена на активизацию развития торгово-экономических отношений между Германией и Украиной в области энергетики и энергоэффективности.</p>\r\n\r\n<h2>Технические экспозиции выставки:</h2>\r\n<p>Электротехника, системы энергообеспечения и электропитания, кабельно-проводниковая продукция, светотехника.</p>', 'Участие в выставке ДП ''Фторопластовые технологии''', '', 'inherit', 'closed', 'closed', '', '2848-revision-v1', '', '', '2018-06-13 19:54:16', '2018-06-13 19:54:16', '', 2848, '<p>ЗАО «Фторопластовые технологии» (ДП) приняло участие в четвертой международной выставке "EIA: электроника и промышленная автоматизация 2009", которая прошла в выставочном центре "КиевЭкспоПлаза"с  6 по 9 апреля 2009 г.</p>\r\n\r\n<p><b>Страной-партнером el', 0, 'revision', '', 0);
INSERT INTO `fttwp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(3712, 1, '2018-06-13 20:01:13', '2018-06-13 20:01:13', '<p>Настоящий стандарт распространяется на электроизоляционные трубки из фторопласта 4Д и 4ДМ, работающие в интервале температур от минус 196 до плюс 250°С и применяемые для электроизоляции проводов в различных климатических условиях.</p>\r\n<p>Настоящий стандарт устанавливает единые требования к трубкам, изготовляемым для нужд народного хозяйства и экспорта.</p>\r\n<p>Трубки обладают высокой химической стойкостью к различным химическим средам.</p>\r\n<p>Трубки относятся к типу 308 по ГОСТ 17675-87.</p>\r\n<p>Требования настоящего стандарта являются обязательными. Показатели приложения 4 гарантируются технологией изготовления продукции.</p>\r\n<p>(Измененная редакция, Изм. № 2, 3).</p>\r\n\r\n1. РАЗМЕРЫ\r\n1.1. Размеры  трубок должны соответствовать указанным  в табл. 1.\r\nТаблица  1 мм\r\n<table class="responsive-table" width="100%">\r\n<tbody>\r\n<tr>\r\n<td colspan="2" valign="top" width="302">\r\n<div>Диаметр внутренний</div></td>\r\n<td colspan="2" valign="top" width="302">\r\n<div>Толщина стенки</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="151">\r\n<div>Номин.</div></td>\r\n<td valign="top" width="151">\r\n<div>Пред. откл.</div></td>\r\n<td valign="top" width="151">\r\n<div>Номин.</div></td>\r\n<td valign="top" width="151">\r\n<div>Пред. откл.</div></td>\r\n</tr>\r\n<tr>\r\n<td width="151">\r\n<div>0,3</div>\r\n<div>0,4</div>\r\n<div>0,5</div></td>\r\n<td width="151">\r\n<div>±0,1</div></td>\r\n<td width="151">\r\n<div>0,2</div></td>\r\n<td width="151">\r\n<div>+0,06\r\n-0,02</div></td>\r\n</tr>\r\n<tr>\r\n<td width="151">\r\n<div>0,6</div>\r\n<div>0,7</div>\r\n<div>0,8</div>\r\n<div>0,9</div>\r\n<div>1,0</div></td>\r\n<td width="151">\r\n<div>±0,15</div></td>\r\n<td width="151">\r\n<div>0,2</div></td>\r\n<td width="151">\r\n<div>+0,06\r\n-0,02</div></td>\r\n</tr>\r\n<tr>\r\n<td width="151">\r\n<div>1,0</div>\r\n<div>1,2</div>\r\n<div>1,4</div>\r\n<div>1,5</div>\r\n<div>1,6</div>\r\n<div>1,8</div>\r\n<div>2,0</div></td>\r\n<td width="151">\r\n<div>±0,15</div></td>\r\n<td width="151">\r\n<div>0,3</div></td>\r\n<td width="151">\r\n<div>+0,09\r\n-0,03</div></td>\r\n</tr>\r\n<tr>\r\n<td width="151">\r\n<div>2,1</div>\r\n<div>2,2</div>\r\n<div>2,4</div>\r\n<div>2,5</div>\r\n<div>2,6</div>\r\n<div>2,8</div>\r\n<div>3,0</div></td>\r\n<td width="151">\r\n<div>±0,15</div></td>\r\n<td width="151">\r\n<div>0,4</div></td>\r\n<td width="151">\r\n<div>+0,12\r\n-0,04</div></td>\r\n</tr>\r\n<tr>\r\n<td width="151">\r\n<div>3,5</div>\r\n<div>3,8</div>\r\n<div>4,0</div>\r\n<div>4,2</div>\r\n<div>4,5</div>\r\n<div>5,0</div></td>\r\n<td width="151">\r\n<div>±0,30</div></td>\r\n<td width="151">\r\n<div>0,6</div></td>\r\n<td width="151">\r\n<div>+0,09\r\n-0,03</div></td>\r\n</tr>\r\n<tr>\r\n<td width="151">\r\n<div>4,0</div>\r\n<div>5,0</div>\r\n<div>5,5</div>\r\n<div>6,0</div>\r\n<div>7,0</div>\r\n<div>8,0</div></td>\r\n<td width="151">\r\n<div>±0,30</div></td>\r\n<td width="151">\r\n<div>1,0</div></td>\r\n<td width="151">\r\n<div>+0,15\r\n-0,05</div></td>\r\n</tr>\r\n<tr>\r\n<td width="151">\r\n<div>9,0</div>\r\n<div>10,0</div>\r\n<div>6,0</div>\r\n<div>8,0</div>\r\n<div>9,0</div>\r\n<div>10,0</div></td>\r\n<td rowspan="2" width="151">\r\n<div>±0,30</div></td>\r\n<td width="151">\r\n<div>1,5</div></td>\r\n<td width="151">\r\n<div>+0,23\r\n-0,07</div></td>\r\n</tr>\r\n<tr>\r\n<td width="151">\r\n<div>8,0</div></td>\r\n<td width="151">\r\n<div>2,0</div></td>\r\n<td width="151">\r\n<div>+0,30\r\n-0,10</div></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<div><i>Примечание.</i> По согласованию с потребителем допускается изготовлять электроизоляционные трубки из фторопласта 4Д и 4ДМ других размеров, не указанных в табл. 1 (при этом внутренний диаметр должен быть не более10 мм), и трубки толщиной 0,6 мм с допуском</div>\r\n<div>(Измененная редакция, Изм. № 2, 3).</div>\r\n<div>1.2. Для каждого типоразмера трубок коды ОКП по Общесо­юзному классификатору промышленной и сельскохозяйственной продукции указаны в приложении 3.</div>\r\n<div>(Измененная редакция, Изм. № 2).</div>\r\n<div>1.3. Трубки должны изготовляться длиной не менее 1,0 м. По согласованию с потребителем допускается выпускать электроизо­ляционные трубки не менее 0,3 мм.</div>\r\n<div>(Измененная редакция, Изм. № 3).</div>\r\n<div>1.4. Площадь сечения и масса трубок указаны в приложении 1.</div>\r\n<div>Пример условного обозначения трубки, изготовленной из фторопласта 4ДМ, диаметром 0,3 мм, толщиной стенки 0,2 мм, окрашенной в синий цвет, дополнительно термообработанной:</div>\r\n<div>Трубка Ф-4ДМ 0,3x0,2Т, синяя ГОСТ 22056-76</div>\r\n<div>То же, изготовленной из фторопласта 4Д диаметром 1,2 мм, толщиной стенки 0,3 мм, неокрашенный, без дополнительной термообработки:</div>\r\n<div>Трубка Ф-4Д, 1,2X0,3 ГОСТ 22056-76.</div>\r\n<div>(Измененная редакция, Изм. № 2, 3).</div>\r\n<div>2. ТЕХНИЧЕСКИЕ ТРЕБОВАНИЯ</div>\r\n<div>2.1. Трубки должны соответствовать ГОСТ 17675-87 и требованиям настоящего стандарта.</div>\r\n<div>2.2. Трубки изготовляют из фторопласта 4Д марки Э по ГОСТ 14906-77 или фторопласта 4ДМ по нормативно-технической документации.</div>\r\n<div>Допускается изготовление трубок из фторопласта 4Д марок Ш и Л по ГОСТ 14906-77.</div>\r\n<div>(Измененная редакция, Изм. № 2).</div>\r\n<div>2.3. Наружная и внутренняя поверхность трубок должна соответствовать ГОСТ 17675-87.</div>\r\n<div>Допускается неровная наружная поверхность трубок.</div>\r\n<div>Внутренний диаметр трубок должен быть концентричным к наружному в предельных отклонениях, указанных в табл. 1.</div>\r\n<div>2.4.Трубки должны изготовляться неокрашенными или окрашенными с дополнительной термообработкой и без нее.</div>\r\n<div>Цвет окраски устанавливается в заказе.</div>\r\n<div>Перечень пигментов для окраски трубок указан в приложении 2.</div>\r\n<div>2.5. Трубки должны соответствовать требованиям и нормам, указанным в табл. 2.</div>\r\n<div>Таблица 2</div>\r\n<table class="responsive-table" width="100%">\r\n<tbody>\r\n<tr>\r\n<td valign="top" width="284">\r\n<div>Наименование показателя</div></td>\r\n<td valign="top" width="151">\r\n<div>Норма</div></td>\r\n<td valign="top" width="189">\r\n<div>Метод испытания</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="284">\r\n<div>1. Цвет неокрашенных трубок</div>\r\n<div></div>\r\n<div>2. Прочность  при  разрыве, МПа (кгс/см<sup>2</sup>), не менее, трубок:</div>\r\n<div>без дополнительной термообработки   диаметром от 0,3 до 7,0 мм включ.</div>\r\n<div>св. 7,0 до 10,0 мм включ.</div>\r\n<div>с дополнительной термообработкой</div>\r\n<div></div>\r\n<div>3. Относительное   удлинение   при разрыве, %, не менее, трубок:</div>\r\n<div>без дополнительной термообработки</div>\r\n<div>с  дополнительной термообработкой</div></td>\r\n<td valign="top" width="151">\r\n<div>Белый натуральный</div>\r\n<div></div>\r\n<div></div>\r\n<div></div>\r\n<div>32 (320)</div>\r\n<div>27 (270)</div>\r\n<div>35 (350)</div>\r\n<div></div>\r\n<div></div>\r\n<div>250</div>\r\n<div>210</div></td>\r\n<td valign="top" width="189">\r\n<div>По п.4.2</div>\r\n<div></div>\r\n<div>По ГОСТ 11262―80 и п.4.5 настоящего стандарта</div>\r\n<div></div>\r\n<div></div>\r\n<div></div>\r\n<div></div>\r\n<div></div>\r\n<div>То же</div></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<div>2.4, 2.5.(Измененная редакция, Изм, № 2).</div>\r\n<div>2.6. Удельное объемное электрическое сопротивление, диэлектрическая проницаемость, тангенс угла диэлектрических потерь и элетрическая прочность трубок должна быть не ниже указанных в ГОСТ 14906-77 и проверке не подлежат.</div>\r\n<div>2.7. По согласованию с потребителем допускается изготовление неокрашенных электроизоляционных трубок из фторопласта 4Д и 4ДМ кремового цвета.</div>\r\n<div>(Введен дополнительно, Изм. № 2).</div>\r\n<div>2.8. Дополнительные показатели качества трубок приведены в приложении 4.</div>\r\n<div>(Введен дополнительно, Изм. № 3).</div>\r\n<div>3. ПРАВИЛА ПРИЕМКИ</div>\r\n<div>3.1. Для проверки соответствия трубок требованиям настоящего стандарта устанавливаются приемо-сдаточные испытания.</div>\r\n<div>3.2. Приемку трубок производят партиями. Партия должна состоять из трубок одного типоразмера, изготовленных из одной партии сырья.</div>\r\n<div>Масса партии должна быть не более 300 кг.</div>\r\n<div>(Измененная редакция, Изм. № 2).</div>\r\n<div>3.3. Для проверки качества трубок от каждой партии случайным образом отбирают по три бухты или пачки. (Измененная редакция, Изм. № 3).</div>\r\n<div>3.4. При получении неудовлетворительных результатов испытаний хотя бы по одному из показателей по нему проводят повторные испытания на удвоенном количестве образцов, взятых от тех же единиц партии. Результаты повторных испытаний распространяются на всю партию.</div>\r\n<div>4. МЕТОДЫ ИСПЫТАНИЙ</div>\r\n<div>4.1. Для испытаний отбирают от каждой бухты или пачки по три образца длиной не менее 200 мм.</div>\r\n<div>Перед испытанием образцы кондиционируют на воздухе при температуре (23±2) °С не менее 3 ч. Испытания проводят при температуре (23±2) °С.</div>\r\n<div>(Измененная редакция, Изм. № 3).</div>\r\n<div>4.2. Внешний вид и цвет трубок диаметром св. 1 до 10мм включительно проверяют визуально в отраженном свете при дневном освещении или освещении, создаваемом искусственным источником света. Трубки диаметром от 0,3 до 1,0 мм включительно изготовителем не проверяются. Трубки диаметром св. 1 до 5 мм включительно с дополнительной термической обработкой могут проверяться на установке полуавтоматического определителя дефектов («Паод»), при этом дефектные участки с пониженной; электрической прочностью автоматически вырубаются.</div>\r\n<div>Внешний вид трубок в бухтах проверяют по ГОСТ 17675-87.</div>\r\n<div>(Измененная редакция, Изм. № 2, 3).</div>\r\n<div>4.3. Внутренний диаметр трубки определяют измерительным стержнем по ГОСТ 17675-87. Длина рабочей части цилиндрической вставки измерительного стержня должна быть не менее 10 мм для трубок диаметром до 3 мм и не менее 15 мм для трубок диаметром более 3 мм. При определении внутреннего диаметра трубок до 3 мм включительно допускается    применять измерительные приборы, например, микроскоп ИМЦ 100Ч50, А.</div>\r\n<div>(Измененная редакция, Изм. № 3).</div>\r\n<div>4.4. Толщину стенок определяют по ГОСТ 17675-87.</div>\r\n<div>4.5. Прочность при разрыве и относительное удлинение при разрыве определяют по ГОСТ 11262-80 и ГОСТ 17675-87 на трубках длиной (120±5) мм с базой образца (25±1) мм при постоянном нарастании нагрузки до разрыва образца и скорость движения нижнего захвата машины (100±10) мм/мин.</div>\r\n<div>Прочность при разрыве (σ<sub>р</sub>), МПа, вычисляют по формуле</div>\r\n<div>где Р<sub>р</sub> - нагрузка, при которой образец разрушился, Н;</div>\r\n<div>      d - внутренний номинальный диаметр трубки, м;</div>\r\n<div>      s - толщина стенки трубки, м.</div>\r\n<div>(Измененная редакция, Изм. № 2, 3).</div>\r\n<div>5. УПАКОВКА, МАРКИРОВКА, ТРАНСПОРТИРОВАНИЕ И ХРАНЕНИЕ</div>\r\n<div>5.1. Упаковка, маркировка, транспортирование и хранение - по ГОСТ 17675-87.</div>\r\n<div>(Измененная редакция, Изм. № 3).</div>\r\n<div>5.1.1. Допускается упаковывание трубок в ящики № 35 и 38 по ГОСТ 13511-91, ГОСТ 16511-86 и ГОСТ 18573-86 № 26-1 тип II-I, барабаны по ГОСТ 17065-77.</div>\r\n<div>Масса ящика брутто не должна превышать 55 кг.</div>\r\n<div>Допускается дно и стенки ящика выстилать оберточной бумагой по ГОСТ 8273-75.</div>\r\n<div>Допускается обивать ящики стальной лентой без скрепления в замок.</div>\r\n<div>Допускается для одногородных потребителей упаковывание трубок в полиэтиленовые по ГОСТ 17811-78 или бумажные по ГОСТ 2226-88 мешки массой до 10 кг.</div>\r\n<div>(Введен дополнительно, Изм. № 3).</div>\r\n<div>5.2. При упаковывании трубок в пачки допускается вкладывать в них до 5% трубок длиной не менее 300 мм. (Измененная редакция, Изм. № 2).</div>\r\n<div>5.3. Масса партии трубок, поставляемых без контроля внешнего вида и цвета, увеличивается на 1,5%.</div>\r\n<div>5.4. (Исключен, Изм, № I).</div>\r\n<div>5.5. Пакетирование - по ГОСТ 17675-87. (Измененная редакция, Изм. № 2).</div>\r\n<div>6. ГАРАНТИИ ИЗГОТОВИТЕЛЯ</div>\r\n<div>6.1. Изготовитель гарантирует соответствие трубок требованиям; настоящего стандарта при соблюдении условий транспортирования; и хранения, установленных настоящим стандартом.</div>\r\n<div>(Измененная редакция, Изм. № 2, 3).</div>\r\n<div>6.2. Гарантийный срок хранения трубок - 17 лет со дня изготовления.</div>\r\n<div>(Измененная редакция, Изм. № 2).</div>\r\n<div>7. ТРЕБОВАНИЯ БЕЗОПАСНОСТИ</div>\r\n<div>7.1. Трубки из фторопласта 4Д и 4ДМ трудногорючи по ГОСТ 12.1.044-89. Температура самовоспламенения трубок - 520 °С. Воспламенение трубок не наблюдается до температуры самовоспламенения.</div>\r\n<div>При нагревании трубок до температуры выше 250 °С выделяются летучие продукты термоокислительной деструкции, предельна допустимая концентрация (ПДК) которых в воздухе рабочей зоны производственных помещений по ГОСТ 12.1.005-88 приведена в табл. 3.</div>\r\n<div>Таблица 3</div>\r\n<table class="responsive-table" width="100%">\r\n<tbody>\r\n<tr>\r\n<td width="217">\r\n<div>Наименование вещества</div></td>\r\n<td width="208">\r\n<div>Предельно допустимая  концентрация, мг/м<sup>3</sup></div></td>\r\n<td width="151">\r\n<div>Класс опасности</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="217">\r\n<div>Водород фтористый</div>\r\n<div>Перфторизобутилен</div>\r\n<div>Фтор- и дифторфосген</div>\r\n<div>Углерода оксид</div>\r\n<div>Аэрозоль фторопласта 4</div>\r\n<div>Тетрафторэтилен</div></td>\r\n<td valign="top" width="208">\r\n<div>0,5/0,1</div>\r\n<div>0,1</div>\r\n<div>0,9</div>\r\n<div>20</div>\r\n<div>10</div>\r\n<div>301</div></td>\r\n<td valign="top" width="151">\r\n<div>1</div>\r\n<div>1</div>\r\n<div>2</div>\r\n<div>4</div>\r\n<div>4</div>\r\n<div>4</div></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<div>(Измененная редакция, Изм. № 3).</div>\r\n<div>7.2. Работы, сопряженные с нагревом трубок, должны производиться в помещениях, оборудованных приточно-вытяжной вентиляцией, обеспечивающей полное удаление вредных веществ; в воздухе рабочей зоны при контроле состояния воздушной среды.</div>\r\n<div>7.3. При производстве трубок из фторопласта 4Д и 4ДМ специальных мер по защите природной среды от вредных воздействий не требуется.</div>\r\n<div>(Измененная редакция, Изм. № 2).</div>\r\n<div>7.4. В аварийных случаях применяются средства пожаротушения - распыленная вода, пена, песок, асбестовое одеяло, углекислотный огнетушитель.</div>\r\n<div>(Введен дополнительно, Изм. № 3).</div>\r\n<div>ПРИЛОЖЕНИЕ 1</div>\r\n<div>Обязательное</div>\r\n<div>Площадь сечения и масса трубок</div>\r\n<table class="responsive-table" width="100%">\r\n<tbody>\r\n<tr>\r\n<td width="170">\r\n<div>Внутренний диаметр, мм</div></td>\r\n<td width="132">\r\n<div>Толщина стенки,\r\nмм</div></td>\r\n<td width="132">\r\n<div>Расчетная площадь сечения, мм</div></td>\r\n<td width="142">\r\n<div>Расчетная масса\r\n1 м длины, г</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="170">\r\n<div>0,3</div>\r\n<div>0,4</div>\r\n<div>0,5</div>\r\n<div>0,6</div>\r\n<div>0,7</div>\r\n<div>0,8</div>\r\n<div>1,0</div></td>\r\n<td width="132">\r\n<div>0,2</div></td>\r\n<td valign="top" width="132">\r\n<div>0,31</div>\r\n<div>0,37</div>\r\n<div>0,44</div>\r\n<div>0,50</div>\r\n<div>0,56</div>\r\n<div>0,62</div>\r\n<div>0,75</div></td>\r\n<td valign="top" width="142">\r\n<div>0,68</div>\r\n<div>0,81</div>\r\n<div>0,97</div>\r\n<div>1,10</div>\r\n<div>1,23</div>\r\n<div>1,36</div>\r\n<div>1,65</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="170">\r\n<div>1,0</div>\r\n<div>1,2</div>\r\n<div>1,4</div>\r\n<div>1,5</div>\r\n<div>1,6</div>\r\n<div>1,8</div>\r\n<div>2,0</div></td>\r\n<td width="132">\r\n<div>0,3</div></td>\r\n<td valign="top" width="132">\r\n<div>1,22</div>\r\n<div>1,40</div>\r\n<div>1,59</div>\r\n<div>1,68</div>\r\n<div>1,78</div>\r\n<div>1,95</div>\r\n<div>2,15</div></td>\r\n<td valign="top" width="142">\r\n<div>2,63</div>\r\n<div>3,0