50</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="170">\r\n<div>6,0</div></td>\r\n<td valign="top" width="132">\r\n<div>1,5</div></td>\r\n<td valign="top" width="132">\r\n<div>35,10</div></td>\r\n<td valign="top" width="142">\r\n<div>77,22</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="170">\r\n<div>7,0</div></td>\r\n<td valign="top" width="132">\r\n<div>1,0</div></td>\r\n<td valign="top" width="132">\r\n<div>24,90</div></td>\r\n<td valign="top" width="142">\r\n<div>54,80</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="170">\r\n<div>8,0</div></td>\r\n<td valign="top" width="132">\r\n<div>1,0</div></td>\r\n<td valign="top" width="132">\r\n<div>28,26</div></td>\r\n<td valign="top" width="142">\r\n<div>62,17</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="170">\r\n<div>8,0</div></td>\r\n<td valign="top" width="132">\r\n<div>1,5</div></td>\r\n<td valign="top" width="132">\r\n<div>44,50</div></td>\r\n<td valign="top" width="142">\r\n<div>97,90</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="170">\r\n<div>8,0</div></td>\r\n<td valign="top" width="132">\r\n<div>2,0</div></td>\r\n<td valign="top" width="132">\r\n<div>62,40</div></td>\r\n<td valign="top" width="142">\r\n<div>137,30</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="170">\r\n<div>9,0</div></td>\r\n<td valign="top" width="132">\r\n<div>1,0</div></td>\r\n<td valign="top" width="132">\r\n<div>31,40</div></td>\r\n<td valign="top" width="142">\r\n<div>69,08</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="170">\r\n<div>9,0</div></td>\r\n<td valign="top" width="132">\r\n<div>1,5</div></td>\r\n<td valign="top" width="132">\r\n<div>49,10</div></td>\r\n<td valign="top" width="142">\r\n<div>108,00</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="170">\r\n<div>10,0</div></td>\r\n<td valign="top" width="132">\r\n<div>1,0</div></td>\r\n<td valign="top" width="132">\r\n<div>34,54</div></td>\r\n<td valign="top" width="142">\r\n<div>76,00</div></td>\r\n</tr>\r\n<tr>\r\n<td