\n</tr>\r\n<tr>\r\n<td>\r\nГОСТ 27575-87</td>\r\n<td>\r\nКостюмы мужские для защиты от общих производственных загрязнений механических воздействий. Технические условия</td>\r\n</tr>\r\n<tr>\r\n<td>\r\nОСТ 6-05-423-76</td>\r\n<td>\r\nДиэлектрики твердые. Пленки из высокомолекулярных соединений. Методы электрических испытаний</td>\r\n</tr>\r\n<tr>\r\n<td>\r\nОСТ 17 635-87</td>\r\n<td>\r\nУборы головные. Общие технические условия</td>\r\n</tr>\r\n<tr>\r\n<td>\r\nТУ 6-01-956-86</td>\r\n<td>\r\nПерхлорэтилен технический</td>\r\n</tr>\r\n<tr>\r\n<td>\r\nТУ 6-10-661-86</td>\r\n<td>\r\nПигменты кадмиевые и кобальт фиолетовый темный для окраски пластических масс</td>\r\n</tr>\r\n<tr>\r\n<td>\r\nТУ 6-10-1320-77</td>\r\n<td>\r\nПигменты для художественных и художественно-оформительских работ</td>\r\n</tr>\r\n<tr>\r\n<td>\r\nМУ 2246 - 80</td>\r\n<td>\r\nМетодические указания на метод определения фтористого водорода в воздухе производственных помещений</td>\r\n</tr>\r\n<tr>\r\n<td>\r\nМУ 1699-77</td>\r\n<td>\r\nМетодические указания на фотометрическое определение фтор органических соединений в воздухе</td>\r\n</tr>\r\n<tr>\r\n<td>\r\nМУ 2509-83</td>\r\n<td>\r\nМетодические указания на метод определения окиси углерода в воздухе</td>\r\n</tr>\r\n</tbody>\r\n</table>', 'пленка из фторопласта ф4-д сырая каландрированная (ту 301-05-49-90)', '', 'inherit', 'closed', 'closed', '', '2757-revision-v1', '', '', '2018-06-14 21:32:25', '2018-06-14 21:32:25', '', 2757, 'ПЛЕНКА ИЗ ФТОРОПЛАСТА-4Д СЫРАЯ КАЛАНДРИРОВАННАЯ\r\nТЕХНИЧЕСКИЕ УСЛОВИЯ\r\nТУ 301-05-49-90\r\nВзамен ОСТ 6-05-405-80\r\nГруппа Л27\r\nОКП 22 4526\r\nОКП 22 4526\r\nСрок действия с 01.08.90 до 01.08.95\r\n\r\nНастоящие технические условия распространяется на пленку из фтороп', 0, 'revision', '', 0);
