INSERT INTO `fttwp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(3793, 1, '2016-06-24 21:33:24', '2016-06-24 21:33:24', 'Рой Планкетт (27-летний ученый и химик) 6 апреля 1938  открыл политетрафторэтилен, или тефлон.\r\n\r\nПолитетрафторэтилен, тефлон или фторопласт-4 (-C2F4-)n - полимер тетрафторэтилена (ПТФЭ - PTFE), пластик, обладающий редкими физическими и химическими свойствами, кроме того широко применятся в разных областях техники и в быту.\r\n\r\nСлово «Тефлон» - зарегистрированная торговая марка компании DuPont. Есть еще непатентованные названия вещества - «политетрафторэтилен» и «фторополимер». В СССР было распространено техническое название материала - фторопласт. В настоящее время оно по прежнему актуально.\r\n\r\n<strong>Фторопласт 4</strong> - фторуглеродный полимер, продукт полимеризации тетрафтрэтилена. Высокая прочность связи атомов фтора и углерода и специфичная структура молекул обуславливают хорошее сочетание химических, физических, электрических, антифрикационных и других свойст, которое невозможно найти ни в каком другом материале.\r\n\r\n<strong>Фторопласт-4 -</strong> полукристалический перфторированный полимер этиленового ряда с температурой плавления около 327 <sup>о</sup>С, выше которой исчезает кристалическая структура и он превращается в аморфный прозрачный материал, не переходящий из высокоэластичного в вазкотекучее состояние даже при температуре разложения (свыше 415<sup>о</sup>С).\r\n\r\nВ связи с этим фторопласт -4 перерабатывается в изделия методом предварительного формования заготовок на холоду с последующим спеканием.\r\n\r\nФторопласт -4 обладает:\r\n<ul>\r\n 	<li style="padding: 2px; list-style-image: url(''/images/checkmark.gif'');">исключительно высокими диалектрическими показателями;</li>\r\n 	<li style="padding: 2px; list-style-image: url(''/images/checkmark.gif'');">низкими заначениями тангенса угла диэлектрических потерь и диэлектрической проницаемости, почти не зависищими от частоты и температуры;</li>\r\n 	<li style="padding: 2px; list-style-image: url(''/images/checkmark.gif'');">исключительно высокой стойкостью к вольтовой дуге;</li>\r\n 	<li style="padding: 2px; list-style-image: url(''/images/checkmark.gif'');">электрической прочностью (при изменении на тонких пленках толщиной 5-20 мкм электрическая прочность достигает 300 МВ/м и более);</li>\r\n 	<li style="padding: 2px; list-style-image: url(''/images/checkmark.gif'');">черезвычайно высокой химической стойкостью, которая объясняется высоким экранирующим эффектом электроотрицательных атомов фтора;</li>\r\n 	<li style="padding: 2px; list-style-image: url(''/images/checkmark.gif'');">стойкостью ко всем минеральным и органическим кислотам, щелочам, органическим растворителям, газам и другим агресивным средам. Разрушение материала наблюдается лишь при действии расплавленнных щелочных металлов.</li>\r\n 	<li style="padding: 2px; list-style-image: url(''/images/checkmark.gif'');">способностью не смачиваться водой;</li>\r\n 	<li style="padding: 2px; list-style-image: url(''/images/checkmark.gif'');">высокими антифрикационными свойствами, исключительно низким коэффициентом трения.</li>\r\n</ul>\r\nБлагодаря высокой тепло-, морозо-, и химической стойкости, антифрикационным, антиадгезионным и исключительным диэлектрическим свойствам фторопласт считают высокотехнологичным пластиком, который широко применяется:\r\n<ul>\r\n 	<li style="padding: 2px; list-style-image: url(''/images/checkmark.gif'');">как антикоррозионный материал - фторопласт применяется в химической промышленности для изготовления аппаратов, теплообменников, насосов, труб, клапанов, облицовочной плитки, сальниковых набивок и др. Использование фторопласта-4 в химических аппаратах в качестве труб, уплотнений, прокладок способствует получению продуктов высокой степени чистоты;</li>\r\n 	<li style="padding: 2px; list-style-image: url(''/images/checkmark.gif'');">как диэлектрик - фторопласт применяется в электротехнике, электронике;</li>\r\n 	<li style="padding: 2px; list-style-image: url(''/images/checkmark.gif'');">как материал для изготовления уплотнителей и подшипников скольжения - в машиностроении в чистом и наполненом виде фторопласт применяется для изготовления деталей машин и аппаратов, подшипников, работающих без смазки в коррозионных средах, в виде уплотнений в компресорах, кранах и др. оборудовании;</li>\r\n 	<li style="padding: 2px; list-style-image: url(''/images/checkmark.gif'');">в производстве клейких и красящих веществ - для защиты оборудования от загрязнений;</li>\r\n 	<li style="padding: 2px; list-style-image: url(''/images/checkmark.gif'');">фторопласт также применяется в пищевой промышленности (облицовка валов, покрытие форм, уплотнение оборудования);</li>\r\n 	<li style="padding: 2px; list-style-image: url(''/images/checkmark.gif'');">фторопласт также применяетсяв медицине * протезы и трансплантанты, емкости , держатели протезов и т.д.).</li>\r\n</ul>', 'О фторопласте-4', '', 'publish', 'open', 'open', '', '%d0%be-%d1%84%d1%82%d0%be%d1%80%d0%be%d0%bf%d0%bb%d0%b0%d1%81%d1%82%d0%b5-4', '', '', '2018-06-24 22:10:04', '2018-06-24 22:10:04', '', 0, 'Рой Планкетт (27-летний ученый и химик) 6 апреля 1938  открыл политетрафторэтилен, или тефлон.\r\n\r\nПолитетрафторэтилен, тефлон или фторопласт-4 (-C2F4-)n - полимер тетрафторэтилена (ПТФЭ - PTFE), пластик, обладающий редкими физическими и химическими свойст', 0, 'post', '', 0),
