r\n<td width="76"></td>\r\n<td width="54"></td>\r\n<td width="81"></td>\r\n<td valign="top" width="54"></td>\r\n<td valign="top" width="68"></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="66"></td>\r\n<td valign="top" width="67"></td>\r\n<td valign="top" width="75"></td>\r\n<td valign="top" width="45"></td>\r\n<td valign="top" width="76"></td>\r\n<td width="76"></td>\r\n<td width="54"></td>\r\n<td width="81"></td>\r\n<td valign="top" width="54"></td>\r\n<td valign="top" width="68"></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="66"></td>\r\n<td valign="top" width="67"></td>\r\n<td valign="top" width="75"></td>\r\n<td valign="top" width="45"></td>\r\n<td valign="top" width="76"></td>\r\n<td width="76"></td>\r\n<td width="54"></td>\r\n<td width="81"></td>\r\n<td valign="top" width="54"></td>\r\n<td valign="top" width="68"></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="66"></td>\r\n<td valign="top" width="67"></td>\r\n<td valign="top" width="75"></td>\r\n<td valign="top" width="45"></td>\r\n<td valign="top" width="76"></td>\r\n<td width="76"></td>\r\n<td width="54"></td>\r\n<td width="81"></td>\r\n<td valign="top" width="54"></td>\r\n<td valign="top" width="68"></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="66"></td>\r\n<td valign="top" width="67"></td>\r\n<td valign="top" width="75"></td>\r\n<td valign="top" width="45"></td>\r\n<td valign="top" width="76"></td>\r\n<td width="76"></td>\r\n<td width="54"></td>\r\n<td width="81"></td>\r\n<td valign="top" width="54"></td>\r\n<td valign="top" width="68"></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="66"></td>\r\n<td valign="top" width="67"></td>\r\n<td valign="top" width="75"></td>\r\n<td valign="top" width="45"></td>\r\n<td valign="top" width="76"></td>\r\n<td width="76"></td>\r\n<td width="54"></td>\r\n<td width="81"></td>\r\n<td valign="top" width="54"></td>\r\n<td valign="top" width="68"></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="66"></td>\r\n<td valign="top" width="67"></td>\r\n<td valign="top" width="75"></td>\r\n<td valign="top" width="45"></td>\r\n<td valign="top" width="76"></td>\r\n<td width="76"></td>\r\n<td width="54"></td>\r\n<td width="81"></td>\r\n<td valign="top" width="54"></td>\r\n<td valign="top" width="68"></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="66"></td>\r\n<td valign="top" width="67"></td>\r\n<td valign="top" width="75"></td>\r\n<td valign="top" width="45"></td>\r\n<td valign="top" width="76"></td>\r\n<td width="76"></td>\r\n<td width="54"></td>\r\n<td width="81"></td>\r\n<td valign="top" width="54"></td>\r\n<td valign="top" width="68"></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="66"></td>\r\n<td valign="top" width="67"></td>\r\n<td valign="top" width="75"></td>\r\n<td valign="top" width="45"></td>\r\n<td valign="top" width="76"></td>\r\n<td width="76"></td>\r\n<td width="54"></td>\r\n<td width="81"></td>\r\n<td valign="top" width="54"></td>\r\n<td valign="top" width="68"></td>\r\n</tr>\r\n</tbody>\r\n</table>', 'Детали из фторопластовых заготовок', '', 'inherit', 'closed', 'closed', '', '2761-revision-v1', '', '', '2018-06-24 21:47:14', '2018-06-24 21:47:14', '', 2761, 'Настоящие технические условия распространяются на детали из фторопласта (далее детали), изготовленные методом механической обработки фторопластовых заготовок.\r\n\r\nЗаготовки изготавливаются из фторопласта-4, фторопласта-4 модифицированного, фторопласта-4А и', 0, 'revision', '', 0);
INSERT INTO `fttwp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(3808, 1, '2018-04-11 18:24:36', '2018-04-11 18:24:36', '<div>Для повышения твердости, теплопроводности, стойкости к истиранию, снижения деформации под нагрузкой и коэффициента термического расширения к фторопласту-4 добавляют различные наполнители, выдерживающие его температуру переработки (360°С).</div>\r\n<div>\r\n\r\nНаполненые композиции на основе фторопласта-4 используются главным образом в качестве антифрикационных материалов для изготовления деталей подшипников, поршневых колец, используемых в компрессорах; прокладок и уплотнений в жестких условиях эксплуатации, седел, диафрагм вентилей, сальниковых колец и других изделий, применяемых в машиностроении, химической промышленности и других отраслях.\r\n\r\nВведение наполнителей, как правило, снижает разрушающее напряжение при растяжении, относительное удлинение при разрыве, ударопрочность, увеличивает модуль упругости (особеннно стекловолокно с дисульфидом молибдена и бронза), прочность на сжатие.\r\n\r\nИзносостойкость наполненных композиций значительно зависит от типа наполнителя: бронза увеличивает износостойкость в 450 раз, никель - в 260, медь - только в 22 раза, порошкообразный алюминий снижает ее.\r\n\r\nНаибольшей износостойкостью отличаются композициии фторополаста-4 с коксом, искуственным графитом, дисульфида молибдена, нитридом бора, бронзой. Выбор указанных наполнителей и степень наполнения зависят от назначения готового изделия.\r\n\r\nНаиболее широко применяется композиция с коксом и композиция с порошкообразной бронзой, улучшающая теплопроводность и механические свойства фторопласта-4. Введение в Ф-4 до 15-25% наполнителя повышает твердость композиций в 1,5-1,8 раза, при большем содержании наполнителя твердость композиций понижается.\r\nКомпозиции на основе фторопласта-4 можно применять в качестве материала подшипников, колец, прокладок, деталей, клапанов и других изделий в тех отраслях промышленности, где требуется теплостойкость и химическая стойкость.\r\n\r\nВ настоящее время применяются следующие неорганические наполнители:\r\n<ul>\r\n 	<li>измельченное стекловолокно (С);</li>\r\n 	<li>молотый кокс (К);</li>\r\n 	<li>графит (Г);</li>\r\n 	<li>двусернистый молибден (М);</li>\r\n 	<li>нитрид бора (НБ) или кобальт синий (КС);</li>\r\n 	<li>безводная окись алюминия (Аl);</li>\r\n 	<li>порошки меди, бронзы и никеля и др.</li>\r\n</ul>\r\nПредприятием изготавливаются заготовки антифрикционного назначения на основе фторопласта-4 с различными наполнителями, а именно:\r\n<ul>\r\n 	<li>Ф4К20 (ТУ 6-05-1413-76 добавка 20% кокса);</li>\r\n 	<li>Ф4К15М5 (ТУ 6-05-1413-76 добавка 15% кокса и 5% дисульфида молибдена);</li>\r\n 	<li>Ф4С15 (ТУ 6-05-1413-76 добавка 15% стекловолокна);</li>\r\n 	<li>Ф4С15М5 (ТУ 6-05-1413-76 добавка 15% стекловолокна и 5% дисульфида молибдена);</li>\r\n 	<li>Ф4К15УВ5 (ТУ 6-05-041-781-84 добавка 15% кокса и 5% углеродистого волокна);</li>\r\n 	<li>Ф4КС2 (ТУ 3O1-05-109-91 добавка 2% кобальта синего);</li>\r\n 	<li>Ф4М5 (ТУ 3O1-05-109-91) добавка 5% дисульфида молибдена.</li>\r\n</ul>\r\n<strong>Материал Ф4К20</strong> по сравнению с фторопластом-4 имеет в 600 раз большую износостойкость и на 30% выше напряжение при 10%-ной деформации сжатия в диапазоне температур от -60 до +250<sup>о</sup>С. Материал Ф4К20 наиболее универсален по примененю. Он рекомендуется для изготовления уплотнительных изделий подвижных соединений (поршневые кольца) и изделий антифрикационного назначения.Поршневые кольца компресоров, изготавленные из Ф4К20, позволяют перевести компрессоры на работу без смазуки цилиндров, что устраняет загрязнение промышленные газы маслом. Применение композиции Ф4К20 для изготовления уплотнительных манжет ограничено  вследствии относитеольно низкой его эластичности. материал Ф4К20 пригоден для работы в условиях высокого вакуума в среде углеводородных газов газов, сухого воздуха, жидких углеводородов, растворителей. Композиции с графитом и углем стойки и истиранию. Эти композиции особенно пригодны как материал сухих подшипников, применяемых при низких температурах.\r\n\r\n<strong>Материал Ф4С15</strong> легко перерабатывается, стоек к любым агресивнм средам, хорошо работает в среде сухих агресивных газов. Добавление измельченного стекла в Ф-4 значительно уменьшает его текучесть (ползучесть). По сравнению с материалом Ф4К20 фторополаст с добавкой стеклопорошка более эластичен. Эта композиция применяется для изготовления различного рода подшипников и других изделий при повышенных требованиях к химической стойкости материала. Еще одно удивительное свойство этого материала возможно к использованию: высокая статические свойства композиции позволяют использовать его как проводник (электрод) для накопления заряда проходящего через проводник материала (жидкости).\r\n\r\nДобавка 5% дисульфида молибдена в композиции Ф4К20 и Ф4С15 повышает износостойкость композитовв 1,6 раза и снижает коэффициент трения в 1,2 раза. Данные материалы (<strong>Ф4С15М5 и Ф4К15М5</strong>) рекомендуются к использованию в условиях влажных газов, в том числе с наличием конденсата.\r\n\r\nМалонаполненные композиции марок <strong>Ф4КС2 и Ф4С5</strong> практически не отличаются по физико-механическим и химическим свойствам от свойств ненаполненнго фторопласта-4. Введение легирующих добавок кобальта синего и дисульфида молибдена заменто увеличиваеь износостойкость. Материалы Ф4КС2 и Ф4М5 пригодны для изготовления подвижных малонагруженных деталей антифрикационного назначения, работающих в паре с резинами, алюминиевыми сплавами и бронзой. Материалы имеют высокую эластичность и повышенную скорость приработки.\r\nразрыве, а также хорошие электрические свойства. Эти свойства вместе с химической стойкостью позволяют широко применять этот материал в химической промышленности.\r\n\r\nМатериал <strong>Ф4АО10</strong> содершит мелкодисперстный порошок окиси алюминия и придает материалу стойкость к воздействию электрической дуги при коронном разряде. Детали из этой фторопластовой композиции используются как изоляторы в коммутирующих приборах.\r\n\r\n</div>', 'Фторопластовые композиции', '', 'publish', 'open', 'open', '', 'compounds', '', '', '2018-06-24 22:13:12', '2018-06-24 22:13:12', '', 0, '<div>Для повышения твердости, теплопроводности, стойкости к истиранию, снижения деформации под нагрузкой и коэффициента термического расширения к фторопласту-4 добавляют различные наполнители, выдерживающие его температуру переработки (360°С).</div>\r\n<div', 0, 'post', '', 0),
