n="top" width="85">0.45 МПа</td>\r\n<td valign="top" width="114">°С</td>\r\n<td valign="top" width="161">160</td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="265">Max температура кратковременной эксплуатации</td>\r\n<td valign="top" width="104">-</td>\r\n<td valign="top" width="85"></td>\r\n<td valign="top" width="114">°С</td>\r\n<td valign="top" width="161">140</td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="265">Max температура непрерывной эксплуатации</td>\r\n<td valign="top" width="104">-</td>\r\n<td valign="top" width="85">5000 часов</td>\r\n<td valign="top" width="114">°С</td>\r\n<td valign="top" width="161">90</td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="265">Min температура кратковременной эксплуатации</td>\r\n<td valign="top" width="104">-</td>\r\n<td valign="top" width="85"></td>\r\n<td valign="top" width="114">°С</td>\r\n<td valign="top" width="161">-</td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="265">Min температура непрерывной эксплуатации</td>\r\n<td valign="top" width="104">-</td>\r\n<td valign="top" width="85"></td>\r\n<td valign="top" width="114">°С</td>\r\n<td valign="top" width="161">-</td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="265">Коэффициент/ линейного расширения (TMA)</td>\r\n<td valign="top" width="104">ISO 11359-2:1999</td>\r\n<td valign="top" width="85">23 °С - 55 °С</td>\r\n<td valign="top" width="114">1/°С</td>\r\n<td valign="top" width="161">9.2 x 105</td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="265">Коэффициент теплопроводности</td>\r\n<td valign="top" width="104">ISO 8301:1991</td>\r\n<td valign="top" width="85">Средняя T = 20 °С</td>\r\n<td valign="top" width="114">Ватт/м. °С</td>\r\n<td valign="top" width="161">0.31</td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="265">Воспламеняемость</td>\r\n<td valign="top" width="104">IEC 60695-1 1 -10:2003-08</td>\r\n<td valign="top" width="85"></td>\r\n<td valign="top" width="114">-</td>\r\n<td valign="top" width="161">HB</td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="265">ЭЛЕКТРИЧЕСКИЕ</td>\r\n<td valign="top" width="104"></td>\r\n<td valign="top" width="85"></td>\r\n<td valign="top" width="114"></td>\r\n<td valign="top" width="161"></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="265">Диэлектрическая проницаемость</td>\r\n<td valign="top" width="104">IEC 60250:1969-01</td>\r\n<td valign="top" width="85">1 МГц</td>\r\n<td valign="top" width="114">-</td>\r\n<td valign="top" width="161">3.8</td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="265">Диэлектрическая проницаемость (низкая частота)</td>\r\n<td valign="top" width="104"></td>\r\n<td valign="top" width="85">100 Гц</td>\r\n<td valign="top" width="114">-</td>\r\n<td valign="top" width="161">-</td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="265">Фактор рассеивания</td>\r\n<td valign="top" width="104">IEC 60250:1969-01</td>\r\n<td valign="top" width="85">100 Гц</td>\r\n<td valign="top" width="114">Гц</td>\r\n<td valign="top" width="161">0.005</td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="265">Диэлектрическая прочность</td>\r\n<td valign="top" width="104">IEC 60243-1:1998-01</td>\r\n<td valign="top" width="85"></td>\r\n<td valign="top" width="114">кВ/мм</td>\r\n<td valign="top" width="161">16.5</td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="265">Удельное электрическое сопротивление</td>\r\n<td valign="top" width="104">IEC 60093:1980-01</td>\r\n<td valign="top" width="85"></td>\r\n<td valign="top" width="114">Ом.м</td>\r\n<td valign="top" width="161">1 x 1013</td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="265">Удельное поверхн. электрич. Сопротивление</td>\r\n<td valign="top" width="104">IEC 60093:1980-01</td>\r\n<td valign="top" width="85"></td>\r\n<td valign="top" width="114">Ом</td>\r\n<td valign="top" width="161">1 x 1013</td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="265">Средний индекс трекинга</td>\r\n<td valign="top" width="104">IEC 60112:2003-01</td>\r\n<td valign="top" width="85"></td>\r\n<td valign="top" width="114">CTI</td>\r\n<td valign="top" width="161">600</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<div>\r\n<h2>Капролон ПА-6 и его модификации</h2>\r\n<div></div>\r\n<div><u>Модификации КАПРОЛОНА:</u></div>\r\n<div>КАПРОЛОН МАСЛОНАПОЛНЕННЫЙ - самосмазывающийся материал. Коэффициент трения в 2,5-3 раза ниже, чем у капролона; абразивный износ - в 4- 5 раз меньше (подшипники скольжения служат в 4- 5 раз дольше III). Пониженное водопоглащение и повышенная термостойкость.</div>\r\n<div>КАПРОЛОН С ДИСУЛЬФИДОМ МОЛИБДЕНА - самосмазывающийся материал. Твердость, прочность при растяжении, сжатии, изгибе выше, чем у капролона. Абразивный износ - ниже в 2 раза. Повышенная термостойкость.</div>\r\n<div>КАПРОЛОН С УФ И ТЕРМОСТАБИЛИЗАТОРАМИ. Максимальная температура непрерывной\r\nэксплуатации на 15 град выше, чем у капролона (+115 0С, 5000 час); максимальная температура кратковременной эксплуатации составляет +180 0С (у капролона +1700С град)</div>\r\n<div>Цвета модификаций КАПРОЛОНА:     натуральный (светло желтый), желтый, черный, синий, зеленый, красный.</div>\r\n<div></div>\r\n<div>ПРИМЕНЕНИЕ  В ПРОМЫШЛЕННОСТИ МОДИФИКАЦИЙ КАПРОЛОНА:</div>\r\n<div>Нефтехимический комплекс • Аэрокосмическая промышленность • Железнодорожный транспорт • Пищевое оборудование • Упаковочная промышленность •  Фармацевтическая промышленность •  Сталелитейные заводы • Горнодобывающая промышленность • Производство кранов • Конвейеры</div>\r\n<div></div>\r\n<div>Типичные примеры деталей из модификаций капролона:</div>\r\n<div>Ролики • Втулки • Шкивы • Зубчатые передачи • Подшипники • Направляющие • Разделочные доски • Прокладки • Зажимы  • Механизмы, использующие принцип действия плуга • Оправки • Червячные передачи • Звездочки • Изоляторы</div>\r\n<div></div>\r\n<table>\r\n<tbody>\r\n<tr>\r\n<td valign="top" width="175">\r\n<div>СВОЙСТВА</div></td>\r\n<td valign="top" width="96">\r\n<div>ПА-6</div></td>\r\n<td valign="top" width="120">\r\n<div>ПА-6 маслонаполненный</div></td>\r\n<td valign="top" width="108">\r\n<div>ПА-6+МоS</div></td>\r\n<td valign="top" width="158">\r\n<div>ПА-6 термостабилизированный</div></td>\r\n</tr>\r\n<tr>\r\n<td colspan="5" valign="top" width="657">\r\n<div>Механические</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="175">\r\n<div>Напряжение при растяжении, мПа</div></td>\r\n<td valign="top" width="96">\r\n<div>80</div></td>\r\n<td valign="top" width="120">\r\n<div>70-75</div></td>\r\n<td valign="top" width="108">\r\n<div>80-90</div></td>\r\n<td valign="top" width="158">\r\n<div>75-85</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="175">\r\n<div>Е-модуль, МПа</div></td>\r\n<td valign="top" width="96">\r\n<div>4000</div></td>\r\n<td valign="top" width="120">\r\n<div>4000</div></td>\r\n<td valign="top" width="108">\r\n<div>4100</div></td>\r\n<td valign="top" width="158">\r\n<div>4000</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="175">\r\n<div>Удлинение при разрыве, %</div></td>\r\n<td valign="top" width="96">\r\n<div>&gt;20</div></td>\r\n<td valign="top" width="120">\r\n<div>&gt;30</div></td>\r\n<td valign="top" width="108">\r\n<div>&gt;20</div></td>\r\n<td valign="top" width="158">\r\n<div>&gt;25</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="175">\r\n<div>Максимальное напряжение при сжатии, МПа</div></td>\r\n<td valign="top" width="96">\r\n<div>95</div></td>\r\n<td valign="top" width="120">\r\n<div>90-100</div></td>\r\n<td valign="top" width="108">\r\n<div>100-110</div></td>\r\n<td valign="top" width="158">\r\n<div>90-100</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="175">\r\n<div>Модуль при сжатии, МПа</div></td>\r\n<td valign="top" width="96">\r\n<div>2700</div></td>\r\n<td valign="top" width="120">\r\n<div>2500</div></td>\r\n<td valign="top" width="108">\r\n<div>3000</div></td>\r\n<td valign="top" width="158">\r\n<div>2700</div></td>\r\n</tr>\r\n<tr>\r\n<td valign="top" width="175">\r\n<div>Изгибающее напряжение, МПа</div></td>\r\n<td valign="top" width="96">\r\n<div>105</div></td>\r\n<td valign="top" width="120">\r\n<div>95-105</div></td>\r\n<td valign="to