>\r\n<tr>\r\n<td>Пластина фторопластовая</td>\r\n<td>25</td>\r\n<td>4000</td>\r\n</tr>\r\n<tr>\r\n<td>Пластина фторопластовая</td>\r\n<td>26</td>\r\n<td>4160</td>\r\n</tr>\r\n<tr>\r\n<td>Пластина фторопластовая</td>\r\n<td>27</td>\r\n<td>4320</td>\r\n</tr>\r\n<tr>\r\n<td>Пластина фторопластовая</td>\r\n<td>28</td>\r\n<td>4480</td>\r\n</tr>\r\n<tr>\r\n<td>Пластина фторопластовая</td>\r\n<td>30</td>\r\n<td>4800</td>\r\n</tr>\r\n<tr>\r\n<td>Пластина фторопластовая</td>\r\n<td>32</td>\r\n<td>5120</td>\r\n</tr>\r\n<tr>\r\n<td>Пластина фторопластовая</td>\r\n<td>33</td>\r\n<td>5280</td>\r\n</tr>\r\n<tr>\r\n<td>Пластина фторопластовая</td>\r\n<td>35</td>\r\n<td>5600</td>\r\n</tr>\r\n<tr>\r\n<td>Пластина фторопластовая</td>\r\n<td>38</td>\r\n<td>6080</td>\r\n</tr>\r\n<tr>\r\n<td>Пластина фторопластовая</td>\r\n<td>40</td>\r\n<td>6400</td>\r\n</tr>\r\n<tr>\r\n<td>Пластина фторопластовая</td>\r\n<td style="text-align: center;" rowspan="5" valign="top">300х300</td>\r\n<td>43</td>\r\n<td>6880</td>\r\n</tr>\r\n<tr>\r\n<td>Пластина фторопластовая</td>\r\n<td>45</td>\r\n<td>7200</td>\r\n</tr>\r\n<tr>\r\n<td>Пластина фторопластовая</td>\r\n<td>50</td>\r\n<td>8000</td>\r\n</tr>\r\n<tr>\r\n<td>Пластина фторопластовая</td>\r\n<td>55</td>\r\n<td>8800</td>\r\n</tr>\r\n<tr>\r\n<td>Пластина фторопластовая</td>\r\n<td>60</td>\r\n<td>9600</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\nПримечание:\r\n\r\nцены на пластины вы можете уточнить через онлайн-чат, по телефону или эл.почте;\r\nнепрямолинейность пластин по длине и ширине +/-5мм, разнотолщинность - от +/-1,0 до +/-2,0мм в зависимости от толщины;\r\nкоробление пластин - в пределах требований ТУ\r\nвозможна поставка пластин из композиции Ф4К20 , при заказе через сайт просьба указывать наполнитель через коэффициент;\r\nпри заказе через форму размещенную на нашем сайте количество пластин указывается в штуках;\r\nцены для организаций РФ.', 'Пластины фторопластовые прессованные', 'Изготавливаются по:\r\n\r\nТУ 6-05-810-88 (фторопласт-4)\r\nТУ 6-05-1413-76 (Ф4К20)\r\n\r\nПластины из фторопласта-4 и композиций предназначены для изготовления уплотнений и электроизоляционных, антифрикционных и химически стойких элементов в конструкциях для различных отраслей промышленности. Благодаря широкому температурному диапазону эксплуатации и химической стойкости фторопластовые пластины широко используется в качестве заготовок для изготовления прокладок, манжет, вкладышей, подшипников, фильтров и мембран.', 'publish', 'open', 'closed', '', 'plates', '', '', '2018-08-08 23:36:16', '2018-08-08 23:36:16', '', 0, 'https://ftoroplast.com.ru/?post_type=product&#038;p=4067', 0, 'product', '', 0);
