(318, 318, 'product_cat', 'Заготовки из фторопласта-4, композиционных материалов и капролона.', 0, 13),
(319, 319, 'product_cat', 'ЗАО “Фторопластовые технологии” производит широкий ассортимент стандартных заготовок и расходных материалов из фторопласта: пластины, стержни, втулки, лист строганный, трубка Ф-4Д, лента ФУМ и др.', 318, 8),
(320, 320, 'product_cat', 'Заготовки из фторопластовых композиций. ', 318, 3),
(321, 321, 'product_cat', 'Заготовки из капролона.', 318, 2),
(322, 322, 'product_cat', 'Сверхвысокомолекулярный полиэтилен РЕ-1000 (РЕ-UHMW).\r\n\r\nОчень высокие триботехнические характеристики. Применяется для изготовления деталей насосов в химической промышленности, шнеков, роликов качения, подшипников, зубчатых колес, направляющих цепей, тросовых блоков, конвейерных направляющих, опорных втулок, скребков, лопаток.', 318, 4),
(323, 323, 'product_cat', 'Полиэтилен высокой плотности (PE-HD)\r\nПрименяется для изготовления ненагруженных деталей пищевого, химического, сельскохозяйственного, транспортного и др. оборудования.', 318, 2),
(324, 324, 'product_cat', 'Изделия из фторопласта и композиционных материалов по чертежам заказчика.', 0, 15),
(325, 325, 'product_cat', 'Фторопластовые ленты и профили.', 0, 5),
(326, 326, 'product_cat', 'Наличие на нашем предприятии аккредитованной лаборатории позволяет изготавливать заготовки по ОСТ В-6-05-5022-81 — 1 и 2 сорта, а также заготовки по ТУ 6-05-810-88 – высший и 1 сорт.', 0, 1),
(327, 327, 'product_cat', 'ФУМ', 0, 2);
